WordHunterWoW_QuestEN = WordHunterWoW_QuestEN or {}
WordHunterWoW_QuestEN[40728] = { title = "Wormgut's Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[40729] = { title = "The New Blood", description = "It is time to begin the ritual, warlock. Be prepared, for the summoning we perform today will be more challenging than any you have known or seen before.\n\nAre you ready?", objectives = "Complete the summoning ritual with the Council of the Black Harvest in the Circle of Wills in Dalaran.", completion = "Calydus sorry we not save your friends, but maybe they survive if we hurry.\n\nJagganoth torture them, yes, but he likes to keep victims alive... mostly." }
WordHunterWoW_QuestEN[40730] = { title = "Redistribution", description = "I would imagine you thought I would simply have wine to deliver.\n\n<Deline chuckles.>\n\nIf it were that easy, his people would not be starving.\n\n<Her expression becomes serious.>\n\nThese... loyalists, shall we say, enjoy abundance. They dance to the Magistrix's whims and so they have all that they need.\n\nThere is no Arcwine shortage. The Magistrix created one to keep us in line.\n\nThey will not miss a few bottles. They have plenty.\n\nSearch the square and bring as much as you can carry back.", objectives = "Acquire 20 Bottles of Arcwine.", progress = "Did you find enough?", completion = "I will see that this gets back to our friend safely. Good work." }
WordHunterWoW_QuestEN[40731] = { title = "The Heart of the Dreadscar", description = "Friend has the artifact! Now Jagganoth does not stand a chance!\n\nQuickly, you must go back to Dreadscar Rift! You may still be able to save your friends from Jagganoth's vengeance.\n\nIf you take the heart of the overlord, his army will be yours to command!", objectives = "Defeat Jagganoth and take his heart to the Seat of the Overlord in Dreadscar Rift.", completion = "The cruel Jagganoth is defeated!\n\nFriend is the new Overlord of the Dreadscar! \n\nThis place will be friend's new home. With the Dreadscar under your control, you can come and go as you please!" }
WordHunterWoW_QuestEN[40732] = { title = "FLAG - Reaves Repair Module", description = "", objectives = "" }
WordHunterWoW_QuestEN[40733] = { title = "FLAG - Reaves Failure Detection Module", description = "", objectives = "" }
WordHunterWoW_QuestEN[40734] = { title = "FLAG - Reaves Fireworks Module", description = "", objectives = "" }
WordHunterWoW_QuestEN[40735] = { title = "FLAG - Reaves Snack Distribution Module", description = "", objectives = "" }
WordHunterWoW_QuestEN[40736] = { title = "FLAG - Reaves Bling Module", description = "", objectives = "" }
WordHunterWoW_QuestEN[40737] = { title = "FLAG - Reaves Piloted Combat Module", description = "", objectives = "" }
WordHunterWoW_QuestEN[40738] = { title = "FLAG - Reaves Wormhole Generator Module", description = "", objectives = "" }
WordHunterWoW_QuestEN[40739] = { title = "FLAG - Reaves Thermal Anvil Module", description = "", objectives = "" }
WordHunterWoW_QuestEN[40740] = { title = "The Dead and the Damned", description = "<A powerful mind again touches your thoughts.>\n\nGorelix the Fleshripper is a monstrous demon. The butcher of a thousand worlds, he has exterminated countless races with his axe, the Maw of the Damned.\n\nA group of Ebon Blade was dispatched to slay him but they have gone missing. You will succeed where they failed.\n\nYou will not be alone in this, I've sent Baron Sliver ahead to assist you.\n\nGo, obtain the Maw of the Damned and ensure that Gorelix is no more.", objectives = "Travel to Dalaran and fly upon Zeomus to Darkstone Isle. While there, travel through the Demon Portal, find Baron Sliver, and obtain the Maw of the Damned.", progress = "It is time to begin, <name>.", completion = "That axe makes me feel uneasy, <name>. Its power is undeniable, but its very essence embodies the eternal hunger.\n\nWe will use it because we must do whatever it takes to win this war. Still, I'd be careful with that weapon if I were you." }
WordHunterWoW_QuestEN[40741] = { title = "In Need of Information", description = "Now that the Commander is dead, we need to find out what they know.\n\nSylessa overheard a conversation suggesting a meeting is about to take place. An informant and one of Commander Elvire's Sentries will exchange very valuable information.\n\nI need you to follow whoever the informant is, and find out what that meeting is about.\n\nYou must not be seen. If you are, the meeting may not take place at all.\n\nNow is the time for discretion, {name}.", objectives = "" }
WordHunterWoW_QuestEN[40742] = { title = "The Elusive Three", description = "Bad news.\n\nWord has started to circulate about a possible infiltration into the city. That was fast, even for our standards.\n\nWe're going to do some damage control. I need you to find three of my best assassins. Start by seeking Cyrille- she resides in the Docks District, acting the part of a Steward.\n\nShe will guide you to the others, and ultimately your target. Commander Elvire.\n\nThat will buy you and Thalyssra some time.", objectives = "" }
WordHunterWoW_QuestEN[40743] = { title = "7.0 DH-Mardum - Small Treasure Chest 011", description = "", objectives = "" }
WordHunterWoW_QuestEN[40744] = { title = "An Ancient Recipe", description = "Suramar is... was... an intellectual's dream.\n\nWe studied everything in there, from alchemy and the arts to the very nature of magic itself. How could we be so foolish as to accept them in?\n\nLook at me, lost in the clouds again when there is much to be done. My work requires some fairly difficult ingredients, {race}. Perhaps you would help me procure them?\n\nI am going to need some harpy talons. Crushed into a powder, they will be a potent reagent.", objectives = "Collect 6 Harpy Talons.", progress = "Do you have what I require, <race>? We don't have much time to spare.", completion = "That should be plenty. Talondust loses its potency fairly quickly, so we must make haste." }
WordHunterWoW_QuestEN[40745] = { title = "Shift Change", description = "This is as good a chance as we are going to get to rescue Verene's daughter.\n\nHere is how this is going to work. \n\nYou are going to wait here for the guard to pass by on their way to their guard shift. Look for something to hide in.\n\n<Silgryn marks a spot on your map.>\n\nYou will know the guard by their bright red armor.\n\nFollow closely, but not so closely that you are seen. It may be necessary to kill the guard when you reach your destination.\n\nThe child's name is Korine. Good luck.", objectives = "Hide in the basket and wait for the guard to appear. Follow the guard to their destination.", progress = "W-who are you?", completion = "I-I thought... they were gonna... *sniff*" }
WordHunterWoW_QuestEN[40746] = { title = "One of the People", description = "It is time for you to enter the city proper, {name}.\n\nI am sending you to my loyal friend Vanthir. I do hope you remember him- I can guarantee that he remembers you.\n\nI will not be able to accompany you, but I must stress that the disguise I have granted you is not impervious. Tread carefully, and avoid those who stare too long.\n\nFarewell for now.", objectives = "Meet with Vanthir in Suramar City.", completion = "Glad you could make it. Your help is sorely needed here." }
WordHunterWoW_QuestEN[40747] = { title = "The Delicate Art of Telemancy", description = "I hadn't the time to gather my instruments before fleeing the palace. I came here to salvage some equipment.\n\nThis old workshop is actually several rooms connected by teleporter pads.\n\nElisande's goons are already scouring the place looking for me, but from here I can alter the teleporter network and keep them moving in circles.\n\nYou go in. I'll monitor your position and ensure the teleporters work normally for you.\n\nFind these two parts and bring them back!", objectives = "Collect the Weathered Telemancy Beacon and Cracked Warpsleeve from Oculeth's Workshop.", progress = "Salvaging the equipment here is necessary if I am to develop a teleporter network for Thalyssra.", completion = "These are in rough shape, but they will suffice." }
WordHunterWoW_QuestEN[40748] = { title = "Network Security", description = "We must lock down the facility. Otherwise my esteemed colleagues from the palace could uncover my secrets, which puts any teleporters I build for you and Thalyssra at risk.\n\n<The inactive attunement device near Oculeth hums to life.>\n\nThis will take us to my secret test chamber beneath the mountain. From there we can begin the lockdown sequence and make our escape!", objectives = "Complete the lockdown sequence in Oculeth's Test Chamber.", completion = "Did we... make it?" }
WordHunterWoW_QuestEN[40749] = { title = "A Token of Remembrance", description = "The flower rests peacefully in your hand, glowing softly.\n\nWhile it doesn't appear to be growing anywhere nearby, there are small bouquets of the flower on some of the memorials around here.\n\nPerhaps laying down some flowers on the remaining graves will ease the gloom.", objectives = "Place 4 Bouquets of Moon Lilies." }
WordHunterWoW_QuestEN[40751] = { title = "Azsuna - Treasure 020 - Olivian Rise", description = "", objectives = "" }
WordHunterWoW_QuestEN[40752] = { title = "Azsuna - Treasure 021 - Oracle", description = "", objectives = "" }
WordHunterWoW_QuestEN[40753] = { title = "Blingtron 6000", description = "", objectives = "While I am programmed for gift distribution, my observations indicate that you are programmed for gift reception.\n\nShall we engage in a mutually-favorable transaction?You will receive:" }
WordHunterWoW_QuestEN[40755] = { title = "Hiding in the Stacks", description = "Magni's information was enlightening. It should prove handy to have a friend who has the ear of a titan.\n\nIt's time to head into Karazhan. Not that I need to remind you, but it can be a dangerous place. There are countless strata of spells woven throughout the tower, and the interactions of the forces within can be... unpredictable. Be on your guard.\n\nI'll join you inside. I need a moment to... gather my thoughts. This place holds a lot of memories for me.", objectives = "Enter Karazhan and search for knowledge of the Pillars of Creation with Khadgar.", progress = "Do you have something for me?", completion = "Not long after you left, the first wave of demons struck. We're holding them at bay... for now.\n\nI'll keep this tome safe until we have a chance to study it.\n\nGood work in there. I should like to delve into the libraries of Karazhan myself one day. At least... I think I would." }
WordHunterWoW_QuestEN[40759] = { title = "7.0 DH-Mardum - Small Treasure Chest 012", description = "", objectives = "" }
WordHunterWoW_QuestEN[40760] = { title = "Emissary", description = "As if things weren't unsettled enough, guests have arrived... the Illidari.\n\nThese demon hunters have been imprisoned since their master's fall at the Black Temple. For the Wardens to release them can only mean the peril is dire indeed.\n\nTheir delegation's leader, Allari \"the Souleater,\" claims Orgimmar faces a hidden threat. I gave them leave to establish a camp within the city... for now.\n\nYou will speak with her at once. Find out whether this threat is credible.", objectives = "Speak with Allari the Souleater.", completion = "<Allari furrows her brow as she speaks.>\n\nYou didn't think the leadership of the Horde could gather in one location and go unnoticed by the Burning Legion, did you?" }
WordHunterWoW_QuestEN[40761] = { title = "Whispers from Oronaar", description = "Ethereals, the Void, a Dark Naaru... I feel they are all connected.\n\nI explored the ruins below while you and Velen were seeking the Crown. There are survivors, {name}.\n\nBroken wander the cluster of buildings to our west- I cannot understand much of what they say but I suspect that their minds are not their own.\n\nIf the Void is to blame, we will need to start our investigation there.\n\nI will conduct my own search in the meantime.", objectives = "Investigate the Ruins of Oronaar.", completion = "Something is very wrong here." }
WordHunterWoW_QuestEN[40762] = { title = "Zealot's Dues", description = "Commander Domitille represents the very essence of the Nightborne's corruption. Abhorrent of power not their own, enamoured with their Grand Magistrix to the point of zealotry, and focused utterly on the destruction of the Moon Guard.\n\nTake her helm to Lothrius as proof of her demise.", objectives = "Take Commander Domitille's Helm to Lothrius Mooncaller.\n\nProvided item:", completion = "I was wondering why she had suddenly gone silent. It is a small comfort to my heart, but a great blow to the remaining forces of the Nightborne. Well done, <name>." }
WordHunterWoW_QuestEN[40763] = { title = "Casual Redistribution", description = "Lately there have been a disturbing array of changes involving our most precious resource, Arcwine. \n\nI imagine Thalyssra has thoroughly educated you about what happens when a Nightborne does not have access to a source of power like Arcwine.\n\nWith the presence of the demons came rationing. There are many who do not have enough to sustain themselves.\n\nBring me as much Arcwine as you can carry. I will see that it gets to the right people.", objectives = "Collect 20 Bottles of Arcwine." }
WordHunterWoW_QuestEN[40764] = { title = "Tracking Quest for Latosius Challenge 1", description = "", objectives = "" }
WordHunterWoW_QuestEN[40765] = { title = "Syrana Tracker", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[40766] = { title = "Charfeather", description = "", objectives = "" }
WordHunterWoW_QuestEN[40767] = { title = "7.0 Suramar - Treasure 001 - Tel'anor Cave - AJB", description = "", objectives = "" }
WordHunterWoW_QuestEN[40768] = { title = "Tracking Quest - W1 - Intro to Illidari Complete", description = "", objectives = "" }
WordHunterWoW_QuestEN[40769] = { title = "Blackroot Idols", description = "The Blackroot are lead by Chieftain Narla.\nI fear that her mind has become twisted beyond reason.\n\nI attempted to make peace with the Blackroot, but I quickly retreated when Drawzle Keen Eye let loose a volley of arrows. I was fortunate enough to escape unharmed.\n\nThis tribe is lost and Narla and Drawzle must be dispatched before the Blackroot spread like a blight. Return their weapons to me as proof of their demise.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Collect Narla's Branch from Chieftain Narla and Drawzle's Bough from Drawzle Keen Eye in the Blackroot Village." }
WordHunterWoW_QuestEN[40770] = { title = "Keeper's Request", description = "The Blackroot have become savage and aggressive. The confluence of energy in this area was simply too much for these furbolgs to handle.\n\nI have tried to soothe their minds, but my efforts have all ended in violence. There is little else that can be done, <race>.\n\nThey must be cut down to protect the neighboring lands.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Slay 8 Blackroot furbolgs in Blackroot Village." }
WordHunterWoW_QuestEN[40771] = { title = "Wild By Nature", description = "Furbolgs often empower totems to harness their natural power and ward off enemies.\n\nUnfortunately, due to the malicious nature of the Blackroot, their totems are tainting any poor creature that comes near them,\n\nWe can't allow others to be corrupted by their totems.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Destroy 4 Blackroot Totems in the Blackroot Village." }
WordHunterWoW_QuestEN[40772] = { title = "7.0 DH-Mardum - Small Treasure Chest 013", description = "", objectives = "" }
WordHunterWoW_QuestEN[40773] = { title = "Bloodshard", description = "", objectives = "" }
WordHunterWoW_QuestEN[40775] = { title = "Trophy Hunting", description = "Dat Hemet Nesingwary think he be such a great hunter. When we ask to join his hunt, he laugh at us and turn us away. We show him who da best hunter really be.\n\nOnly thing, mon, we be needin' your help.\n\nRedtooth be da most dangerous prey in the area. I'd hunt it myself, but those pale creepers be all over da place.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Kill Redtooth and return its head to Mom'zula at the <hunting camp>." }
WordHunterWoW_QuestEN[40776] = { title = "Kazok'thul", description = "A rogue felhunter known as Kazok'thul has been terrorizing Azurewing Repose in Azsuna.\n\nFelhunters feed on arcane energy and it seems that Kazok'thul has been gorging itself on the mana from nearby Azurewing whelps.\n\nTravel to Azurewing Repose and speak with Ardonu to find the last known location of Kazok'thul.\n\nSlay the demon and return here when your mission is complete.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Find and slay Kazok'thul in Azurewing Repose." }
WordHunterWoW_QuestEN[40777] = { title = "Vittles and Bits", description = "I used to travel the world until I fell in with this lot of incompetent hunters. When I found them, they were practically starving to death.\n\nI cooked one meal for them, and somehow became their camp cook.\n\nIf you're going out into the wild, bring me back some animal parts that I can cook up for this lot.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Use Tony Mordain's Cleaver to carve Animal Bits from the wildlife near the <hunting camp>." }
WordHunterWoW_QuestEN[40779] = { title = "We Need Even More Power!", description = "Good new, {race}! I have located another power orb.\n\nI last saw it down by the Nightborne encampment to the southwest. I had to get out of there before their patrols saw me, but it should be no trouble for you, now should it?", objectives = "Find the Charged Power Orb." }
WordHunterWoW_QuestEN[40780] = { title = "Hunting Impaired", description = "<Kalla motions for you to come closer and whispers.>\n\nI do not want Mom to hear, but as you can probably tell by all the wounded, these hunters are not very skilled. They are more likely to twist an ankle than they are to track down a lame deer.\n\nI cannot be everywhere at once. If you come across any of our band in the wilds, please tend to them.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Tend to any of Mom'zula's Hunters that you find outside of the <hunting camp>." }
WordHunterWoW_QuestEN[40781] = { title = "Balance Chosen", description = "", objectives = "You will receive:" }
WordHunterWoW_QuestEN[40782] = { title = "Relief For Parim", description = "The air around these flowers is sweet and crisp.\n\nParim Eversong would welcome the pleasant smell of these flowers.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Collect Fragrant Poppies for Parim Eversong outside of the <hunting camp>." }
WordHunterWoW_QuestEN[40783] = { title = "The Scythe of Elune", description = "I have received word that Tyrande herself has authorized the release of a great artifact, the Scythe of Elune, to aid our cause. Valorn Stillbough has agreed to give up the weapon, which he has kept as part of an investigation into the cursed worgen of Duskwood.\n\nI believe that you, champion, will be our best hope at wielding its power without succumbing to the animal rage that ebbs within. You must go to Duskwood, and take up the scythe against our foes!", objectives = "Meet with Valorn Stillbough in the Twilight Grove in Duskwood.", progress = "The champion arrives. I hope you are prepared for this burden.", completion = "Well met, champion. \n\nAre you ready for the burden you must bear?" }
WordHunterWoW_QuestEN[40784] = { title = "Its Rightful Place", description = "Though it goes against my better judgment, it is Tyrande's wish that the Scythe of Elune be brandished once more against the new Legion threat. It is a small comfort to see it wielded by a keeper of the balance, such as yourself.\n\nKnow that the last time the scythe was wielded, it resulted in great calamity. You must be vigilant to contain the bestial wrath that ebbs within. \n\nWith those words in your heart, take the scythe and bring its fury against our foes. May the light of Elune protect you.", objectives = "Take the Scythe of Elune from Valorn.", progress = "The scythe is yours, <class>.", completion = "Valorn...\n\nThat was.. a Dark Rider!\n\nBut how did they reach us here, under the protection of the grove?" }
WordHunterWoW_QuestEN[40785] = { title = "A Foe of the Dark", description = "I cannot believe the Dark Riders found us here. Long have they hunted the scythe to sate their lust for the artifacts of Azeroth. We thought we would be protected within the grove...\n\nAnd now, Valorn is gone...\n\nYou must become the hunter, {name}. Seek the Dark Riders and recover the scythe. We last encountered them near Manor Mistmantle in Duskwood. Start your search there.\n\nAnd {name}... bring justice to Valorn. The rider must pay.", objectives = "Start your search for the Scythe of Elune at Manor Mistmantle in Duskwood.", completion = "So I was correct, and the Scythe is your quarry.  Know that in order to retrieve it, we must do what no denizen of Duskwood has ever attempted.\n\nWe must hunt the Dark Riders.\n\nI have been tracking them for some time since my encounter with them while hunting down the Wolf Cult.  They are a blight upon these lands, and they hold no right to the artifacts they hoard.\n\nIf we wish to recover this artifact, we will need to find their lair. Fortunately, I may just have the clue we need." }
WordHunterWoW_QuestEN[40786] = { title = "The Smoldering Ember", description = "Cold to the touch when you first reach for it, this ember bursts into flame without warning and snuffs itself just as quickly. As the stone rests in your hand, visions of fire and of dragons dance through your mind, but you can hear conversation taking place in Orgrimmar and the familiar sight of circle portals bubbles to the top.", objectives = "Bring the Smoldering Timewarped Ember to Kiatke in Orgrimmar.", completion = "Yes, another one of these pesky artifacts. The meddling in the timestreams has grown worse of late... or is it that it will grow worse?\n\n<She sighs heavily.>" }
WordHunterWoW_QuestEN[40787] = { title = "The Smoldering Ember", description = "Cold to the touch when you first reach for it, this ember bursts into flame without warning and snuffs itself just as quickly. As the stone rests in your hand, visions of fire and of dragons dance through your mind, but you can hear the hustle and bustle of Stormwind and the familiar sight of circle portals bubbles to the top.", objectives = "Bring the Smoldering Timewarped Ember to Kiatke in Stormwind.", completion = "Yes, another one of these pesky artifacts. The meddling in the timestreams has grown worse of late... or is it that it will grow worse?\n\n<She sighs heavily.>" }
WordHunterWoW_QuestEN[40788] = { title = "Withered and Creeping", description = "Have you seen those pale creepers, mon? I've seem 'em lurching about outside da camp.\n\nThey be scarin' away our game and makin' us look bad.\n\n<Mom'zula leans in and whispers.>\n\nThey also make my skin crawl. I bet dat even Hemet would turn hide and run if he saw one.\n\nI'm tellin' ya, mon. They be bad voodoo.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Slay Withered around the <hunting camp> for Mom'zula." }
WordHunterWoW_QuestEN[40790] = { title = "A Struggle Of Power", description = "", objectives = "" }
WordHunterWoW_QuestEN[40792] = { title = "A Shattered Path Through Time", description = "The Destroyer's star shines upon the land with its piercing light as even the spirits retreat to the shadows. This star is unlike any other in the skies, laying bare the weaknesses of even the boldest heroes. While its influence holds, new paths may open up, to distant places and even distant times. No sage truly understands the nature of this sign, but fortune favors the daring.", objectives = "Complete 5 Timewalking dungeons.", progress = "Follow the Destroyer's star, and walk the paths it reveals.", completion = "Ah, <name>, you have returned. An otherworldly air hangs heavy about you." }
WordHunterWoW_QuestEN[40793] = { title = "A Matter of Planning", description = "Your weapon is stronger than ever, now is the perfect time to put it to use and take our fight to the Legion.\n\nMaster Hsu has set up a command table by the training grounds, and has collected reports from our friends and allies around all of Azeroth.\n\nWhen you are ready, Grandmaster, he should have an update prepared for you.", objectives = "Speak to Master Hsu.", completion = "Grandmaster, I've prepared a brief report on all that I've heard about the Broken Isles.\n\nYou may find it quite interesting." }
WordHunterWoW_QuestEN[40794] = { title = "Fate of the Queen's Reprisal", description = "<This is the kind of intelligence that should be shared. Perhaps someone at the Greyfang Enclave on Dalaran will know what to do with it.>", objectives = "Take the Captain's Log to Lieutenant Surtees at the Greyfang Enclave on Dalaran.\n\nProvided item:", completion = "<The officer looks down at what you're offering him and his eyes light up.>\n\nDo you know what you have here? You might have just delivered some of the most significant intel of the campaign.\n\nI will see to it personally that this gets into Lord Greymane's hands." }
WordHunterWoW_QuestEN[40795] = { title = "The Fight Begins", description = "The Burning Legion has left a trail of ruin all across the face of Azeroth. We must strike at their bases within the Broken Isles if we are to have any hope of ending this war.\n\nI've put together a map of the isles and a list of tasks that we will need to have done there.\n\nOnce you've had a chance to peruse the map, you should choose where we will begin our assault.", objectives = "Select your first assault point on the Broken Isles.", completion = "An excellent choice, Grandmaster." }
WordHunterWoW_QuestEN[40796] = { title = "Lingering on the Edge", description = "I h-have made... mistakes...\n\n<Absolon draws in a rasping breath.>\n\nI want to make it right... I want to live! But the madness... the WITHERING..\n\nI am... fading.\n\n<Absolon stares at you helplessly.>", objectives = "Give Absolon 100 Ancient Mana.", progress = "Can you help me? Is there nothing you can do?", completion = "<Absolon immediately consumes the Ancient Mana and seems incapable of speech for a short while.>" }
WordHunterWoW_QuestEN[40797] = { title = "7.0 DH-Mardum - Small Treasure Chest 014", description = "", objectives = "" }
WordHunterWoW_QuestEN[40798] = { title = "Cling to Hope", description = "Your kindness has inspired me, friend.\n\nI thought I would wander forever among the empty husks of the Withered, but Thalyssra invited me in.\n\nI have chosen to remain here with my people and together we will take back Suramar.\n\nFor now I have but one request.\n\nTake this letter to my wife. She should know that I still live, among other things.\n\nGive her the hope that you gave me.", objectives = "Deliver a letter to Absolon's Wife, Noressa.", progress = "<Noressa eyes you suspiciously.>", completion = "Absolon... is alive?" }
WordHunterWoW_QuestEN[40801] = { title = "Journey to Azsuna", description = "{class}t, I've obtained word that Archmage Khadgar has been able to form a portal that will enable access to the isle of Azsuna. He requests an audience with you at the earliest opportunity.\n\nThe Kirin Tor have also constructed a permanent waygate to enable speedy movement between here and Dalaran - you can find it near the path down in the village should you wish to use it.", objectives = "Speak with Archmage Khadgar in Dalaran." }
WordHunterWoW_QuestEN[40803] = { title = "REUSE ME", description = "", objectives = "" }
WordHunterWoW_QuestEN[40804] = { title = "Li Li Slotted", description = "", objectives = "" }
WordHunterWoW_QuestEN[40805] = { title = "Meet The Master", description = "Hey there <class>t, my mission in Dalaran was a complete success! This new monk is really strong and would be great to have as part of the order!\n\nWe will be waiting for you back at the Wandering Isle.", objectives = "Use the Zen Pilgrimage spell to return to the Wandering Isle." }
WordHunterWoW_QuestEN[40806] = { title = "Arcano-Plasm", description = "Hey there, friend. I am in a bit of a bind and I was hoping that you could lend me some assistance.\n\nI was studying the nearby ley line that runs through this area. Well, I was paying close attention to my scanners, but not to my fuel gauge.\n\nI managed to put down my gyro safely, but I'm out of fuel.\n\nAccording to my scans, there are deposits of Arcano-Plasm in this tunnel, which I can convert into fuel.\n\nYou'll need this Arcane-Drano to extract the samples.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Collect 20 Arcano-Plasms from Arcano Pools or from dead Arcano Slimes in the Arcano Caverns." }
WordHunterWoW_QuestEN[40807] = { title = "Clearing the Tunnels", description = "The nearby  tunnel runs right along the very ley line that I've been studying from the sky. It's a happy coincidence that I landed at this very spot, don't you think?\n\n<Nedward frowns a bit.>\n\nWell, it would haven been, but it seems that the ley line has also attracted every withered creature in Suramar.\n\nCould you lend me a hand and get them to scoot?You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Kill 8 Feeble Husks in the Arcano Caverns." }
WordHunterWoW_QuestEN[40808] = { title = "Fuel Transfer Worker", description = "I knew that I could extract fuel from the Arcano-Plasm, but after getting an eyeful of all those withered creatures running about, I decided to send my Fuel Transfer Worker to collect the samples. I call him FTW-001 for short.\n\nUnfortunately, FTW-001 never came back out and I there's no way in Gnomeregan that I am going in after it.\n\nKeep an eye out for it if you go in there, would ya?You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Retrieve FTW-001 from the Arcano Caverns." }
WordHunterWoW_QuestEN[40810] = { title = "Tracking Quest: Dorion Fed", description = "", objectives = "" }
WordHunterWoW_QuestEN[40811] = { title = "Not to Scale", description = "I was looking for my husband when I accidentally stumbled on this group of naga.\n\nOne of those large brutes nearly crushed me with his foot, but I ran and hid in this cage for protection.\n\nIf I am going to get out of here with my life, I'll need a disguise. I have the know-how, but I need the components. That's where you come in.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Collect 100 Mistbreaker Scales from Mistbreaker naga <naga area>." }
WordHunterWoW_QuestEN[40812] = { title = "Trident True", description = "", objectives = "" }
WordHunterWoW_QuestEN[40813] = { title = "It's in the Glands", description = "", objectives = "" }
WordHunterWoW_QuestEN[40814] = { title = "The Power to Survive", description = "We have long relied on Lord Illidan to vanquish the Legion's strongest warriors - many have expressed concern over our efforts without him.\n\nThankfully, their concerns may not matter much longer.\n\nWe know of two pairs of blades rumored to be more powerful than even Lord Illidan's that are not yet out of reach.\n\nIf we act quickly we should be able to hunt down one without forsaking our watch over the Legion's movements.\n\nI must defer judgment on which is most worthy of our time to you, {name}.", objectives = "Select an artifact weapon to pursue.", completion = "Well chosen. There isn't a moment to spare." }
WordHunterWoW_QuestEN[40815] = { title = "From Within", description = "Our demon hunters, Kor'vas Bloodthorn and Cyana Nightglaive took a small force of the Illidari across to Faronaar. Their mission was to weaken the Legion from within.\n\nI haven't heard from them in a while.\n\nIt would be best if you could find and lead them to success. Agreed?", objectives = "Find Kor'vas Bloodthorn on Faronaar at Vanquish Point.", completion = "Oh, <name>, it's you. Good, we've got a little problem here .\n\nAltruis didn't think that Cyana and I could handle this on our own? He might have been right this time." }
WordHunterWoW_QuestEN[40816] = { title = "The Power to Survive", description = "Illidan and I may have disagreed, but he was unarguably powerful. He was pivotal in vanquishing some of the Legion's most powerful soldiers.\n\nHowever, that may not matter much longer.\n\nThere are two pairs of blades rumored to be more powerful than even Illidan's that may still be within reach.\n\nRegrettably, our numbers are too few to hunt both while maintaining our vigil over the Legion. I fear our window of opportunity is waning quickly.\n\nAs the ranking Illidari, that decision falls to you.", objectives = "Select an artifact weapon to pursue.", completion = "You must move quickly - our time is short." }
WordHunterWoW_QuestEN[40817] = { title = "Twinblades of the Deceiver Chosen", description = "", objectives = "You will receive:" }
WordHunterWoW_QuestEN[40818] = { title = "Aldrachi Warblades Chosen", description = "", objectives = "You will receive:" }
WordHunterWoW_QuestEN[40819] = { title = "Making Arrangements", description = "Do you recall Varedis, {name}? He was once our lead trainer, but fell with the Black Temple years ago.\n\n...or so we thought.\n\nKor'vas spotted the traitor alongside the Legion... wielding glaives imbued with power unlike anything she'd ever seen.\n\nThe Kirin Tor have an eredar lord locked away in the Violet Hold that will know where Varedis' stronghold lies. The prison warden has agreed to consider granting us access to the fiend.\n\nTime to do some convincing.", objectives = "Meet Kayn Sunfury outside the Violet Hold.", completion = "I hold little love for these mages and their ilk, but they are necessary allies." }
WordHunterWoW_QuestEN[40820] = { title = "7.0 DH-Mardum - Small Treasure Chest 015", description = "", objectives = "" }
WordHunterWoW_QuestEN[40821] = { title = "Power Overwhelming", description = "Jagganoth's minions are now yours to command, Overlord, but there is more power to this place than just that!\n\nHere, at the Seat of the Overlord, you will find a special altar, formed of the pit lord's blood and charged with his power. This power can be transferred to your new weapon.\n\nApproach the altar, Overlord, and claim Jagganoth's power for your own!", objectives = "Use the Felblood Altar to unlock your first Artifact Trait.", completion = "Yes, your weapon grows stronger! \n\nFriend cannot rest, though, for a new danger lies around the corner!" }
WordHunterWoW_QuestEN[40823] = { title = "Rebuilding the Council", description = "It seems that friend has caught the attention of Mephistroth. This is very bad news, as the dreadlord will surely wish to seek revenge for losing his general.\n\nFriend will need more than the Dreadscar to stand against him, you will need powerful warlocks such as those who were captured.\n\nCalydus thinks the orc still lies in the pit where you were chained. Friend must revive him, and rebuild the council!", objectives = "Resurrect Ritssyn Flamescowl in Dreadscar Rift.", progress = "I will not rest until the council has been rebuilt.", completion = "I can hardly believe my eyes. For one <class> to control an entire army of demons is beyond what I thought the council was capable of. \n\nI only hope such power is enough to turn the tide of this war." }
WordHunterWoW_QuestEN[40824] = { title = "The Path of the Dreadscar", description = "It would seem that where the council has failed, you have found untold success. These Dreadscar should prove powerful allies, but they may not be enough.\n\nFor now, we must look to rebuild. I will send agents out to locate the whereabouts of the captured council members, as well as any other warlocks who may be able to aid the cause.\n\nMeet me at the scrying pool, and we will plan our action from there.", objectives = "Use the Dreadscar Battle Plans to choose your first zone.", completion = "The plan is set, and the wheels are in motion." }
WordHunterWoW_QuestEN[40825] = { title = "Arcano-Plasm", description = "You got time to give a goblin a hand? Good, thought so.\n\nI was flying my rocket and taking readings of this ley line, you see. Only I wasn't keeping an eye on my fuel reserves. Long story short, I ran out of gas.\n\nI set it down safely and all, but I don't have enough fuel to get me outta here. There's a nearby cave filled with Arcano-Plasm, which I can use to fuel my rocket. Wanna get some for me?\n\nOh yeah, you'll need this here Arcano-Drano to extract it.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Collect 20 Arcano-Plasms from Arcano Pools or from dead Arcano Slimes in the Arcano Caverns." }
WordHunterWoW_QuestEN[40827] = { title = "Clearing the Tunnels", description = "Before I went down, I was tracing the nearby ley line. Turns out, it goes right by the nearby caves.\n\nI'd like to get down there for a closer look, but that ley line is attracting every withered from here to Azsuna.\n\nBut hey, you look like a strong <race>. I bet you'd have no problem clearing them out of there. It's just like trying to clear rats out of a sewer.\n\nWell, sort of.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Kill 8 Feeble Husks in the Arcano Caverns." }
WordHunterWoW_QuestEN[40828] = { title = "Fuel Transfer Worker", description = "I'm no dummy, <name>. I let my brains do the work for me. When I landed, I sent in my personal Fuel Transfer Worker to gather up the Arcano-Plasm.\n\nI call it the FTW-001. Great name, right? Well anyway, the darn thing never came back with my Arcano-Plasm.\n\nI ain't about to go chasing after it with all of those withered things running about.\n\nIf you come across the FTW-001, would ya let me know? I'll even throw in a few coins for your trouble.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Retrieve FTW-001 from the Arcano Caverns." }
WordHunterWoW_QuestEN[40829] = { title = "LFGDungeons - Draenor 6.2 - Raid Finder - 1st", description = "", objectives = "You will receive:" }
WordHunterWoW_QuestEN[40830] = { title = "Close Enough", description = "<Oculeth's eyes have dulled. His voice trembles.>\n\nAre we... are we close?\n\nSo hungry...", objectives = "Carry Chief Telemancer Oculeth to Thalyssra in Shal'Aran.", progress = "Where is Oculeth?", completion = "Thank you for recovering Oculeth. He will be an invaluable asset to our cause." }
WordHunterWoW_QuestEN[40831] = { title = "Save the Crumbling Coast", description = "", objectives = "" }
WordHunterWoW_QuestEN[40832] = { title = "Call of The Uncrowned", description = "My masters gave me strict instructions to deliver this letter to you as quickly as possible.\n\nIts contents are for you and you alone.\n\nGood luck.", objectives = "Read the Sealed Letter and follow the instructions within.", completion = "Your reputation precedes you, <name>.\n\nApologies for the secrecy. We simply could not risk the wrong person finding us here." }
WordHunterWoW_QuestEN[40833] = { title = "Mograine's Recruit", description = "Suffer well <class>t, my mission in Dalaran was a complete success!\n\nWe will await your arrival at Acherus.", objectives = "Use the Death Gate spell to return to Acherus." }
WordHunterWoW_QuestEN[40834] = { title = "Following the Curse", description = "In my previous confrontation with your foe, I was able to see a glimpse into their past. Granted blessed vision by the Cloak of Purity, I saw the Dark Riders for who they once were.\n\nCome, we must go to Ariden's Camp in Deadwind Pass. I can explain its significance along the way.", objectives = "Escort Revil Kost from Manor Mistmantle in Duskwood to Ariden's Camp in Deadwind Pass.", completion = "It's strange that the Dark Riders haven't followed us here, but I will take whatever boon I can get.\n\nI believe the key to finding the Dark Riders is here somewhere. Let us begin our search." }
WordHunterWoW_QuestEN[40835] = { title = "Disturbing the Past", description = "This place is where the merchant, Ariden, set up camp while he was trying to ply his dubious wares to the sorcerer Medivh. It has remained strangely untouched for all this time, which leads me to believe it may still have a connection to its former owner.\n\nHelp me search the camp. Let's see if we can find something to lead us to the Dark Riders.", objectives = "Search around Ariden's Camp for clues leading to the Dark Riders.", completion = "Dark energy hums from the journal, which appears to be the writings of Ariden, and chronicles his time in Deadwind Pass. One entry in particular stands out:\n\n\"The Nightbane have become restless of late, and whispers are abound of the Scythe of Elune having left Darnassus. It must be coming nearer, for the worgen are constantly drawn to it. They will lead me to it.\n\nThose cursed night elves think the weapon is safe in their care. They will soon find how wrong they are\"" }
WordHunterWoW_QuestEN[40837] = { title = "The Deadwind Hunt", description = "The Nightbane! If they are in Deadwind Pass, then they may be seeking the scythe as well.\n\nLet's split up and try to track them down. We'll see where their trail leads...", objectives = "Follow the tracks of the Nightbane worgen.", completion = "The worgen appear to be drawn to the catacombs beneath Karazhan.\n\nCould it be..." }
WordHunterWoW_QuestEN[40838] = { title = "The Dark Riders", description = "This sewer grate leads to the catacombs underneath Karazhan. I've never paid it much attention, but it seems to be where the Nightbane are being drawn to.\n\nTo think, the Dark Riders may have been under our noses this entire time! Come, let us see where this leads.", objectives = "Defeat the Dark Riders and claim the Scythe of Elune.", progress = "It is done.", completion = "Today was a great blow against the Dark Riders, and a victory for the people of Duskwood. \n\nThey are in your debt, as am I." }
WordHunterWoW_QuestEN[40839] = { title = "The Final Shadow", description = "You walk in the halls of the Uncrowned. We are the slayers of kings, the downfall of empires, the unseen blades that write the true history of this world.\n\nSeated before you are the Shadows, the council which aims the blades of the Uncrowned wherever our will demands.\n\nWe have brought you here today with an offer. Take your seat as the final Shadow and help us lead the Uncrowned.\n\nWhat do you say?", objectives = "Take your seat in the Council of Shadows.", progress = "It's up to you, <name>.", completion = "Welcome to the Uncrowned, Shadow <name>." }
WordHunterWoW_QuestEN[40840] = { title = "A Worthy Blade", description = "For quite some time, we've been looking for someone who can operate outside these halls.\n\n{name}, you are the answer to that search. You will be the blade in the dark that vanquishes our foes.\n\nIn order to do so, you require weapons capable of striking down the Legion's best.\n\nGreymane, Tethys, and Valeera each have devised plans to obtain weapons worthy of the tasks to come. I suggest you hear each out before proceeding.", objectives = "Select a weapon to pursue.", completion = "Well chosen." }
WordHunterWoW_QuestEN[40841] = { title = "The Aid of Val'sharah", description = "The land is in pain, <name>, and we have felt its suffering. The druids of Val'sharah will not stand idly by and let our ancient home fall to ruin at the hands of the Leyspine naga.\n\nOur charge is to protect nature. These naga seem only to want to destroy it. We must cut down their leaders and drive back their forces.\n\nWith you help, <name>, we may still be able to save this land.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Slay Raj'kess and Overseer Sakar'thiss in the Crumbling Coast." }
WordHunterWoW_QuestEN[40842] = { title = "Kingslayers Chosen", description = "", objectives = "You will receive:" }
WordHunterWoW_QuestEN[40843] = { title = "Dreadblades Chosen", description = "", objectives = "You will receive:" }
WordHunterWoW_QuestEN[40844] = { title = "Fangs of the Devourer Chosen", description = "", objectives = "You will receive:" }
WordHunterWoW_QuestEN[40845] = { title = "Coastal Healing", description = "The earth has suffered wounds at the hands of the Leyspine naga. They have subjugated murlocs to tear up the land and extract its resources for their own devices.\n\n<Lyris hands you a pouch of seeds.>\n\nI have infused these seeds with restorative essences. Place a seed in any scar left by the murlocs and the healing can begin.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Use the Seed Pouch to plant 8 seeds in Sinkholes in the Crumbling Coast." }
WordHunterWoW_QuestEN[40847] = { title = "A Friendly Accord", description = "I'd like to offer ya an accord.\n\nThe Dread Admiral Eliza wields a pair of cursed blades that have made her the scourge of the south seas. She also stole one of me best ships - the Horizon's Edge - and has it anchored off the shore of Azsuna as we speak. \n\nIf you help me take back me ship, then her cursed blades are yours.\n\nNow, assuming that sounds agreeable, meet me aboard the Crimson Veil. We have her docked right in Booty Bay - not a cheap arrangement.", objectives = "Meet Fleet Admiral Tethys aboard the Crimson Veil in Booty Bay.", completion = "Aha! I knew you'd come!" }
WordHunterWoW_QuestEN[40848] = { title = "Foe Underestimation", description = "<The scroll is written in an elegant script.>\n\nWith the arrival of the Legion, we will be expanding our territory far beyond the confines of Suramar.\n\nYou are to enter the ruins underneath Featherfall Village and dispose of any and all creatures that are inhabiting it.\n\nTake heed. Our scouts have reported many creatures roaming its ancient halls, including a large crystalline giant.\n\nReport back to Suramar after the ruins are clear.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Slay Cromlechus in the Ancient Well." }
WordHunterWoW_QuestEN[40849] = { title = "The Dreadblades", description = "I can promise ya a safe journey to Eliza's position, but once we're there... well, we both know there be no guarantees.\n\nThe plan is simple. We'll take the Crimson Veil as close as we can get her without being seen and disembark from there.\n\nOnce we're ashore, we'll board the Horizon's Edge, bribe her mutinous crew to hand it over, and hunt down Eliza and her legendary blades wherever she may be.\n\nJust say the word when yer ready.", objectives = "Capture the Horizon's Edge and obtain the Dreadblades.", completion = "You did fine work today, lad." }
WordHunterWoW_QuestEN[40850] = { title = "Prisoners of Greystone", description = "", objectives = "" }
WordHunterWoW_QuestEN[40851] = { title = "Darkwell's Request", description = "When I was exiled from Suramar, I tried all manner of things in order to sustain myself.\n\nMany of the creatures that reside in these ruins contain traces of Ancient Mana, but have converted into a crystalline form that is useless to me.\n\nAs chance would have it, Manashale loves to eat this crystallized mana. When he is, uh, done digesting it, the results are turned into a form that I can use.\n\nIf you have any of this crystallized mana on you, I'd sure like to have it.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Collect 20 Crystallized Mana Cores from creatures in Featherfall Ruins or the Ancient Well." }
WordHunterWoW_QuestEN[40853] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[40854] = { title = "Endless Possibilities", description = "Say, since you're down here, I have something that you might be interested in.\n\n<Filgo points over to a husk lying in the junk behind him.>\n\nI found that thingy down in Azsuna, just lying on the beach. I'm sure with a little tinkering, an engineer like you could probably get it up and running in no time.\n\nMight even be useful against the Legion. Kind of like fighting fel with fel, heh!", objectives = "Bring the Fel Reaver Husk back to Didi the Wrench in Dalaran.", progress = "Is there something you need fixed?", completion = "How did you get your hands on this?!\n\n<Didi begins inspecting the husk.>\n\nDo you realize what we could do with something like this? Our own personal fel reaver?!\n\nWe could lay waste to our enemies!\n\nWe could advance our knowledge of science and technology!\n\nWe could make it serve us drinks!" }
WordHunterWoW_QuestEN[40855] = { title = "Our Man in Azsuna", description = "Yikes! OK. This thing is missing a LOT of parts.\n\nWhy don't you go hunt down some new gears or whatever while I do what I can to its existing frame?\n\nA colleague of ours, down in Azsuna, may be able to help out here. His name's Flintlocke.\n\nFetching parts should keep him out of trouble. Just don't let him BUILD anything.", objectives = "Find Fargo Flintlocke in Azsuna near the Felblaze Ingress.", completion = "Shush-it, <class>! This 'ere place is crawlin' with demony things.\n\nAye, Didi sent ye, did she? How is tha wee lass?\n\nIf yer lookin' for demon parts, I can certainly help yeh with that!" }
WordHunterWoW_QuestEN[40856] = { title = "It'll Cost You", description = "If yeh need demon parts, oh aye, this place is right teeming with them fel buggers.\n\nYer bound ta find what'yer lookin' fer probably near them portals they've got jus' sou'east of 'ere.", objectives = "Collect a Fel Reaver Arm and a Fel Reaver Leg from within the Felblaze Ingress.", progress = "Found what'cha need yet?", completion = "Just wat are ye and Didi puttin' together exactly?\n\nIs it big? Dangerous? Rer-diculous?\n\nI want in!" }
WordHunterWoW_QuestEN[40857] = { title = "Bits and Pieces", description = "So many artifacts to catalogue, and never enough time.\n\nGood to see you again, {name}. Brann Bronzebeard and the Explorers' League are in Stormheim right now and could use your help tracking down an ancient titan relic.\n\nBrann can fill you in on the details when you arrive.", objectives = "Meet with Brann Bronzebeard in Stormheim.", completion = "Oh good, another pair of hands. I'm on ta somethin', <name>. I jes' know it!" }
WordHunterWoW_QuestEN[40858] = { title = "The Missing Pieces", description = "Yeh seem ta 'ave everything yeh need. Head back to Didi now wit' yer supplies and giv'er a slap on tha back from me!", objectives = "Head back to Didi the Wrench in Dalaran.", completion = "<You give Didi a slap on the back.>\n\nUgh! I take it Flintlocke says hello?\n\nLet's see what you brought me! Oh good, these will work perfectly.\n\nI'll get started on the repairs using a new invention of mine, the Auto-Hammer.\n\nHere's a copy of the blueprints for it if you're interested in making one for yourself." }
WordHunterWoW_QuestEN[40859] = { title = "The Latest Fashion: Headguns!", description = "So Grapplehammer's got hisself a whole lotta extra guns, right? Glorious! An'it got me ta thinkin', \"What if we put 'em on our heads?\"\n\nHear me out!\n\nSee, yer hands are already busy with yer current weapons, but what's yer head doin'? It's just sittin' there LOOKIN' at stuff. That's me plan. Weaponize yer head!\n\nYou, me lucky lad, can test it out. Strap this on. Now, go blast some fel-tainted critters down below. Blammo!", objectives = "Kill 10 Fel Critters using Flintlocke's Headgun Prototype.", completion = "What'd I tell ya? Now THAT's usin' yer HEAD!\n\nYeh see what I did there?\n\nSeeing as 'ow yeh tested them out fer me, I'll let yeh 'ave a copy of the blueprint fer 'em." }
WordHunterWoW_QuestEN[40860] = { title = "Resupplying the Line", description = "{name}, I need you to make a delivery for me.\n\nFlintlocke's sent word from Val'sharah stating that they're out of bullets.\n\nI sent him down there with enough ammo to cut the planet in half, but Flintlocke goes through ammunition the way you or I go through... air. Go help him out!", objectives = "Deliver the Crate of Ammunition to Fargo Flintlocke in Val'sharah.\n\nProvided item:", completion = "Oh aye! This is exactly what we needed! I wuz about ta start flingin' wee animals." }
WordHunterWoW_QuestEN[40861] = { title = "In My Sights", description = "I used up all me bullets on a wee invention of mine. I call it: Tha Deployable Bullet Dispenser!\n\nOh aye. It shoots in-der-scriminantly wit'out all that messy and time-consumin' \"aiming\" or \"thinkin'\" that us people-folk are wont ta do.\n\nWe had deployed quite a few of 'em east o' here when this swarm of plants came a'thrashin from tha trees.\n\nI didn't 'ave time ta go back an' get me turrets. Would ye mind gettin' them back fer me? Or at least, what's left of 'em?", objectives = "Recover 10 Deployable Bullet Dispenser Parts around Moonrest.", progress = "Those mean greenies better not've touched me dispensers!", completion = "Ohhh me poor innocent bullet dispensers! Look what they've done ta yeh.\n\nWell at least they went down shootin', tha's how I'd like ta go.\n\nEre's tha schematic fer 'em. Deploy 'em near somethun' yeh don't like!" }
WordHunterWoW_QuestEN[40862] = { title = "All Charged Up", description = "If yer gonna wander inta these woods, ye'll be wantin' somethin' with some punch. These plants are a might grabby.\n\nI've got me special explosive charges here that should send those fertilizer mutations back to the dirt.\n\nTake 'em with yeh and give them viney beasties a what-fer!", objectives = "Use Flintlocke's Gunpowder Charges to kill 15 Shimmering Oleanders.", completion = "Quite tha weed killer, eh? Haha!\n\nI figure ye'll be wantin' more of them charges so I went ahead an' wrote down tha schematic fer ye.\n\nI figure it's always good ta keep them plants an' trees in line when they get all uppity." }
WordHunterWoW_QuestEN[40863] = { title = "Always the Last Thing", description = "Well, I've worked out all the kinks. Added a few nuts and bolts, and fitted a new housing for the power core.\n\nProblem is, none of the batteries I have here seem to work. I think we're gonna have to fashion somethin' new together.\n\nI'm gonna need your help, {name}. Let's start by trying a charged gem from the jewelcrafting shop down the way.", objectives = "Find a suitable power source for Didi's design and deliver it to her. Then, see if her new battery actually works.", progress = "Hopefully it's not too much trouble finding a suitable power source.", completion = "We did it! That's one fully functional, killer-lookin' fel reaver.\n\nShould it ever run out of power, here's the schematic for that battery I came up with.\n\nJust pop a new one in it and you should be good to go.\n\nBy the way, whatcha think we should name it? I was thinking somethin' deadly, like \"Reaves.\"" }
WordHunterWoW_QuestEN[40864] = { title = "Modular Modifications", description = "Now that we got this baby running, let's give it some cool abilities.\n\nWhen I was fixing Reaves up, I installed a module port onto his motherboard. This will allow us to upload anything we want.\n\nI'll teach you one of my module designs and you install it on Reaves.", objectives = "Create a Reaves Module: Snack Distribution Mode. Then summon Reaves and install it into him.", progress = "I have a lot of other ideas for things we can do, but I only wrote down a couple to start.", completion = "Everything appears to be running as expected. Although to be honest, I half expected an explosion to go along with it.\n\nHere's the other schematic I made for Reaves. It's based off the auto-hammer design I gave you earlier." }
WordHunterWoW_QuestEN[40865] = { title = "It's Not Rocket Science", description = "{name}, I need you to help me track down Flintlocke again.\n\nI sent him to Stormheim to gather some materials for an invention of mine and he hasn't been back for days. I'm not worried about Flintlocke, but I DO fear for Stormheim.\n\nSee if you can find him!", objectives = "Find Fargo Flintlocke in Stormheim.", completion = "<name>, what're ya doin 'ere? Hobart sent ye, didn'e?\n\nListen, I dunnae need yer help, but seein' as how yeh made yer way down 'ere, maybe we can stir up some trouble ta'gether." }
WordHunterWoW_QuestEN[40866] = { title = "The Shell, You Say?", description = "I know ol' Hobart sent me down 'ere to acquire 'is precious murloc glass thingies, but I have designs of me own!\n\nI've seen those murlocs carrying interesting lookin' shells that would go perfectly into me music box I've been workin on.\n\nYa lead the charge an'a I'll be right behind ya.", objectives = "Slay murlocs to collect  10 of their shells for Fargo Flintlocke.", progress = "Jes let me finish up 'ere and I'll be right with yeh.", completion = "Oh, yer finished! I swear I was jes' about ta join yeh, too.\n\nWell, what's done is done. I s'pose I can share me design with yeh since yeh got all the shells fer me." }
WordHunterWoW_QuestEN[40867] = { title = "Bubble Baubles", description = "Ol' Hobart wanted me ta gather up these shiny, glass trinkets the murlocs carry around, but those bloody buggers ain't willin' to jes' hand 'em over!\n\nI tried the dip-ler-matic approach, but I don't speak murloc, so I just end up shootin' 'em.\n\nMaybe you might have better luck gettin' them baubles.", objectives = "Gather 12 Murloc Trinkets from around their camps.", progress = "Any luck?\n\nDid yeh try shootin' 'em?", completion = "Well lookie there! You managed to talk 'em outta their trinkets! Ye'll have to teach me their language someday." }
WordHunterWoW_QuestEN[40868] = { title = "Wibbly-Wobbly, Timey-Wimey", description = "I gotta finish up 'ere, so why don'tcha take those trinkets back to Hobart fer me.\n\n'Sides, I'ma thinkin' he likes ya more than me.", objectives = "Deliver the Murloc Trinkets to Hobart Grapplehammer in Dalaran.", completion = "The pieces! Well it's about time.\n\n<Hobart moves over to a machine and begins inserting the items you gave him.>\n\nI take it Flintlocke made you deliver these? Well since you did the legwork, you can have a copy of my design.\n\nIt's a new type of wormhole generator. Specifically designed for getting around Dalaran in the blink of an eye!" }
WordHunterWoW_QuestEN[40869] = { title = "Fire and Forget", description = "They say, \"When life gives you lemons, make lemonade.\" Well, life gave me a butt-load of guns.\n\nSo I've been figuring out ways to turn these guns into useful tools.\n\nMy latest modification is a gun that shoots bandages! Imagine it, you're on the battlefield, you see your ally go down, you pull out your bandage gun, shoot him with it and bam, he's back in the fight!\n\nI just need you to test it first and make sure it's safe.", objectives = "Test out the Prototype Pump-Action Bandage Gun on Wounded Kirin Tor Guardians in Dalaran. Use the gun to calibrate it when needed.", completion = "Good job on calibrating the power. Shame about those first few though...\n\nI've adjusted the numbers on the schematic to the new specifications so you should be able to make the safe version." }
WordHunterWoW_QuestEN[40870] = { title = "Here Comes the BOOM!", description = "{name}, they stole all my fireworks, the little scamps.\n\nYou didn't see them? I was just on the verge of creating a new module for Reaves when these kids came in here and ran off with my fireworks.\n\nI need them back if I'm going to finish what I'm working on. Can you go get them back for me?", objectives = "Get Didi's fireworks back from the children in Dalaran.", progress = "If I ever get my hands on those kids...", completion = "<Didi takes the fireworks from you and continues to work at her bench.>\n\nThere we go. All done!\n\nApply this to your bot, and you should be able to launch fireworks wherever you want! ALL explosions are beautiful in their own way... but fireworks really are something else." }
WordHunterWoW_QuestEN[40871] = { title = "Locke and Load", description = "Flintlocke's been looking for you, {name}. I think he needs your help again.\n\nI sent him out to test out a couple of new inventions of mine back down in Azsuna. Look for him on the shoreline west of Oceanus Cove!", objectives = "Find Fargo Flintlocke in Azsuna.", completion = "Oh aye, there yeh are lad. I was kinda hopin' ta see yeh again." }
WordHunterWoW_QuestEN[40872] = { title = "Going Out With a Bang", description = "While I was, eh, testin' out this new flight pack fer Hobart, it sorta exploded an' sent me flyin' back over 'ere.\n\nYou can see all the pieces out there in tha water.\n\nNow, I've got these boots 'ere that Hobart gave me to test out too, but they're not quite me size.\n\nI figure we could kill two birds with one stone and 'ave ye test 'em out while pickin' up the broken bits of the pack.\n\nMind tha sharks while yer out there.", objectives = "Use the Gunshoes to skim across the water while picking up 15 pieces of Gunpack Debris.", completion = "Ah terrific! Nice work gettin' them parts back. I thought I was gonna have ta drain the bay by blowin' up Warden's Isle over there.\n\nThem boots seemed ta suit yeh - here's the schematic fer 'em if yeh need another pair." }
WordHunterWoW_QuestEN[40873] = { title = "Keep Yer Powder Dry", description = "So while we've got all tha parts for tha pack again, I'm afraid I'm all outta gunpowder.\n\nThis is the worst thing ta ever happen ta me.\n\nBut there's hope. Just o'er to tha north are caves filled with crashed ships. Chances are them sea giants crashed one or two ships with cannons. And cannons mean gunpowder, sweet gunpowder.\n\nSearch their caves fer sum powder an' bring it on back.", objectives = "Gather 8 Barrels of Gunpowder and return them to Fargo in Azsuna.", progress = "Try not ta get it wet, I dunna feel like waitin' fer it ta dry out.", completion = "Oh aye, tha's plenty, lad. I made sum adjustments ta tha design fer tha gunpack.\n\nYou should probably hold on to 'em, seein as 'ow these inventions of Hobart keep explodin' on me." }
WordHunterWoW_QuestEN[40874] = { title = "I'd Do It Myself, But...", description = "If yer headed over ta tha sea giant caves, do me a favor give those slimy naga a right bludgerin'.\n\nThey done run oft with me rogue friend an' I figure some revenge is in order.\n\nI'd do it meself but ol' Hobart would give me wut-fer if I abandoned his stuff.", objectives = "Kill 10 Hatecoil Slavemasters in the Oceanus Cove.", completion = "Oh I wish I coulda been there ta see tha look on their fishy faces!\n\nEh, come ta think of it, fish always look kinda ser-prised." }
WordHunterWoW_QuestEN[40875] = { title = "Going to Waste", description = "Me wee rogue friend Lowping were\ngnome-napped by them dirty naga when we got 'ere. He's gone! They drug him right oft toward tha cove!\n\nBut 'ere's tha real issue. He 'ad a schematic on 'im fer one of me greatest inventions.\n\nAnd by \"on 'im,\" I mean I tattooed it to tha top o' his head. FOR SAFETY!\n\nWhen ye find 'im, jes shave 'is head and make a quick copy o' tha design.", objectives = "Find Lowping in the sea giant caves, shave his head, and make a copy of the schematic that's tattooed there.", progress = "Poor lad's probably bein' tortured as we speak. Curse them scaley beasts!", completion = "Oh aye, yeh get me schematic! Here, keep a copy fer yerself, in case yer lookin' for somethin' to tattoo somewheres.\n\nIt's a damn shame about Lowping. Yeh know, come ta think of it, maybe we shoulda rescued him. Ah! Multi-tasking were never my thing." }
WordHunterWoW_QuestEN[40876] = { title = "Locke, Stock and Barrel", description = "Well that jes' about wraps up me work 'ere. I'll start packin up an'ead back ta Dalaran.\n\nIf yeh wouldn't mind, could yeh tell Hobart 'ow things went down 'ere? Maybe leave out tha bits with tha explodin', tha drownin', an' tha gettin captured an' what not.\n\nYer a proper friend, {name}!", objectives = "Return to Hobart in Dalaran and inform him of Flintlocke's work.", completion = "So the gunshoes and pack were a success? I guess all these guns I made weren't such a waste after all.\n\nWhich reminds me, I saw the plans for those goggles Flintlocke made and I've got to say, they were rather crude in their design. \"Dwarven Engineering\" is a bit of an oxymoron.\n\nI've updated the schematic to not require so many materials." }
WordHunterWoW_QuestEN[40877] = { title = "Halls of Valor: Trigger Happy", description = "In order to complete my latest invention, I need a special relic known as the Runestone of Vitality.\n\nOdyn, king of the Halls of Valor is known to use it to breathe life into his constructs.\n\nWhat I'm asking is no easy task, but I need to take the runestone from Odyn and bring it back to me.", objectives = "Obtain the Runestone of Vitality from Odyn in the Halls of Valor.", progress = "I'm glad you're the one going up against a god and not me.", completion = "Keep your fingers crossed, <name>, and let's hope this works.\n\n\n\nYes! YES! It's alive, ALIVE!\n\nNow I can mass-market these gun parts as toys for children!" }
WordHunterWoW_QuestEN[40878] = { title = "Assault on Violet Hold: Cheating Death", description = "Hobart was showing me a copy of a design you found, and it got me to thinking of a new module for Reaves.\n\nUnfortunately I didn't have the materials required to test it.\n\nCould you make me a couple Failure Detection Pylons?\n\nI'll also need a plasmatic laser bolt. You should be able to find one in the Violet Hold.", objectives = "Craft 2 Failure Detection Pylons. Go to the Violet Hold and recover a Plasmatic Laser Bolt and return everything to Didi the Wrench in Dalaran.", progress = "Just rip the bolt off of one of the prison cells. I'm sure whatever's inside has long since died.", completion = "<Didi takes the pylons and begins tinkering with them and starts writing some notes.>\n\nYea, that should do the trick!\n\nOne new and improved Reaves module schematic for you, <name>." }
WordHunterWoW_QuestEN[40879] = { title = "It's On With Automatons", description = "", objectives = "It's time I showed you my ultimate plans for Reaves! Allow me to present... piloted combat mode! Sure, the ingredients are ridiculously hard to find, and nobody even knows if it works, but hey - that's engineering for you!\n\nEnjoy the schematics!" }
WordHunterWoW_QuestEN[40880] = { title = "Short Circuit", description = "While I've got you here, I was wondering if you could track something down for me.\n\nI'm sure you're familiar with a Blingtron, yes? Well, I started askin' around, and it seems no one really knows where the design for it came from. One rumor does pop up more than others, though:\n\nArea 52.\n\nInterested in a field trip?", objectives = "Find the inventor of Blingtron.", completion = "An old schematic, still intact, is floating amongst the papers.\n\nAs you examine the schematic you realize that it's the circuit design for Blingtron!" }
WordHunterWoW_QuestEN[40881] = { title = "Oil Rags to Riches", description = "Didi will be very interested in reading the journal you found as well as examining the circuit design.\n\nYou should return to her as soon as you can.", objectives = "Return to Didi the Wrench in Dalaran and show her the items you've found.", completion = "That circuit design was exactly what I needed to finish the Blingtron module for Reaves.\n\nNow to reap the rewards, <name>!" }
WordHunterWoW_QuestEN[40882] = { title = "Court of Stars: Revamping the Recoil", description = "{name}, you'll be very excited to hear that I've been working on a newer, better version of those goggles that Flintlocke rigged up.\n\nThe ones I've designed have double the power, but unfortunately they also have double the recoil. I'm afraid if you use them, they'll break your neck.\n\nBut I found a solution. Deep inside Suramar City lies a magical mechanism that will reduce the recoil to practically nothing.\n\nRecover that mechanism for me and we're in business!", objectives = "Go into the Court of Stars and recover the Arcanic Compressor for Hobart.", progress = "Those elves probably had no idea the quantum mechanical applications that mechanism has!", completion = "<Hobart takes the mechanism from you and begins tinkering with his design.>\n\nYes, I believe that's it. Good work, <name>.\n\nAs per usual I'll let you have a copy of my schematic for your personal gain." }
WordHunterWoW_QuestEN[40883] = { title = "Fate of the Guard", description = "<Thalrenus looks you over.>\n\nYou are not one of them.\n\nThe Nightborne came to our gates hours after the shield over Suramar fell. We thought them friends, despite our long separation.\n\nWe were wrong.\n\nThey poured into our stronghold and began the slaughter. We were unprepared. Though we fought, we were beaten.\n\nThe keep is lost. Our leaders have perished and their corpses lay in the streets.\n\nFind them, give them their final rites.\n\nWhile you search, look for survivors. Help them if you can.", objectives = "Find the corpses of Nyellus Starweaver, Galar'thus Rivertree, and Kailea Windfeather and perform funereal rites for them.", progress = "Are you here to fight the Nightborne?", completion = "I thought the Moon Guard could endure anything..." }
WordHunterWoW_QuestEN[40884] = { title = "Corrupted Into Crystal", description = "<class>, We need your help!\n\nWe came here from Val'sharah to lend aid to our sisters against the Legion. When we arrived, we found that they had been corrupted by the arcane energies that flow through these ruins.\n\nBefore we could act, our corrupted sisters attacked us. Those of us that remain have been backed into this corner. Here we must make a final stand.\n\nIf we are to survive this onslaught, we will need to fight our way out.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Kill 8 Corrupted Sisters in the Ancient Well." }
WordHunterWoW_QuestEN[40885] = { title = "Transplanting Their Cores", description = "All dryads have a connection with nature, <name>. We live to nurture all living things. Even in their corrupted state, our sisters are fostering the growth of the plants in these ruins.\n\nSadly, these plants are feeding off of the corruption that has taken over.\n\nThe Shalebark have a natural resistance to this corruption. If their cores have not been tainted, there still is a chance to cleanse and replant them elsewhere.\n\nOf course, that assumes that we escape with our lives.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Collect 6 Pristine Shalebark Cores from Shalebark Treants in the Ancient Well." }
WordHunterWoW_QuestEN[40886] = { title = "Verdant Search", description = "When the Corrupted Sisters set upon us, many of the Watchers fell behind when we fled. Few made here it, and fewer have the ability to fight.\n\nWe cannot let the Watchers die in this accursed place, but we don't have the strength to go into the ruins and retrieve them.\n\nThis is a task that I must ask of you.\n\nUse this salve to treat the wounds of any Watcher that still draws breath.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Apply Leafwind's Salve to 6 Injured Verdant Watchers in the Ancient Well." }
WordHunterWoW_QuestEN[40888] = { title = "Hammer of Khaz'goroth Actived", description = "", objectives = "" }
WordHunterWoW_QuestEN[40889] = { title = "Tidestone of Golganneth Activated", description = "", objectives = "" }
WordHunterWoW_QuestEN[40890] = { title = "The Tears of Elune", description = "The Tear of Elune floats effortlessly, glistening in an ethereal pillar of moonlight.", objectives = "Use the central teleporter in Dalaran and then place the Tears of Elune in the Portrait Room.", completion = "<Archmage Khadgar has set aside a space here for the Tears of Elune, as well as the rest of the Pillars of Creation.>" }
WordHunterWoW_QuestEN[40891] = { title = "Aegis of Aggramar Activated", description = "", objectives = "" }
WordHunterWoW_QuestEN[40895] = { title = "The Haunted Mire", description = "", objectives = "" }
WordHunterWoW_QuestEN[40896] = { title = "Threnody of Chieftains", description = "", objectives = "" }
WordHunterWoW_QuestEN[40897] = { title = "Garvrulg", description = "", objectives = "" }
WordHunterWoW_QuestEN[40898] = { title = "Fresh Meat", description = "This crater is infested with felfire basilisks.\n\nThey may not be the most cunning of creatures, but they are as vile and dangerous as any demon.\n\nHowever, they may yet prove useful to us. Slay the basilisks, but return to me with chunks of their fel-infused flesh.\n\nI have plans to make use of their freshly carved flesh...", objectives = "Collect 6 Fresh Fel-Flesh.", progress = "Do you have the Fresh Fel-Flesh I require?", completion = "I see that you have returned with the freshly carved remains of the fel basilisks.\n\nListen closely, and I will explain the purpose behind retrieving them..." }
WordHunterWoW_QuestEN[40900] = { title = "The Burden Borne", description = "Your assistance against the Dark Riders has proven a great service to the Light. Though our beliefs may separate us, I know that we share one goal.\n\nYou have allowed me to fill my purpose in returning these artifacts to their rightful owners, and for this I am thankful. As for the Scythe of Elune, I can think of no safer place than in your care. \n\nMay it serve you well against the Legion, {name}.", objectives = "Return to Arch Druid Greathoof in the Dreamgrove. You may use Dreamwalk to travel via the Emerald Dreamway.", completion = "The Scythe of Elune!\n\nI never thought I would see that weapon used without turning its wielder into a savage beast, but you've brought balance to its primal nature.\n\nElune has certainly guided your hand, <name>. You've accomplished what no <class> has done before!" }
WordHunterWoW_QuestEN[40901] = { title = "Grimwing the Devourer", description = "You have my thanks for rescuing me from captivity, {class}.\n\nHowever, Azoran is no mere demon. He is a powerful eredar who commands great rank within the Burning Legion.\n\nIf you wish to continue with me, I need proof of your strength.\n\nGrimwing the Devourer is the strongest of the felbats and a suitable test of skill. Place the basilisk flesh upon the altar to the north and slay Grimwing when she appears.\n\nReturn to me with her head and I will not doubt your ability.", objectives = "Slay Grimwing the Devourer.", progress = "What news do you bring of Grimwing the Devourer?", completion = "Grimwing was a formidable demon... I must say I am impressed with your skill, <name>.\n\nThere are many more demons here to kill. It is good to have someone capable at my side." }
WordHunterWoW_QuestEN[40902] = { title = "7.0 Suramar - Treasure 002 - Fel Breach - AJB", description = "", objectives = "" }
WordHunterWoW_QuestEN[40904] = { title = "Shadow of the Defiler", description = "Crimson energy swirls within this disturbing object, which seems to have slightly different contours each time your gaze returns to it.\n\nIts power is utterly foreign, unlike anything you have seen in Draenor or during your battles with the Legion. Perhaps the keepers of Moonglade, back on Azeroth, might have some insight into its nature.", objectives = "Consult the keepers of Moonglade to see if they can shed any light on the nature of the Remnant of Chaos.", progress = "I have heard of your deeds beyond the red portal, <name>. Two worlds owe you and your companions a great debt. What brings you to the Moonglade?", completion = "Where... where did you find this?" }
WordHunterWoW_QuestEN[40905] = { title = "Lieutenant Strathmar", description = "", objectives = "" }
WordHunterWoW_QuestEN[40906] = { title = "Serpents from the Deep", description = "Hail, {class}.\n\nMy village of Jandvik has fallen under siege by a group of naga called the Sashj'tar.\n\nNormally I would not seek out the help of an outsider, but we are facing an enemy that we are incapable of defeating.\n\nMany powerful elven relics can be found in the ruins around Jandvik. In exchange for your help, you will have your just rewards.\n\nDo we have an accord?", objectives = "Speak with Toryl outside of Jandvik.Hail, <class>.\n\nMy village of Jandvik has fallen under siege by a group of naga called the Sashj'tar.\n\nNormally I would not seek out the help of an outsider, but we are facing an enemy that we are incapable of defeating.\n\nMany powerful elven relics can be found in the ruins around Jandvik. In exchange for your help, you will have your just rewards.\n\nDo we have an accord?You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[40907] = { title = "Removing Obstacles", description = "{class}! Interested in earning some coin?\n\nThe jarl of Jandvik is missing and two headstrong whelps are vying to take over leadership. I should be the next jarl, not them!\n\nI want you to enter Jandvik and defeat Calder and Eynar in mortal combat.\n\nI would not normally put my trust in an outsider, but this situation requires the aid of someone like you. Jandvik would condemn me if I were caught with their blood on my hands.\n\nMeet me in the center of Jandvik when the deed is done.", objectives = "Kill Calder and Eynar in Jandvik.", progress = "Do not underestimate Calder and Eynar.", completion = "With my adversaries gone, I can claim leadership of Jandvik unopposed." }
WordHunterWoW_QuestEN[40908] = { title = "Jarl Come Back Now", description = "You seem to follow my commands well, {name}. Perhaps I can use you again.\n\nJarl Throndyr, the leader of Jandvik, has been missing for some time now. I assume that he has fallen in battle to the invading Sashj'tar naga, but I must know for certain.\n\nFind out what has become of him.\n\nDo this task for me and I can assure you that my vrykul will not harm you.", objectives = "Locate Jarl Throndyr in Azuregale Bay.", completion = "<Throndyr mutters through shallow breaths.>\n\nPoison... runs through... my body." }
WordHunterWoW_QuestEN[40909] = { title = "7.0 DH-VotW - Small Treasure Chest 000", description = "", objectives = "" }
WordHunterWoW_QuestEN[40910] = { title = "7.0 DH-VotW - Small Treasure Chest 001", description = "", objectives = "" }
