WordHunterWoW_QuestEN[40917] = { title = "Black Rook Hold Normal Reward Quest", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[40918] = { title = "Black Rook Hold Heroic Reward Quest", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[40919] = { title = "Fel Bent for Leather", description = "Ah, my faithful assistant. I have just the task for you.\n\nAs you have seen, fel power permeates living tissue and can easily be coaxed out.\n\nAlso, these damned bats are driving me to my wits' end. There is an opportunity to kill two bats with one blade, it seems. Your blade.\n\nTake this crystal. It should rip those hellions from the sky and into your waiting arms.\n\nYou may as well bring back their hides, if only to shut up that fellow in the corner for a few moments.", objectives = "Collect 50 Felbat Hide Scraps for Kyrtos.", progress = "Have you obtained the hides?", completion = "I can no longer hear their shrieking. Finally, peace and quiet!" }
WordHunterWoW_QuestEN[40920] = { title = "Stonebinder Bounty", description = "", objectives = "" }
WordHunterWoW_QuestEN[40921] = { title = "Tracking Quest: Bastillax 1", description = "", objectives = "" }
WordHunterWoW_QuestEN[40922] = { title = "Tracking Quest: Mephistos 2", description = "", objectives = "" }
WordHunterWoW_QuestEN[40923] = { title = "Tracking Quest: Mephistos 3", description = "", objectives = "" }
WordHunterWoW_QuestEN[40924] = { title = "Tracking Quest: Bastillax 4", description = "", objectives = "" }
WordHunterWoW_QuestEN[40925] = { title = "Bitestone Burglary", description = "", objectives = "" }
WordHunterWoW_QuestEN[40927] = { title = "Jandvik's Last Hope", description = "Commander Malt'his was conferring with a sea giant?\n\nWithout your help, this village will surely fall to the combined forces of the Sashj'tar and the sea giants.\n\n<Toryl stands there quietly for a moment.>\n\nMeet me in an underground cave out in Azuregale Bay.\n\nI want to show you something that may turn the tide in this battle.", objectives = "Meet with Toryl in the Sashj'tar Grotto.", completion = "I do not know who you are, but I must thank you." }
WordHunterWoW_QuestEN[40929] = { title = "Symbols of Power", description = "This demon has information that could lead us to those in charge.\n\nUnfortunately, he is more fearful of his master than he is of us. We need to change his mind about that.\n\nThe most powerful Burning Legion soldiers often carry an emblem of their rank and status within the demon army.\n\nSeek out the stronger demons in Felsoul Hold, slay them, and return to me with their emblems.\n\nWe will show this wyrmtongue servant who it is he should fear...", objectives = "Collect 8 Legion Emblems.", progress = "Do you have the Legion Emblems?", completion = "I see you have returned with the emblems. Excellent.\n\nLet's see how this wyrmtongue reacts when we show him what we've made of his comrades." }
WordHunterWoW_QuestEN[40930] = { title = "Apocalypse", description = "<The Lich King's chill voice fills your mind once again>\n\nThere is an ancient blade, lost in the echoes of time, that has the power to bring my vengeance upon the Legion. \n\nIt is known as Apocalypse.\n\nI've sensed the blade in the possession of the Dark Riders of Deadwind Pass. Their magic conceals them from my sight but they cannot hide from the scourge! They were last seen by my agents near a place called Manor Mistmantle.\n\nGo there, {name}. Defeat the Dark Riders, and claim the blade!", objectives = "Start your search for Apocalypse at Manor Mistmantle in Duskwood.", progress = "And just why should I help you, <class>?", completion = "I am left with little choice. I cannot face another Dark Rider ambush alone, and you are obviously formidable.\n\nI will help you find your artifact, but only if you will allow me to return the others in their possession to their rightful place.\n\nDo we have a deal, <class>?" }
WordHunterWoW_QuestEN[40931] = { title = "Following the Curse", description = "Very well. I suppose an introduction is in order. I am Revil Kost, priest of the Light and a seeker of lost artifacts. I've dealt with the Dark Riders before, and have returned to rid this place of them.\n\nThe Riders are elusive, but I may have a clue to their whereabouts. In our previous confrontation, I was able to see a glimpse into their past. Granted blessed vision by the Cloak of Purity, I saw the Dark Riders for who they were before.\n\nCome with me to Ariden's camp. I will explain on the way.", objectives = "Escort Revil Kost from Manor Mistmantle in Duskwood to Ariden's Camp in Deadwind Pass.", completion = "As much as your company pains me, you are proving to be a powerful ally. \n\nI believe the key to finding the Dark Riders is here somewhere. It is strange that the riders haven't followed us here, but we should make haste lest they change their mind." }
WordHunterWoW_QuestEN[40932] = { title = "Disturbing the Past", description = "This place is where the merchant, Ariden, set up camp while he was trying to ply his dubious wares to the sorcerer Medivh. \n\nIt has remained strangely untouched for all this time, which leads me to believe it may still have a connection to its former owner.\n\nHelp me search the camp. Let's see if we can find something to lead us to the Dark Riders.", objectives = "Search around Ariden's Camp for clues leading to the Dark Riders.", completion = "Dark energy hums from the journal, which appears to be the writings of Ariden, and chronicles his time in Deadwind Pass. One entry in particular stands out:\n\n\"I hear the whispers. They call me from the wet soil of shallow graves, hearkening me to my legacy. \n\n\"But what legacy? The merchant I once was had no special bloodline...\n\n\"Nevertheless, I am drawn to it. The dread blade... the world-ender... Apocalypse.\"" }
WordHunterWoW_QuestEN[40933] = { title = "A Grisly Task", description = "Wet soil? Shallow graves?\n\nI think the journal is referring to the gravesites off of the lake near Karazhan. Nobody knows who is buried there, but they may be the key to finding the Dark Riders.\n\nYou can... speak to the dead, yes?", objectives = "Raise the dead buried in the Sodden Graves in Deadwind Pass until you find one who can point you to the Dark Riders location.", completion = "The chill down my spine tells me that you must have met with success.\n\nWhat did you find?" }
WordHunterWoW_QuestEN[40934] = { title = "The Dark Riders", description = "The catacombs? I've never heard of such a place. Unless, he means...\n\nThere's a sewer grate along the edge of the river leading to a catacombs underneath Karazhan. I've never paid it much attention, but it could lead to the catacombs that the spirit spoke of. \n\nTo think, the Dark Riders may have been under our noses this entire time! Come, let us see where this leads.", objectives = "Defeat the Dark Riders in the Karazhan Catacombs and claim Apocalypse.", progress = "Didyou find what you seek, <class>?", completion = "Today was a great blow against the Dark Riders, and a victory for the people of Duskwood. \n\nThey are in your debt, as am I." }
WordHunterWoW_QuestEN[40935] = { title = "The Call of Vengeance", description = "I was wrong about you, death knight. Your assistance against the Dark Riders has proven a great service to the Light. Perhaps I should not be so quick to judge.\n\nNevertheless, you have allowed me to fill my purpose in returning these artifacts to their rightful owners. As for Apocalypse, I can think of no safer place than in your care. \n\nMay it serve you well against the Legion, death knight.", objectives = "Take the Death Gate to the Frozen Throne, and receive the Mark of the Lich King.", completion = "The champion of the Lich King returns, and with a mighty weapon to bear against our demon foes!\n\nMay the Burning Legion tremble at the sight of our forces!" }
WordHunterWoW_QuestEN[40936] = { title = "Tracking: Revil Convinced", description = "", objectives = "" }
WordHunterWoW_QuestEN[40937] = { title = "Tracking: Revil Defeated", description = "", objectives = "" }
WordHunterWoW_QuestEN[40938] = { title = "The Light and the Void", description = "Alonsus Faol has been a valuable ally, and his instincts about you have proven true. I believe you are uniquely suited to assist in a matter that will bring a great force of good into this world.\n\nI must take you somewhere far from Azeroth to finish a task my people began long ago. Will you aid us?", objectives = "Aid Velen with his mysterious task.", progress = "We have important work to do, <name>.", completion = "Welcome back, Cardinal. I think you'll find we've done quite a job getting this place prepared for you. We should get started immediately." }
WordHunterWoW_QuestEN[40939] = { title = "Vignette: Stormwing Matriarch", description = "", objectives = "" }
WordHunterWoW_QuestEN[40940] = { title = "Test Quest Two", description = "[PH]", objectives = "" }
WordHunterWoW_QuestEN[40941] = { title = "Missive: Assault on the Pit", description = "The Blackrock forces based out of the Pit in Gorgrond make up the bulk of the Iron Horde army. If we crush them on their home soil, the rest of the Iron Horde will have little hope of standing against us.\n\nIf you choose the battle, bring friends. The Blackrock won't be defeated easily.", objectives = "Assault the Blackrock forces at the Pit in Gorgrond.", completion = "News about da assault beat ya back, boss-mon. And some spoils of the fightin'.\n\nYa be a force to be reckonin' with." }
WordHunterWoW_QuestEN[40942] = { title = "Missive: Assault on the Pit", description = "The Blackrock forces based out of the Pit in Gorgrond make up the bulk of the Iron Horde army. If we crush them on their home soil, the rest of the Iron Horde will have little hope of standing against us.\n\nIf you choose the battle, bring friends. The Blackrock won't be defeated easily.", objectives = "Assault the Blackrock orcs at the Pit in Gorgrond.", completion = "Word of the assault has already made it back, as have some spoils from the fight.\n\nWell done sir, if you don't mind me saying." }
WordHunterWoW_QuestEN[40943] = { title = "Missive: Assault on the Heart of Shattrath", description = "Sargerei forces from deep in Shattrath have grown stronger and bolder by the day. We can no longer risk ignoring the threat that they pose.\n\nBring allies if you wish to face the Sargerei so deep within the city.", objectives = "Assault the Sargerei force in Shattrath City in Talador.", completion = "News about da assault beat ya back, boss-mon. And some spoils of the fightin'.\n\nYa be a force to be reckonin' with." }
WordHunterWoW_QuestEN[40944] = { title = "Missive: Assault on the Heart of Shattrath", description = "Sargerei forces from deep in Shattrath have grown stronger and bolder by the day. We can no longer risk ignoring the threat that they pose.\n\nBring allies if you wish to face the Sargerei so deep within the city.", objectives = "Assault the Sargerei forces deep within Shattrath City in Talador.", completion = "Word of the assault has already made it back, as have some spoils from the fight.\n\nWell done sir, if you don't mind me saying." }
WordHunterWoW_QuestEN[40947] = { title = "Special Delivery", description = "Verene's child has gone missing. I can guess what happened, but I need to be sure.\n\nMost guardsmen use couriers to relay delicate information. In this, magic is strictly the province of high ranking officials.\n\nTake this blade. Do not touch the cutting edge. Use it to silently waylay the couriers and collect any correspondence they carry.\n\nWith any luck, the missives will tell us exactly where to find the girl.\n\nWe guards know everything, after all.\n\n<Silgryn offers you a winning smile.>", objectives = "Acquire 3 Stacks of Letters from Nightborne Couriers using the Nightborne Spellblade.", progress = "Were you successful?", completion = "Fine work. I will read these over." }
WordHunterWoW_QuestEN[40949] = { title = "Not Their Last Stand", description = "I've been watching you- you are not with them.\n\n<Ivanel coughs quietly.>\n\nI am not long for this world, but there is one thing I would have you do while you are here.\n\nThe hippogryphs here still fight bitterly to defend their home and their companions in the Moon Guard. They have not accepted that the Guard is no more. \n\nPlease... send them away. Let them know there is nothing left for them to fight for here.", objectives = "Dissuade 5 Lingering Moonfall Hippogryphs", progress = "What is it?", completion = "Thank you. I feel better knowing they will not continue to sacrifice themselves for us." }
WordHunterWoW_QuestEN[40950] = { title = "Honoring Success", description = "All has gone as planned. Your new blades are a testament to that.\n\nWe will demand a great deal of you in the weeks and months to come, as we must. But we would be remiss if we failed to take a moment to celebrate a job well done.\n\nWhat do you say?", objectives = "Celebrate the successful acquistion of your artifact with your fellow Shadows.", progress = "It's kill or be killed.", completion = "It seems you struck a nerve." }
WordHunterWoW_QuestEN[40951] = { title = "Bitestone Bazaar", description = "", objectives = "" }
WordHunterWoW_QuestEN[40952] = { title = "Hunter to Hunter", description = "Now that you wield Thas'dorah, it's time to learn more about the night elf who set you on this journey\n\nI suggest returning to the Hunter's Reach shop where you met my courier. Whoever this Emmarel Shadewarden is, it seems she has some part to play in the war against the Legion.", objectives = "Go to the Hunter's Reach shop in Dalaran and speak to Emmarel Shadewarden.", completion = "There is much to do, noble <class>. But first, I suppose you'll want to learn a little more about who I am and why I have sought you out." }
WordHunterWoW_QuestEN[40953] = { title = "On Eagle's Wings", description = "Since ancient times, my order has stood vigil on these Broken Isles, watching for the Legion's return. Only a handful of us remain... but that changes today.\n\nThe artifact you hold is more than a weapon. It is a symbol that will unite hunters of all kingdoms and creeds.\n\nI'm sure you have questions. Meet me at the Trueshot Lodge in Highmountain and see with your own eyes what awaits us. Snowfeather and I will make our own way there.", objectives = "Meet Emmarel Shadewarden at Trueshot Lodge in Highmountain.", completion = "I've observed your skills for some time, <name>. Watched you from a distance.\n\n\n\nWait, that sounds a little creepy. Sorry, my social skills are a tad rusty. Let me start again.\n\nOur order has been on the lookout for hunters who could lead the Unseen Path into a new era. No one is more qualified for that role than you." }
WordHunterWoW_QuestEN[40954] = { title = "The Unseen Path", description = "For a thousand years, the Unseen Path has watched and waited. We remained few in number, quietly acting behind the scenes when Azeroth needed us. Only a select few even knew our group existed.\n\nBut the time for lingering in the shadows is over.\n\nBefore we begin our work, you should hear more about the Unseen Path.", objectives = "Hear Emmarel's tale.", completion = "The Legion has returned, and the Unseen Path needs new blood... new leadership.\n\nThe weapon you hold is proof there is no one better suited to this task.\n\nWill you take up the mantle? Will you fulfill the oath my order took so long ago?" }
WordHunterWoW_QuestEN[40955] = { title = "Oath of Service", description = "Assembled before you are many of our world's greatest archers, rangers, beast masters, and trappers, ready to fight the Legion as one.\n\nIt is time to take your first step in becoming a true leader of hunters.\n\nWe gather at the fire pit and take our oaths of service before the statue of Ohn'ahra. Touch the statue and kneel before it while I recite the oath, and the Unseen Path will be reborn!", objectives = "Kneel before the eagle statue and pledge your service to the Unseen Path.", progress = "Ohn'ahra has blessed our order!", completion = "Ohn'ahra has not appeared to us since the order's founding!\n\nThis is surely a sign that with you guiding us, the Unseen Path will triumph over the Legion!" }
WordHunterWoW_QuestEN[40956] = { title = "Survey Says...", description = "It is time to establish the first secure connection in our teleportation network.\n\nTake this beacon to the Ruins of Elune'eth above us and survey the area to find a suitable location.\n\nOnce your survey is complete, place the beacon and I will anchor a connection to it from here.", objectives = "Use the Telemancy Beacon to survey the Ruins of Elune'eth.", completion = "<This seems like a good location for the teleporter.>" }
WordHunterWoW_QuestEN[40957] = { title = "A Strong Right Hand", description = "", objectives = "Even with the support of your fellow hunters, the crusade against the Legion will consume much of your time and attention. It is a war you cannot fight alone.\n\nI first served our order's founder, Namuria Gladesong, acting as her eyes and ears when she was needed elsewhere. It would be my honor to do the same for you, <name>." }
WordHunterWoW_QuestEN[40958] = { title = "Tactical Matters", description = "Now that your artifact is ready, it's time to plan your first strike against the Legion.\n\nSpeak to Tactician Tinderfell, our expert on such matters.", objectives = "Speak to Tactician Tinderfell in the Trueshot Lodge.", completion = "Hail, Pathfinder! It will be my honor to aid you in the fight against the Legion." }
WordHunterWoW_QuestEN[40959] = { title = "The Campaign Begins", description = "The Legion believes we are still reeling from our loss on the Broken Shore.\n\nLet's prove them wrong.\n\nOur scouts have mapped out the Broken Isles, learning everything we can about each region for our imminent assault.\n\nChoose where to strike first, and you will lead the Unseen Path's efforts personally.", objectives = "Choose an initial assault point on the Command Map", completion = "Excellent choice. The campaign against the Legion has begun!" }
WordHunterWoW_QuestEN[40960] = { title = "Luminous Pearl", description = "Balanced upon your fishing hook, you find a pearl unlike any other you've seen before. It shines with a cold, steady light, and its size and weight fluctuate in your hand.\n\nThis is clearly a magical item, and should be brought to a magical person.", objectives = "Bring the Luminous Pearl to Archmage Khadgar in Dalaran.\n\nProvided item:", completion = "A pearl, you say? Well now, let me have a good look at that..." }
WordHunterWoW_QuestEN[40961] = { title = "The Dalaran Fountain", description = "You fished this up, did you? I'm... not quite sure what you want ME to do about that. Here.\n\n<Khadgar pats you on the head.>\n\n\"Good job.\"\n\nWith regard to the pearl... it does seem to be magical, but I couldn't tell you much more than that. Perhaps it might look nice in the Dalaran fountain?", objectives = "Bring the Luminous Pearl to the fountain in Dalaran.\n\nProvided item:", completion = "She's a BEAUTY! I've never seen the like!\n\nYeah yeah, sure, throw 'er in that fountain. Light knows people throw all sorts of other junk in there.\n\n<The pearl glows brighter now, and moves to a spot above the water.>" }
WordHunterWoW_QuestEN[40962] = { title = "Dark Waters", description = "Come with me to the edge of Elune'ara. Its crystal waters can wash away even the darkest shroud to reveal the truth within.", objectives = "Accompany Malfurion to Elune'ara to reveal the nature of the Remnant of Chaos.", progress = "Yes, <race>?", completion = "Malfurion departed in a great hurry, but he bade me give you this before you left. Thank you for all you have done for Azeroth, and for all that you will do in time to come." }
WordHunterWoW_QuestEN[40963] = { title = "Take Them in Claw", description = "We should have seen this coming. My sister is dead, my friends are wounded and we will likely die here.\n\nI want revenge.\n\n<Lyrea hands you a vial full of growing green liquid.>\n\nWe cannot beat them, but we can turn the Stronghold against them.\n\nWild hippogryphs are attracted to the scent in this bottle. Wild hippogryphs are also notoriously violent when the object of their attraction is not a hippogryph.\n\nUse it to clear a path deeper into the stronghold.", objectives = "Attract 3 Wild Moonfall Hippogryphs to deal with the Nightborne at Moonfall Roost.", progress = "I thought I was alone here. Are you here to continue the fight?", completion = "I heard screams, and I was gratified that they belonged to the Nightborne. Well done." }
WordHunterWoW_QuestEN[40964] = { title = "The Rift Between", description = "I was with Lothrius when the Nightborne poured into the stronghold.\n\nHe and his constructs managed to get the majority of us out of the Athenaeum, but he was cornered before he could make good on his own escape.\n\nI know he still lives- I feel it in my gut!- but I cannot go back for him myself. My injuries are too severe.\n\nBeakbuck will take you to where we last saw Lothrius. Simply let him know when you are ready to leave.\n\nGo quickly, and good luck!", objectives = "Locate Lothrius Mooncaller in the Athenaeum.", completion = "Serena sent you? Good... she still lives." }
WordHunterWoW_QuestEN[40965] = { title = "Lay Waste, Lay Mines", description = "They ransacked my library, {name}.\n\nIf they want our knowledge, we will give it to them. \n\nThis piece of rune work will allow you to cast an ensnaring spell on the ground. When the Nightborne cross the threshold they will see the true might of the Moon Guard.\n\nTeach them well!", objectives = "Slay 50 Nightborne With the Trap Rune.", progress = "How fares the education?", completion = "A lesson we all must one day learn. Never assume your enemy dead until you see their corpse. <Lothrius grins.>" }
WordHunterWoW_QuestEN[40966] = { title = "Ritualists in Our Midsts", description = "", objectives = "" }
WordHunterWoW_QuestEN[40967] = { title = "Precious Little Left", description = "I have not been able to leave the safety of my guardians to search, but there are three tomes of great importance to me and mine. \n\nThey contain secrets and cantrips that the Nightborne must NOT obtain. \n\n<Lothrius raises his hand to your forehead, cementing the names of three tomes into your mind> \n\nIf we cannot best them, we must preserve all we can. Hurry, {name}.", objectives = "Locate and recover \"Anthology of the Guard\", \"Magical Manifest of the Moon\", and \"Aftermath of the Well\".", progress = "Did you locate them?", completion = "Thank the Mother Moon... They survived!" }
WordHunterWoW_QuestEN[40968] = { title = "Recovering Stolen Power", description = "My injuries will not kill me, but I cannot fight. I have my own idea of how to deal with the remaining Nightborne.\n\nThey destroyed our defense matrix as soon as they arrived. Surely one of them carries the spell focus necessary to reactivate it.\n\nFind it, then go to a hippogryph. They linger throughout the Stronghold.\n\nThese loyal beasts will take you to the skies and take care of the rest.", objectives = "Acquire a Volatile Spell Focus." }
WordHunterWoW_QuestEN[40969] = { title = "Starweaver's Fate", description = "I will take these tomes to Thalrenus.\n\nThere is one thing that weighs heavily on my mind, and I would like for you to attend to it in my stead. \n\nMy wife and life partner, Syrana Starweaver, resides in the Starweaver's Sanctum across the bridge. It fell shortly after the Nightborne entered the Stronghold. \n\nIf she still lives she will need to know of our efforts. Her power is sorely needed. \n\nGive her my best- I will be along shortly.", objectives = "Locate Syrana Starweaver", completion = "Lothrius and Thalrenus live, then. There may be some hope yet. Thank you for braving the bridge, stranger." }
WordHunterWoW_QuestEN[40970] = { title = "The Orchestrator of Our Demise", description = "Conjurer Thalerian must be stopped.\n\nHe immediately sought out my father's private study when he arrived and he has not yet emerged. I worry that he may have found a very dangerous item.\n\nIt is called the Astromancer's Keystone. It is used to manipulate the stronghold's defenses.\n\nSuch magic was meant to protect the Moon Guard- used for any other purpose and it becomes unspeakably destructive.\n\nRetrieve the Keystone. Slay Conjurer Thalerian to get it, if you must.", objectives = "Slay Conjurer Thalerian and acquire the Astromancer's Keystone.", progress = "Is it done?", completion = "They had no right to this power. Thank you." }
WordHunterWoW_QuestEN[40971] = { title = "Overwhelming Distraction", description = "Do you see the Nightborne outside this room?\n\nThey hold us here, like mice in a cage. It is more convenient for them that we are pinned down while they search the Sanctum for my father's relics.\n\nMy companions and I can escape to higher ground with some help.\n\nTake this crystal. While standing on a mana focusing rune, use it to overcharge a Conjurer.\n\nTheir summons will turn on them and create an opening.\n\nUse it well, and we will meet you atop the stronghold when the way is clear.", objectives = "Overcharge 3 Imperial Conjurers using the Inert Crystal. You must be standing on a Mana Focuser to use the crystal.", completion = "We were able to make it here safely, thanks to you." }
WordHunterWoW_QuestEN[40972] = { title = "Last Stand of the Moon Guard", description = "This is all that remains of the Moon Guard.\n\nTake a good look.\n\nWe are but a shadow of our former selves, and we have the Nightborne to thank for our demise.\n\nFor now there is nothing more we can do. If we want to live, we must leave immediately.\n\nRetribution can wait.", objectives = "Leave Moon Guard Stronghold with Thalrenus, Lothrius, and Syrana.", completion = "I called them here. I will see that they are taken care of after the horrors my people put them through." }
WordHunterWoW_QuestEN[40973] = { title = "Creating Time", description = "Thanks in large part to your substantial efforts, we have discovered the whereabouts of a powerful piece of our history. It should enable us to survive whatever else the Nightborne have to throw at us, and hopefully more.\n\nHowever, recovering it will require a great deal of our energy and focus. We will bolster the Starweaver's scrying efforts, but the slightest disruption will ruin this delicate spellwork. See that we are not disturbed.\n\nSpeak to Syrana Starweaver when you are ready to begin.", objectives = "Defend Syrana Starweaver." }
WordHunterWoW_QuestEN[40974] = { title = "Latosius' Trial", description = "I bow to Latosius' wisdom. If we are to endure, it must be you who claims the Amulet. Survive this challenge, {name}, and the might of the Moon Guard will be yours forevermore.", objectives = "Survive the Trial of Latosius." }
WordHunterWoW_QuestEN[40975] = { title = "Arluin Bribe Tracking", description = "", objectives = "" }
WordHunterWoW_QuestEN[40976] = { title = "Audience with the Warchief", description = "\n\nTensions are running high, demon hunter. Warchief Vol'jin was gravely wounded in a disastrous assault on the Broken Shore.\n\nI suggest you offer your skills in service of the Horde before your presence is... misinterpreted.\n\nHigh Overlord Saurfang commands the city's defenses. Though wary of the Illidari, I believe he will give you a chance to prove your worth.\n\nSpeak to him and request passage into Grommash Hold.", objectives = "Speak to High Overlord Saurfang.", completion = "Vol'jin's death was part of a larger plan. The Legion thrives on weakening its enemies from within. The demons will strike when their enemy is at its most vulnerable.\n\nWhatever grief the Horde's people are feeling, they can no longer afford to ignore us.\n\nOur time is now, Illidari!" }
WordHunterWoW_QuestEN[40978] = { title = "Bears Behaving Badly", description = "", objectives = "" }
WordHunterWoW_QuestEN[40980] = { title = "Boilback Plague", description = "", objectives = "" }
WordHunterWoW_QuestEN[40982] = { title = "Second Sight", description = "Sylvanas becoming Warchief may be problematic. In life she was a proud ranger, known to many in our ranks. But since the Scourge took her, some of her own allies do not trust the Banshee Queen.\n\nThe Legion will strike at the first hint of dissension.\n\nEven now, I sense something amiss, {name}. I fear that not all is as it seems.\n\nQuickly, use your Spectral Sight. We must know if there are foes among us!", objectives = "Use your Spectral Sight.", progress = "Time is precious.", completion = "Of course the Legion would try to infiltrate this funeral. With the leaders of the Horde gathered in one place at one time, it was too tasty of a target for the demons to resist." }
WordHunterWoW_QuestEN[40983] = { title = "Demons Among Them", description = "It is just as we suspected, {name}! The demons thought they could take us by surprise.\n\nQuickly, to arms! Protect the Banshee Queen!", objectives = "Protect the Warchief.", progress = "This is what we were born for.", completion = "Your warning just saved us from what might have been a catastrophic loss. Now we can unleash our vengeance upon this Legion filth.\n\nYou now have my attention, <class>... and perhaps a bit of appreciation as well." }
WordHunterWoW_QuestEN[40984] = { title = "Murkwater Naga Incursion: Highmountain", description = "", objectives = "" }
WordHunterWoW_QuestEN[40985] = { title = "Rimescale Naga Incursion: Highmountain", description = "", objectives = "" }
WordHunterWoW_QuestEN[40986] = { title = "The Dark Riders", description = "The catacombs? I've never heard of such a place. Unless, he means...\n\nThere's a sewer grate along the edge of the river leading to a catacombs underneath Karazhan. I've never paid it much attention, but it could lead to the catacombs that the spirit spoke of. \n\nTo think, the Dark Riders may have been under our noses this entire time! Come, let us see where this leads.", objectives = "Defeat the Dark Riders in the Karazhan Catacombs and claim Apocalypse.", progress = "Did you find what you seek, <class>?", completion = "Though I'll admit I may not have been able to do this alone, I will not forget the transgressions that happened today.\n\nYou have what you came for, <class>. I think it is time you were on your way." }
WordHunterWoW_QuestEN[40987] = { title = "The Call of Vengeance", description = "Our goals have been met, death knight, and it is time we part ways.  I think I will be glad to see the last of you.\n\nGo on, return to your dark masters. We are done here.", objectives = "Take the Death Gate to the Frozen Throne, and receive the Mark of the Lich King.", completion = "The champion of the Lich King returns, and with a mighty weapon to bear against our demon foes!\n\nMay the Burning Legion tremble at the sight of our forces!" }
WordHunterWoW_QuestEN[40988] = { title = "Too Many Cooks", description = "Greetings. I am called Nomi.\n\nI couldn't help but notice that recipe that you just picked up and... well, you'd never guess it, but I'm a bit of a chef myself.\n\nUnfortunately, I'm not much of a fighter, and this place is dangerous. You, on the other hand, are clearly an accomplished {class}.\n\nCome find me in Dalaran. Maybe we can work together!", objectives = "Meet Nomi in Dalaran.", completion = "<class>! I was hoping you'd come back.\n\nHere, take a sample of some of the recipes and dishes I've been working on." }
WordHunterWoW_QuestEN[40989] = { title = "The Prodigal Sous Chef", description = "{name}? Master, is that you?\n\nDon't you recognize me? It's me, Nomi! Remember, we cooked together in Pandaria? More accurately, you cooked and I learned. I was not much more than a cub back then.\n\nBoy, am I glad to see you!\n\nI'm headed back to the Dalaran kitchens. Come find me! Maybe we can work together!", objectives = "Meet Nomi in Dalaran.", completion = "Master <name>!! I knew you'd come.\n\nHere, take a sample of some of the recipes and dishes I've been working on." }
WordHunterWoW_QuestEN[40990] = { title = "A Good Recipe List", description = "I've tried adventuring, and it isn't for me. Cooking is my one true passion: the heat of the stove, the sizzle of bacon... nothing beats it.\n\nLet me help you, Master {name}. If you can bring me some recipes, I can work on improving them, here in Dalaran.\n\nWe'll make a great team. What do you say?", objectives = "Learn 6 Legion cooking recipes.", progress = "We need more recipes before we can do any meaningful work in this kitchen.", completion = "You are truly amazing, Master <name>.\n\nNow, let's get to work, shall we?" }
WordHunterWoW_QuestEN[40991] = { title = "Opening the Test Kitchen", description = "I can cook, but I can't really hunt... or even fish, for that matter.\n\nIf you bring me ingredients, however, I will use them to research new recipes for you.\n\nWe can start with the few fish I managed to scrounge up. You'll find them in the barrel in the back of the kitchen.", objectives = "Obtain 5 of Nomi's Silver Mackerel, then bring them to Nomi to research.", progress = "Mackerel may not be extravagant, but it will fill your belly.", completion = "We've done it! With this technique, we should be able to prepare dried mackerel strips much more efficiently.\n\nI am certain that there is much more we can learn. Keep bringing me ingredients, and I will keep the oven on!" }
WordHunterWoW_QuestEN[40992] = { title = "Honor Among Thieves", description = "", objectives = "You will learn:" }
WordHunterWoW_QuestEN[40994] = { title = "Right Tools for the Job", description = "The blades you wield are among the most powerful in all of Azeroth, but we must always remain two steps ahead of the enemy. Even now their armies grow in strength, and those weapons will make you a prime target for their assassins.\n\nSpeak with Marin Noggenfogger in the Uncrowned Vault next door. He recently completed a project which you will find most intriguing.", objectives = "Speak to Marin Noggenfogger in the Hall of Shadows.", completion = "So, what can I do for you today, Master <name>?" }
WordHunterWoW_QuestEN[40995] = { title = "Injection of Power", description = "Power, eh? You bet! I got just the thing!\n\nWe've managed to get our hands on a rare venom from an uncharted island deep in the south seas. We captured as much of it as we could.\n\nI had my boys build a device that can inject the venom into weapons, but just in small quantities for now until we've got a better handle on its effects.\n\nAnywho, we got it locked up in a secure area just over there. You're free to use it, Shadow <name>... for a price, of course!", objectives = "Convince Marin Noggenfogger to allow you to use the Crucible of the Uncrowned, then use it to empower your artifact.", progress = "It's like my momma used to say - if you've got the coin, we've got a deal.", completion = "Hey, don't even mention it, pal. I'm here for ya any time you need anything!\n\nSeriously though, don't mention it. There are some folks that would do anything to get their hands on this stuff." }
WordHunterWoW_QuestEN[40996] = { title = "Delegation", description = "If I might impart some advice to aid you on the trials and tribulations ahead: do not hesitate to use the many resources of the Uncrowned to aid your efforts.\n\nThere is a communal board in the tavern beyond this chamber where we organize the efforts of our underlings.\n\nSeek out Nikki by the board - she can show you the ropes.", objectives = "Speak to Nikki the Gossip.", completion = "I don't know nothin' about nobody.\n\nOh, who I am I kiddin'? I know everything about everybody! How's it goin', Shadow <name>?" }
WordHunterWoW_QuestEN[40997] = { title = "Lethal Efficiency", description = "Word is you're headin' down to the Broken Isles. That true?\n\nSoon as news got out about the place, we combed through every book, tome, and paper we could get our hands on. We put together quite the report! You should take a look.\n\nWhile you're here, this board is where the magic of the Uncrowned happens. You can put a bounty on a king's head, offer a reward for felsilk cloth... just jot down your latest whim and your agents will take care of it.", objectives = "Select your first assault point on the Broken Isles.", completion = "Great choice! We have tons of intel on that place." }
WordHunterWoW_QuestEN[40998] = { title = "Rendezvous", description = "<class>t <name>, the recruitment operation was successful.\n\nRendezvous in the Hall of Shadows as soon as possible to debrief.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Use your Extraction Point ability to return to the Hall of Shadows." }
WordHunterWoW_QuestEN[41000] = { title = "King Forgalash's Burden", description = "That sea witch spoke the truth.\n\nI witnessed the Tidemistress confer with King Forgalash on several occasions.\n\nKill Forgalash and bring the prow from his shoulder to Fjolrik as proof of his demise.\n\nI will meet afterwards in the center of Jandvik. I need to warm myself by its fires.", objectives = "Retrieve Forgalash's Prow from King Forgalash in Forgalash's Den." }
WordHunterWoW_QuestEN[41001] = { title = "Shatter the Sashj'tar", description = "The Sashj'tar forces may have dwindled, but the Tidemistress has surrounded herself with her fiercest naga.\n\nThis is the time to strike a final crushing blow against the Sashj'tar.\n\nIf we can defeat them now, we may finally break the back of this menace and save Jandvik.", objectives = "Kill 12 Sashj'tar naga in the Sashj'tar Ruins.", progress = "We must defeat the Sashj'tar once and for all.", completion = "We may have finally overcome this naga threat." }
WordHunterWoW_QuestEN[41002] = { title = "A Weapon of the Horde", description = "It would seem I underestimated your initial value.\n\nWe will have need of your kind in the coming war. I plan to hunt these demons to the ends of Azeroth, and your kind will be the arrow I shall loose upon them.\n\nTell your Illidari within Orgrimmar to make ready to serve the Horde.\n\nBut make no mistake, your kind once served the Betrayer. Betray me, and there is no world you can run to that will save you from my vengeance.", objectives = "Report to Elthyn Da'rai at the Illidari camp in Orgrimmar.", completion = "You have proven our worth to the new Warchief. Excellent work.\n\nTo vanquish the Legion, we will need the Horde's strength at our backs." }
WordHunterWoW_QuestEN[41003] = { title = "The Emperor's Gift", description = "Ah, Sheilun, the legendary staff wielded by our last emperor. If the Legion were to acquire this weapon, they could unleash untold horrors across the whole of the continent. They must be stopped!\n\nIf you want to get to the Terrace as fast as possible, you should hitch a ride directly to the mainland. Tak-Tak, a hozen kite-master, is skulking around west of the temple. Speak to him without delay.", objectives = "Retrieve Sheilun, Staff of the Mists, from the Terrace of Eternal Spring. See Tak-Tak to fly directly to the Terrace.", progress = "The Terrace of Eternal Spring is a very sacred place for mainland Pandaren. I hope you were able to preserve it from corruption. Enough of Pandaria was destroyed when Garrosh Hellscream turned it into a battlefield.", completion = "Incredible. The very staff the Emperor used to cloak Pandaria in mists all those ages ago!\n\nTreat that staff well, <name>. It will save your life. And probably the lives of all your friends, as well..." }
WordHunterWoW_QuestEN[41004] = { title = "Jandvik Craftsmanship", description = "{name}, you have slain both Tidemistress Sashj'tar and King Forgalash, an incredible feat for a {race}.\n\nEven without their leaders, I am certain that the naga and the sea giants will regroup and unleash a final assault on us.\n\nWe will need your help if Jandvik is going to survive.\n\nFjolrik and I have devised a plan of attack. Go and speak with him.\n\nBe sure to drag that prow with you. Fjolrik will need it.", objectives = "" }
WordHunterWoW_QuestEN[41005] = { title = "Coastal Cleanup", description = "Toryl wants me to construct a mighty war machine to strike a final blow against the naga. I have a plan to turn the Sashj'tar's own siege weapons against them.\n\nWe sent a war party out earlier to destroy a cluster of ballistae that were assailing Jandvik from the coast.\n\nSift through the wreckage and salvage any useful parts that you can get your hands on.\n\nKeep an eye out for harpoons.", objectives = "" }
WordHunterWoW_QuestEN[41006] = { title = "Assassinate That Guy", description = "", objectives = "" }
WordHunterWoW_QuestEN[41007] = { title = "Building a Better Boat", description = "I am a master craftsman, but even my siege weapons cannot reach the Sashj'tar's base from Jandvik. I will need to construct a seaworthy boat on which to mount my weapon.\n\n<Fjolrik examines the prow.>\n\nYes, this will make a sturdy brace beam for a boat... I think.\n\n<Fjolrik scratches his head.>\n\nI've never built a boat before, but I am certain that if you bring me enough wood, I can construct something that will float.", objectives = "" }
WordHunterWoW_QuestEN[41008] = { title = "Hunter to Hunter", description = "I sense the threads of fate entwined about you. Your destiny is tied to that of the ancient night elf who started you on this journey.\n\nI can send you back to the city in the sky. From there, you must begin the task of gathering allies against the ravenous darkness.\n\nFight well, {name}. May Talonclaw serve you well.", objectives = "Return to the Hunter's Reach shop in Dalaran and speak to Emmarel Shadewarden.I sense the threads of fate entwined about you. Your destiny is tied to that of the ancient night elf who started you on this journey.\n\nI can send you back to the city in the sky. From there, you must begin the task of gathering allies against the ravenous darkness.\n\nFight well, <name>. May Talonclaw serve you well.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[41009] = { title = "Hunter to Hunter", description = "Now that Titanstrike is yours, ye should learn more about the night elf who set us on this journey.\n\nShe might well be back at the Hunter's Reach shop where you met her. Whoever this Emmarel Shadewarden is, I'd bet me beard she has some part to play in the war against the Legion!\n\nThanks again fer the fun, {name}. If ye ever have need of me, just call!", objectives = "Go to the Hunter's Reach shop in Dalaran and speak to Emmarel Shadewarden.", completion = "There is much to do, noble <class>. But first, I suppose you'll want to learn a little more about who I am and why I have sought you out." }
WordHunterWoW_QuestEN[41010] = { title = "Fish Frenzy", description = "{name}!\n\n<pant, pant>\n\nYou've got to see it! The fish, they're... they're everywhere!\n\nOff the coast of Val'sharah, something's whipping them up into a frenzy.\n\nI've never seen better fishing in my life!\n\nI've got a boat down below. Grab your pole and I'll take you there!", objectives = "Follow Nat Pagle to the Gloaming Reef, then dispatch all of the fish in the area.", completion = "What in the world have you brought me?! Nat told you to ask me to turn THIS into a pole?\n\n<Marcia takes the severed lure from you. As she holds it close to the pearl, it begins to resonate with it.>\n\nThat's interesting. There seems to be a connection between this and the pearl. Maybe turning this into a fishing rod can yield some interesting results..." }
WordHunterWoW_QuestEN[41011] = { title = "Umbralshard Rituals", description = "", objectives = "" }
WordHunterWoW_QuestEN[41012] = { title = "Kirin Tor Showdown Seen", description = "", objectives = "" }
WordHunterWoW_QuestEN[41013] = { title = "Darkbrul Arena", description = "", objectives = "" }
WordHunterWoW_QuestEN[41014] = { title = "Fury Road", description = "", objectives = "" }
WordHunterWoW_QuestEN[41015] = { title = "Artifacts Need Artificers", description = "Your weapon is indeed powerful, but we shouldn't rest on our laurels. I've managed to procure one of the dwarves' foremost experts on artifice and enchanting.\n\nI'd like you to speak with Betild and see if she can't infuse the weapon with even greater potency.", objectives = "Speak with Betild Deepanvil in Netherlight Temple.", completion = "Ach, there ye are. Let me see that priceless weapon ye're swingin' 'round like a stick ye bought at the gift shop!" }
WordHunterWoW_QuestEN[41016] = { title = "BC TL", description = "", objectives = "" }
WordHunterWoW_QuestEN[41017] = { title = "Empowering Your Artifact", description = "Since ye're bound an' determined ta crack that thing against every demon on Azeroth, let's see if we can't squeeze what we can out of it. With Saa'ra's power I've reworked this 'ere draenei altar into somethin' ye can use to focus... eh, let's skip that part, shall we?\n\nJust stick the thing in there and give it a whirl!", objectives = "Use the Altar of Light and Shadow.", completion = "Well ain't that nice an' shiny!\n\nYou'll need ta get used to usin' that thing. Then we can mess with it rather than, ye know, puttin' it in a museum and respectin' it for the piece o' history that it is.\n\n You should head back to Alonsus, he's giving us the eye." }
WordHunterWoW_QuestEN[41018] = { title = "UNUSED - Agent of Aid", description = "I see ol' Alonsus there givin' us the eye. That man ne'er sleeps, I tell ye! And now neither will ye, heh!\n\nGo on then, looks like he wants ta introduce ye ta someone.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Speak with Alonsus and his friend.I see ol' Alonsus there givin' us the eye. That man ne'er sleeps, I tell ye! And now neither will ye, heh!\n\nGo on then, looks like he wants ta introduce ye ta someone.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[41019] = { title = "Actions on Azeroth", description = "Let me show you the Command Map. Thanks to some draenei construction and naaru magic we now have a window into the Broken Isles! You can devise strategy, send your agents on missions, and choose our first area to operate in.\n\nTake a look and let me know where we are going!", objectives = "Use the Command Map to select your order's first operational area.", completion = "An excellent choice! We will do our best to support your efforts on the Broken Isles." }
WordHunterWoW_QuestEN[41024] = { title = "Dirge of the Dead", description = "", objectives = "" }
WordHunterWoW_QuestEN[41025] = { title = "Rise of the Fallen", description = "", objectives = "" }
WordHunterWoW_QuestEN[41026] = { title = "Back to the Shadows", description = "", objectives = "" }
WordHunterWoW_QuestEN[41027] = { title = "One Last Breath", description = "<The parchment is soaked in seawater. A note is hastily scribbled on it.>\n\nTo whomever finds this note first,\n\nBefore I was cast from Suramar, I was a master alchemist. In my time, I have concocted many potions and elixirs for the benefit of the Nightborne.\n\nAll of this was forgotten when the Legion came.\n\nBefore I succumb to the hunger, I wanted to create one last draught to celebrate my love of sea.\n\nDrink it and explore the vast deep in my honor.", objectives = "Drink the Nightfallen Alchemist's Strange Draught in Azuregale Bay.<The parchment is soaked in seawater. A note is hastily scribbled on it.>\n\nTo whomever finds this note first,\n\nBefore I was cast from Suramar, I was a master alchemist. In my time, I have concocted many potions and elixirs for the benefit of the Nightborne.\n\nAll of this was forgotten when the Legion came.\n\nBefore I succumb to the hunger, I wanted to create one last draught to celebrate my love of sea.\n\nDrink it and explore the vast deep in my honor.You will learn:" }
WordHunterWoW_QuestEN[41028] = { title = "Power Grid", description = "This station has fallen into disrepair. The circuit is broken, and to mend it we must recharge the seals in the central chamber.\n\nBoth a high potency current and low potency current are needed for each seal. Direct the currents to point at the same seal, then engage the seal.\n\nMe? I shall supervise. You are the help, after all.", objectives = "Charge the Moon Seal, Star Seal, Beast Seal and Elven Seal in Ley Station: Tel'Anor.", completion = "I must admit I am impressed. You may actually be of some use to us." }
WordHunterWoW_QuestEN[41029] = { title = "Tracking Quest for Latosius Challenge 2", description = "", objectives = "" }
WordHunterWoW_QuestEN[41030] = { title = "Sigil Reclamation", description = "The smooth square sigil weighs a fair amount more than its appearance would suggest. \n\nHandling it results in an intense tingling sensation in your palm- this is an object of focused, pure power. \n\nSuch an advantage should not be so easily surrendered to the Nightborne.", objectives = "Collect 7 Moon Guard Sigils.", progress = "What is this?", completion = "You were wise to keep these out of our enemies' hands, <class>. I believe you can be trusted." }
WordHunterWoW_QuestEN[41031] = { title = "For the People", description = "We have a problem, friend.\n\nAcross the canal is a district not well known for affluence. Since the demons' arrival, it has been locked down. I have heard the cries of those who have been deprived of sustenance.\n\nTake this wineskin. Find an Arcwine fountain and take your fill.\n\nFind those who are suffering and offer them a drink. It is the best we can do in the present circumstances.\n\nYou must not be seen doing this, {name}. It will end badly.", objectives = "Locate an Arcwine Fountain to fill your Empty Arcwine Skin, then offer Arcwine to Mana-Starved Nightborne." }
WordHunterWoW_QuestEN[41032] = { title = "Stop the Spell Seekers", description = "The Nightborne are here in force. As if that were not worrying enough, they now bring reinforcements.\n\nI have seen them opening large portals to Suramar.\n\nThrough these portals they have called in their constructs. They are immune to much of my magic and so represent something of a stumbling block to rejoining the others.\n\nFind the portals and close as many as you can. That should buy us some time.", objectives = "Close 3 Spell Seeker Portals.", progress = "I can still sense them, <name>.", completion = "Yes! I can feel their spells receding. Soon I will be able to rejoin Thalrenus!" }
WordHunterWoW_QuestEN[41033] = { title = "Return to Mardum", description = "The gateway is fully functional, {name}. Ooh, I am positively tingling with excitement!\n\nDo let Jace and the others know that we eagerly await your arrival. There's so much to do and ever so little time.\n\nYou will be joining us aboard, won't you?", objectives = "Enter the Illidari Gateway to board the Fel Hammer in Mardum.", completion = "This place is built for war - it's exactly what we need to level the playing field." }
WordHunterWoW_QuestEN[41034] = { title = "Testing the Waters", description = "There is no place that the Sashj'tar can hide from you now, {name}.\n\nThey will not be expecting a direct attack in their waters. This is a perfect opportunity to cut down their commanders.\n\nMeet me in Jandvik after you have slaughtered them.", objectives = "Slay Raz'jira, Malt'his, and Kel'tariss in Azuregale Bay.", completion = "There are sea giants in the bay!?\n\nYou must tell Toryl about this grave news right away." }
WordHunterWoW_QuestEN[41035] = { title = "Felstorm's Plea", description = "You may not know me, but I need your help, {name}.\n\nMeet me in the Violet Gate and I'll explain everything. \n\nMake haste. I fear we have little time.", objectives = "Meet Meryl Felstorm in the Violet Gate in Dalaran.", completion = "I was a fool. I thought that I could banish Kathra'natir once and for all, but instead the dreadlord broke free.\n\nIn the years he spent trapped within my body, he must have been privy to my secrets... such as those of the Council of Tirisfal.\n\nThe damage he could do with this knowledge is unthinkable. He must be stopped." }
WordHunterWoW_QuestEN[41036] = { title = "The Dreadlord's Prize", description = "Kathra'natir escaped my grasp, but I know what his next step will be.\n\nHe seeks an ancient relic called the Forge of the Guardian, used for centuries by the Council of Tirisfal to infuse their power into the Guardian. The forge was hidden away, its location known only to the Council themselves.\n\nNow the dreadlord has this knowledge.\n\nWe must go to the Violet Hold. I only hope we are not too late.", objectives = "Defeat Kathra'natir in Violet Hold.", progress = "We must hurry!", completion = "In times past, the Council of Tirisfal called upon the Tirisgarde, the protectors of Dalaran, to do battle in the Guardian's absence.\n\nIt is clear now that the hall of the Tirisgarde must be rebuilt to face this new threat.\n\nI need your help to accomplish this. First of all, you'll need to know how to get to this hall. I will show you." }
WordHunterWoW_QuestEN[41037] = { title = "Unbridled Power", description = "Although our forces have dutifully held this citadel since your departure, we have been unable to access most of its resources - the Fel Hammer can only be fully activated by those bearing the mark of a Legion lord.\n\nThankfully, your blades carry that very mark. Use them to activate the Fel Hammer - show your forces your limitless power!", objectives = "Activate the Fel Hammer and rally your Illidari forces.", progress = "Yes?", completion = "The Fel Hammer is fully operational." }
WordHunterWoW_QuestEN[41038] = { title = "The Mead Master", description = "The Storm Brew is created by a legendary vrykul brewmaster named Melba. Here is the location of her meadery along the northern Stormheim coast.\n\nIf we can convince her to share her secret recipe with us, we will gain a significant advantage over the enemy.\n\nGrandmaster, how are your skills of persuasion?", objectives = "Speak to Aegira in Stormheim.", progress = "What do you seek?", completion = "My master was loved by many, and she passed her knowledge to me.\n\nHowever, the recipe for Storm Brew, her most fiercely guarded secret, was stolen before she could teach it to me." }
WordHunterWoW_QuestEN[41039] = { title = "Stolen Knowledge", description = "Morjirn, the head brewer of the Tideskorn clan, has the Storm Brew recipe.\n\nI have never been strong enough to assault his fortress alone, but together with you, I think we can claim retribution for my fallen master. I would like nothing better than to pry the recipe from Morjirn's cold, dead fingers.\n\nWhile we are there, we will sample his Storm Brew. I'd like to see if his brewing skills are even near my master's.", objectives = "Taste the Sour Storm Brew, Weak Storm Brew, Blazing Storm Brew, and kill Morjirn for the Storm Brew Recipe.", progress = "Do you have the recipe?", completion = "The last time I saw these notes, I was still a young child.\n\nI understand much of what is written here now.\n\nIt won't be easy to acquire everything here, but I believe we can do it, <name>." }
WordHunterWoW_QuestEN[41040] = { title = "Halls of Valor: The Brewmaster", description = "I've made a new breakthrough with Melba's Storm Brew recipe.\n\nWe need the use of a special cauldron, one owned by Odyn himself.\n\nThis cauldron is located in none other than the Halls of Valor.\n\nThere is only one way to enter this exalted place, and that is through the storm god's favor.\n\nYou must find a way to enter the hall of warriors. You may require allies for this endeavor, {name}.", objectives = "Speak to Melba in the Halls of Valor.", completion = "Hello, champion.\n\nI have been watching you from afar." }
WordHunterWoW_QuestEN[41041] = { title = "Sashj'tar Allies DISBALED", description = "Commander Malt'his was conferring with a sea giant?\n\nWe are prepared to battle the naga, but if they have yoked the strength of the sea giants, we will have to double our efforts to save Jandvik.\n\nYou must tell Toryl about this grave news right away.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Speak with Toryl in Jandvik.Commander Malt'his was conferring with a sea giant?\n\nWe are prepared to battle the naga, but if they have yoked the strength of the sea giants, we will have to double our efforts to save Jandvik.\n\nYou must tell Toryl about this grave news right away.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[41042] = { title = "Champion Chomper", description = "", objectives = "" }
WordHunterWoW_QuestEN[41043] = { title = "Jandvik's First Sailor", description = "It should not take me long to build the boat, but you will need someone to pilot it while you are unleashing havoc on the Sashj'tar.\n\nWhen Brandolf heard about our plan, he volunteered to be your oarsman.\n\n<Fjolrik laughs.>\n\nYou must have made quite the impression on him. No vrykul has dared set boot to boat in an age.\n\nGo speak with him when you are ready to begin your assault.", objectives = "" }
WordHunterWoW_QuestEN[41044] = { title = "Attack and Assail!", description = "I will row with the strength of a titan while you use that contraption that Fjolrik made to send the Sashj'tar back to the black abyss that they came from!\n\nLet me know when you are ready, and we will begin our final assault.", objectives = "" }
WordHunterWoW_QuestEN[41045] = { title = "Matron Moves", description = "", objectives = "" }
WordHunterWoW_QuestEN[41047] = { title = "Infused with Power", description = "The weapon you hold will strike a potent blow against the Legion... but the demons are relentless. Just as your battle tactics grow and evolve, so must your weapon.\n\nThe altar before you courses with ancient magic, and is alive with the skill and dedication of the hunters who have used it through the ages.\n\nPlace your artifact upon it, and over time you will awaken the full potential of your weapon.", objectives = "Use the altar to imbue your artifact weapon with a new power.", completion = "Wondrous! The growing power of your artifact will strike fear into the hearts of the demon army!" }
WordHunterWoW_QuestEN[41048] = { title = "7.0 Suramar - Treasure 003 - Jandvik - twh", description = "", objectives = "" }
WordHunterWoW_QuestEN[41049] = { title = "7.0 Suramar - Treasure 004 - Jandvik - twh", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[41050] = { title = "7.0 Suramar - Treasure 005 - Jandvik - twh", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[41051] = { title = "7.0 Suramar - Treasure 006 - Jandvik - twh", description = "", objectives = "" }
WordHunterWoW_QuestEN[41052] = { title = "A Desperate Plea", description = "{name}, Saurfang has not been the same since our loss at the Broken Shore. Though he led well and slew many, he has taken our defeat hard.\n\nI fear he is determined to return to the Broken Shore. Will you speak to him?", objectives = "Meet with High Overlord Saurfang at Krasus' Landing.", progress = "Will you help?", completion = "Very well, let us see what awaits us on that ill-fated shore.\n\nAt the very least, a lot of dead demons! Hah!" }
WordHunterWoW_QuestEN[41053] = { title = "Altar of the Eternal Hunt", description = "Now that you've rallied hunters from across Azeroth together, it's time to turn your attention to the battle against the Burning Legion.\n\nWithin the Trueshot Lodge is the Altar of the Eternal Hunt. It is an ancient relic alive with old magic, and I believe it can be used to infuse your weapon with even greater might.\n\nGo inside the lodge and speak to Altar Keeper Biehn, who can instruct you in its use.", objectives = "Speak to Altar Keeper Biehn inside the Trueshot Lodge.", completion = "Greetings, <name>. It will be my honor to assist you with your artifact." }
WordHunterWoW_QuestEN[41054] = { title = "Love Lost", description = "Malfurion, my love...\n\nIn vision I saw him, enraged and then distressed, and now lost beyond my mind's reach.\n\n{race}, I know we have little reason to trust one another, but I will not turn away your help.\n\nIf you value the sanctity of this world, you will come with me.", objectives = "Speak with Tyrande Whisperwind at Starsong Refuge.", completion = "Pray my husband makes it through this alive, <race>." }
WordHunterWoW_QuestEN[41055] = { title = "Primal Payback", description = "", objectives = "" }
WordHunterWoW_QuestEN[41056] = { title = "Love Lost", description = "Malfurion, my love...\n\nIn vision I saw him, enraged and then distressed, and now lost beyond my mind's reach.\n\nHe is strong, but the horrors that have befallen this land are all-consuming.\n\nI must find him, and you must help me!\n\nGather your wits, {race}, and follow me.", objectives = "Speak to Tyrande Whisperwind at Starsong Refuge.", completion = "I pray it is not too late, friend." }
WordHunterWoW_QuestEN[41057] = { title = "Primal Payback", description = "", objectives = "" }
WordHunterWoW_QuestEN[41058] = { title = "The Forge of Guardians", description = "First and foremost, the Forge of the Guardian must be protected. With Kathra'natir's knowledge, it will no longer be safe in Violet Hold.\n\nTogether, we should be able to transport it to a safer place. From there, our true challenge can begin.You will learn:", objectives = "Help Meryl and Alodi transport the Forge of the Guardian to a safe location." }
WordHunterWoW_QuestEN[41059] = { title = "Halls of Valor: Odyn's Cauldron", description = "Your actions in Stormheim were courageous. I thank you for avenging me, and for helping my apprentice, Aegira. I can think of none better to inherit my knowledge.\n\nWith you, I will share the secret to my Storm Brew. The true strength of the brew comes from Odyn's Cauldron, which can be found in the great hall just ahead.\n\nYou have my blessing to borrow it. Good luck in your journey ahead, {name}.", objectives = "Collect Odyn's Cauldron from the Halls of Valor, then pass Odyn's trial.", progress = "Did you pass the trials?", completion = "Tell me, were the Halls of Valor as amazing as the stories say? Regardless, you got the cauldron. Now we can begin brewing." }
WordHunterWoW_QuestEN[41060] = { title = "Unbridled Power", description = "Although our forces have dutifully held this citadel since your departure, we have been unable to access most of its resources - the Fel Hammer can only be fully activated by those bearing the mark of a Legion lord.\n\nThankfully, your blades carry that very mark. Use them to activate the Fel Hammer - show your forces your limitless power!", objectives = "Activate the Fel Hammer and rally your Illidari forces.", progress = "Yes?", completion = "The Fel Hammer is ours at last.\n\nNicely done." }
WordHunterWoW_QuestEN[41062] = { title = "Spoils of Victory", description = "The Fel Hammer will be a fine home for our kind, but it is what we found within its depths that is the true prize of our conquest.\n\nBattlelord Gaardoun and his Ashtongue have it closely guarded - you should have him show you.", objectives = "Have Battlelord Gaardoun show you what your forces obtained.", completion = "It is my honor to serve, <name>." }
WordHunterWoW_QuestEN[41064] = { title = "Cursed Forge of the Nathrezim", description = "Even as we speak, the Legion's dark masters fashion new horrors in hopes that they might destroy us - especially you.\n\nYou must increase your own power as well.\n\nThe Cursed Forge of the Nathrezim, our greatest treasure from taking the Fel Hammer, waits in the chamber ahead. You can use it to further empower your blades and maintain our edge over the enemy.", objectives = "Use the Cursed Forge of the Nathrezim to empower your artifact.", progress = "Your blades... they glow with such power...", completion = "Such power! The Legion's armies will fall before you in droves." }
WordHunterWoW_QuestEN[41065] = { title = "Troubling News", description = "Master, there is one more thing I wish to speak to you about.\n\nBelow us lies an open chamber cut off from the rest of the citadel. We thought you might desire it as your personal sanctum - a place where you might gather your thoughts or scry upon your enemies.\n\nThe sanctum crystal before you will transport you there - Lady S'theno has already descended to help you get acquainted.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Use the Sanctum Crystal to enter the Master's Sanctum." }
WordHunterWoW_QuestEN[41066] = { title = "The Hunter's Gaze", description = "{name}, before you lies your nether crucible - more powerful than any we've crafted before.\n\nThe souls of the hundreds of slain demons in Mardum have provided us with enough power to directly observe the Legion on Azeroth.\n\nWhat we have uncovered so far has been... unsettling. Gaze into the pool and see for yourself.", objectives = "Use the Empowered Nether Crucible to gaze upon the Burning Legion's forces in Azeroth.", progress = "The Legion threat is more dire than we thought.", completion = "We must not underestimate the Legion - I fear they are even more powerful than we realize." }
WordHunterWoW_QuestEN[41067] = { title = "Time is of the Essence", description = "As you can see, there is little time to spare - the Legion's armies already encroach on our world.\n\nKayn has gathered our best tacticians around the star map above us to discuss our plan of attack - your leadership would be invaluable to their efforts.", objectives = "Speak to Kayn Sunfury.", completion = "<Kayn sighs.>\n\nI know that look. I, too, gazed into the crucible and saw the horrors of the tomb.\n\nWe must act quickly." }
WordHunterWoW_QuestEN[41069] = { title = "Direct Our Wrath", description = "We must seal the Tomb of Sargeras at all costs or the flow of demons will never cease.\n\nUntil then, we must do what we can on the ground to alleviate their foothold before it grows further.\n\nThis citadel was created to spearhead Legion invasions on other worlds - we can use its navigation systems to plan our assault.\n\nI think you would agree that none would be better suited to lead our charge than you.", objectives = "Select your first assault point on the Broken Isles.", completion = "Agreed. You are as skilled a tactician as myself." }
WordHunterWoW_QuestEN[41070] = { title = "Spoils of Victory", description = "In conquering this citadel we obtained something that I think would be of great use to you.\n\nGaardoun's men have it well-guarded just below - I suggest you have him show you.", objectives = "Have Battlelord Gaardoun show you what your forces obtained.", completion = "It is my honor to serve, <name>." }
