WordHunterWoW_QuestEN[41214] = { title = "Parts Unknown", description = "Brambley... I still canna' believe it.\n\nI canna' leave the lad here... not in this place... not like this.\n\nHelp me find the rest of him, so I can take his remains back home where he belongs.\n\nWe'll give him a proper burial... it's what he deserves!", objectives = "Collect Brambley Morrison's remains.", progress = "Aye, is that all of him? We aren't missing any parts are we?", completion = "<Angus wipes away a tear as he speaks.>\n\nBrambley, lad... I promise ye'll have tha' best burial money can buy! An' all the ale ye can drink..." }
WordHunterWoW_QuestEN[41215] = { title = "They Become The Hunted", description = "The trapper you slew was but one of many.\n\nThe Nightborne are subjugating the local creatures, creating a sort of pleasurable exhibit. I think we can strike them in two places at once.\n\nDescend upon these trappers, {race}. Let us teach them a lesson in respecting their prey.", objectives = "Slay 6 Nightborne Trappers.", progress = "With the number of trappers thinned, their ability to scout into Suramar will be sorely hampered.", completion = "Excellent work. They do not respect the hunt, so they must be reminded of their place." }
WordHunterWoW_QuestEN[41216] = { title = "Survival of the Fittest", description = "The collar you took from the trapper is simple, but effective. Affixing the collar to a target will make them complacent and obedient to their Nightborne masters. Lilryia was able to reverse the spell using the traps you found.\n\nThe magics in the collar can now be used to cancel out the other collars.\n\nHow about giving the Nightborne a reminder that nature always finds a way?", objectives = "Free 12 exhibits from the Menagerie.", completion = "I could hear their cries and see the carnage from here! That will teach the Nightborne to enslave creatures. Have they fallen so far during all those years under the shield?" }
WordHunterWoW_QuestEN[41217] = { title = "The Future of Gnomeregan", description = "It's a victory for us every time we're able to help another survivor escape from the contaminated halls of Gnomeregan. {class}s like you will play an important part in the future of Gnomeregan. To that end, our leader, High Tinker Mekkatorque, has assembled a team of trainers to help you learn your arts.\n\nMuffinus Chromebrew will help oversee your training and adjustment to life on the surface. He's waiting for you on the stands across the road.", objectives = "Meet with Muffinus Chromebrew in New Tinkertown.", completion = "For a <race> who has spent so much time inside Gnomeregan, you look positively fit and healthy, <name>. That's good. Before we can complete what Operation: Gnomeregan began, we're going to need more hunters like you." }
WordHunterWoW_QuestEN[41218] = { title = "Meet the High Tinker", description = "I don't know if you'll remember Mekkatorque or not. Nevin tells me that memory loss is pretty common for a Gnomeregan survivor.\n\nMekkatorque, or more properly, the High Tinker Mekkatorque is the leader of all the gnomes. He has made a habit of meeting with every rescued survivor personally. You should introduce yourself to him. He'll be with his war council beneath the tent in the center of town.", objectives = "Introduce yourself to High Tinker Mekkatorque in New Tinkertown.", completion = "It's good to meet you, <name>. You've probably heard others speaking of Operation: Gnomeregan. Let me tell you a bit about what happened and why we left the dwarven city of Ironforge." }
WordHunterWoW_QuestEN[41219] = { title = "Flourishing Foxflower", description = "", objectives = "" }
WordHunterWoW_QuestEN[41220] = { title = "Down to Azsuna", description = "{name}, we must find a way to reseal the Tomb of Sargeras.\n\nI have uncovered information concerning an ancient relic, which might be the key to stopping the Legion.\n\nOur search begins on the ancient elven island of Azsuna. Long ago, it was where the Highborne elves of Suramar perfected their mightiest of magics. Now it is a cursed ruin.\n\nThe Illidari demon hunters have established a camp on the island. As they are the only people we know in the area, that is where we will begin.\n\nReady to take wing?", objectives = "Speak with Archmage Khadgar to fly down to Azsuna.", progress = "It would seem that we have arrived at the crucial moment.", completion = "As I suspected, the Illidari are holding the line against the Burning Legion, but just barely.\n\nWe must come to their aid, <name>." }
WordHunterWoW_QuestEN[41221] = { title = "Return to Mardum", description = "The gateway is fully functional, {name}. Ooh, I am positively tingling with excitement!\n\nDo let Jace and the others know that we eagerly await your arrival. There's so much to do and ever so little time.\n\nYou will be joining us aboard, won't you?", objectives = "Enter the Illidari Gateway to board the Fel Hammer in Mardum.", completion = "This citadel was one of the Legion's most valuable assets - it will serve us well." }
WordHunterWoW_QuestEN[41222] = { title = "Into The Pit!", description = "The felstalker pits?!\n\nThere's no time to waste, {name}!\n\n I canna' tell ye what the Burnin' Legion has planned for ol' Brambley, but it canna' be good!\n\nHurry! We've got to find him before the Burnin' Legion has their way with him!", objectives = "Escort Angus to Felmaw Cavern in Felsoul Hold.", progress = "We've got to get to the felstalker pits an' save Brambley!", completion = "It canna' be true!\n\nBrambley... my dear ol' friend! Why did ye have to go an' die?" }
