WordHunterWoW_QuestEN[41226] = { title = "Breaking Out", description = "We cannot fight our way out of the Vault alone.\n\nTwo of your allies, Kayn Sunfury and Altruis the Sufferer, are imprisoned within this room. \n\nFree them with haste. Their strength will be of great use to us.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Free both Altruis the Sufferer and Kayn Sunfury.We cannot fight our way out of the Vault alone.\n\nTwo of your allies, Kayn Sunfury and Altruis the Sufferer, are imprisoned within this room. \n\nFree them with haste. Their strength will be of great use to us.You will receive:\n\nUpon completion of this quest you will gain:" }
