WordHunterWoW_QuestEN[41230] = { title = "Trapping Evolved", description = "The Nightborne are using magic for everything, even trapping.\n\nNighteyes saw them at work, laying down magical snares to capture prey rather than the kind our people use. \n\nBring me their traps so that I may study their make.", objectives = "Collect 4 Arcane Traps for Lilryia.", progress = "Do you have the snares, <race>?", completion = "These devices are peculiar. They are like the traps our hunters use, but can magically attract and trap nearby beasts." }
WordHunterWoW_QuestEN[41231] = { title = "Apex Predator", description = "I have good news and bad news, {race}.\n\nThe bad news is that they somehow managed to capture and train a Devilsaur.\n\nThe good news is that it doesn't seem to have a collar and is tame. I imagine it must think that one of the Nightborne in there is its master. Find the pack leader and take him out, and we will set quite a beast upon them.", objectives = "Find and slay the Nightborne keeping Su'esh obedient.", progress = "Did you find the alpha?", completion = "I saw everything from out here. That was... messy." }
