WordHunterWoW_QuestEN[41255] = { title = "Sowing The Seed", description = "Your weapon is ancient and powerful but it holds the potential to be so much more.\n\nTake this seed, it is all that remains of a forest that grew tall when the world was young. Plant it within the grove to the west and allow it to take root.\n\nWith its power both it and your weapon will be far more than they are alone.", objectives = "Plant the Seed of Ages in the Soft Soil within The Dreamgrove.", completion = "Excellent. There's no time to waste." }
WordHunterWoW_QuestEN[41256] = { title = "Blast of Spice Fish", description = "I have an ingredient that will make my fruit irresistible.\n\nNot many remember the delicacy of manatrout liquor. Its pungent aroma, the unctuous mouthfeel...\n\nThe toads near the northern river concentrate this additive in their gizzards. Fetch some stomachs for me, and we will have plenty.", objectives = "Collect Toad Gizzards for Keelay.", progress = "Daglir is young and foolish!", completion = "Manatrout was completely fished out of our harbors. Since the shield was raised all we have had of the liquor is memories on our palates." }
WordHunterWoW_QuestEN[41257] = { title = "Warden Tower Assault: Cordana's Apex", description = "", objectives = "" }
WordHunterWoW_QuestEN[41258] = { title = "Fruit of the Doom", description = "Now is the time to strike.\n\nShadowbloom has... potent digestive qualities. Go sprinkle some on Daglir's fruit bowls and watch the show.\n\nMeanwhile, I will use the manatrout liquor to cement my position as the premier fruit vendor in the city.", objectives = "Poison 3 Bowls of Fruit.", progress = "Daglir will be ruined after this.", completion = "Victory tastes sweeter than any dish, even one of mine." }
