WordHunterWoW_QuestEN[41307] = { title = "All That Glitters", description = "Now that the shield is down, the older settlements outside the city have been on my mind.\n\nDid you know that I helped create the filigree on the arcane lamps that are used throughout the city? A simple task, one of my first...\n\nNo matter. Nostalgia is the enemy of progress. The lamps are made of material better used in my new works.\n\nThose wretched harpies probably have several decorating their nests. Bring back any you find.", objectives = "Retrieve 6 Arcane Glowlamps.", progress = "Can you imagine, a Lespin original hiding under a pile of leaves? What a waste.", completion = "Excellent. I shall have these melted down and turned into ingots for my next batch of commissions." }
WordHunterWoW_QuestEN[41308] = { title = "Border Reinforcements", description = "", objectives = "" }
WordHunterWoW_QuestEN[41309] = { title = "Mangelrath", description = "The demonic beast that stands before ye, must be the one that devoured ol' Brambley...\n\nJust look at it, lying there with a full belly! I canna abide it any longer, {name}! We must slay the foul creature and avenge Brambley!\n\nWe've come this far already, {class}.\n\nAre ye with me?!", objectives = "Defeat Mangelrath.", completion = "It's good to see a friendly face, I don't know how much longer I could have held out on my own!" }
