WordHunterWoW_QuestEN[41332] = { title = "Ascending The Circle", description = "Now, you are more powerful than ever! Truly, you are a druid without equal, {name}.\n\nI sense that Malfurion has arrived. He will certainly want to know of your accomplishments, but first, please walk with me a moment.", objectives = "Accompany Archdruid Greathoof and then speak with Malfurion Stormrage.", progress = "Yes?", completion = "Congratulations, Archdruid <name>.\n\nWe will be counting on you in the days ahead." }
