WordHunterWoW_QuestEN[41335] = { title = "The Elements Call...", description = "Nobundo is right. Conventional tactics will not work against the Legion - the Broken Shore taught us that. We must scour the world for weapons to use against the Legion!\n\nThe Doomhammer is missing and must be recovered. Rehgar and Erunak have some other ideas, as well. Whatever our course, we must act immediately.\n\nSpeak with me to go over your options, but the final decision is yours!", objectives = "Speak with Thrall and choose the Artifact you wish to pursue.", progress = "Have you made your decision yet?", completion = "A good choice. There is no time to lose - let us begin!" }
