WordHunterWoW_QuestEN[41436] = { title = "In Deep Slumber", description = "This bed will be yours for the deep slumber that will usher you into the Dream.\n\nOnce you are comfortable, drink of the moonwater you brought. I will guide you from there.\n\nQuickly, now - with every passing moment G'Hanir slips further into darkness.", objectives = "Enter the Emerald Dream and retrieve G'Hanir.", progress = "Were you able to retrieve G'Hanir?", completion = "Delving into the Dream with such darkness encroaching is no simple task, one few druids dare attempt, but I'm afraid your journey is far from over." }
