WordHunterWoW_QuestEN[41449] = { title = "Join the Dreamer", description = "I'm afraid I can't really help you actually enter the Emerald Dream - we dryads merely shift our bodies between the planes.\n\nThat's ok, though - Naralex has offered to help!\n\nGo to the very bottom of the Tel'Andu Barrow Den. Naralex is already there setting things up for you.", objectives = "Find Naralex deep within the Tel'Andu Barrow Den.", completion = "My preparations are complete. Are you prepared to enter the Dream?" }
WordHunterWoW_QuestEN[41451] = { title = "Assault on Hrydshal", description = "", objectives = "" }
WordHunterWoW_QuestEN[41452] = { title = "Feline Frantic", description = "Greetings, stranger.\n\n<Mayruna bows to you.>\n\nWe arrived from Val'Sharah a short time ago with hopes of settling here. Our journey was not easy and we are weary.\n\nThese owlcats have made a mess of our camp, as you can surely see. Would you be so kind as to assist us with cleaning up?\n\nThen perhaps you can help us establish a new moonwell!", objectives = "Organize the camp.", progress = "Is everything in its proper place?", completion = "All is in its proper place. We are that much closer to being settled." }
WordHunterWoW_QuestEN[41453] = { title = "Homeward Bounding", description = "The first step to establishing a moonwell is to gain the blessings of the local wildlife. \n\nIt is their good will that enables us to  peacefully coexist, and a moonwell thrives on such energies. Combined with Elune's light, a moonwell can purify its surroundings for years.\n\nTo begin, we must find creatures willing to give their blessing. We can start with these owl-cat creatures.\n\nThey ran while you cleaned, but I saw one lingering just before the bridge. \n\nSee if you can find where it lives!", objectives = "Chase the Lost Feathermane Kitten across the bridge and return it to its family.", progress = "Did you bring the little one back with you?", completion = "Well this is an interesting turn of events." }
WordHunterWoW_QuestEN[41454] = { title = "Luminous Leystone Outcropping", description = "", objectives = "" }
WordHunterWoW_QuestEN[41455] = { title = "Gleaming Leystone Outcropping", description = "", objectives = "" }
WordHunterWoW_QuestEN[41457] = { title = "Radiant Leystone Outcropping", description = "", objectives = "" }
WordHunterWoW_QuestEN[41458] = { title = "Hardened Leystone Outcropping", description = "", objectives = "" }
WordHunterWoW_QuestEN[41459] = { title = "Dense Leystone Outcropping", description = "", objectives = "" }
WordHunterWoW_QuestEN[41460] = { title = "Primal Leystone Outcropping", description = "", objectives = "" }
WordHunterWoW_QuestEN[41461] = { title = "Malevolent Felslate Outcropping", description = "", objectives = "" }
WordHunterWoW_QuestEN[41462] = { title = "Trouble Has Huge Feet", description = "The Ettin's hide bears many shallow scratch marks and bite scars. It seems he had been terrorizing the local Owlcats for quite some time.\n\nMardranel Forestheart would be interested in this.", objectives = "Take the Grotesque Ettin Leather to Mardranel Forestheart.", completion = "Ahhhh... Well done, I am sure our furry friends here are very thankful for your efforts." }
WordHunterWoW_QuestEN[41463] = { title = "Missing Along the Way", description = "As we retreated from Val'Sharah, our company was briefly separated by a conflict with some satyrs at the border.\n\nOne of our own did not make it here- Mythandros' brother, Kalendros. I would like you to try and find him if you could.\n\nSearch the woods just before the bridge back into Val'Sharah.", objectives = "Locate Kalendros Irongrove.", completion = "How good of Mayruna to send help. I had nearly lost hope." }
WordHunterWoW_QuestEN[41464] = { title = "Not Here, Not Now, Not Ever", description = "I cannot, will not, accept what is happening here. My body resists me, but I will stop this.\n\n<He looks at you.> You will stop this.\n\nHere is a root of the corrupted World Tree Shaladrassil. It has somehow found its way out of the ground to this untouched place and already the Darkfiend satyrs are hard at work corrupting Suramar.\n\nStop them. Kill the satyrs, take their horns, drive their points through the totems.\n\nOnly then can we have any hope of reversing this.", objectives = "Use Satyr Horns to destroy 3 Darkfiend Totems.", progress = "Have you stalled their efforts, <race>?", completion = "I am relieved, though there remains more we must do." }
WordHunterWoW_QuestEN[41465] = { title = "Estate Jewelry: A Braggart's Brooch", description = "Amateur merchants worry about losing face from bad products. Masters worry about losing face from bad customers.\n\nNaltethis Springblade has grown too bold for his station, and as such has lost much standing in the eyes of the city's elite.\n\nI sold this man a brooch, a clasp he wears on his cape. I am careful to only sell to those above my station.\n\nMy pieces never tarnish, but my name and reputation are much more fragile. Relieve him of my property before he lowers me further.", objectives = "Retrieve Lespin's Brooch from Naltethis Springblade.", progress = "That oaf will undo years of hard work. It is so much easier to fall than it is to climb...", completion = "Ahh, see! I told you it would not tarnish. Now there's nothing linking me to that fool...\n\nWhat's that? A plot to weaken his position? Regardless, the damage has been done. Better safe than sorry." }
WordHunterWoW_QuestEN[41466] = { title = "Estate Jewelry: Haute Claw-ture", description = "An amateur merchant looks back on their previous work as a learning experience. A master knows that some things are better left forgotten.\n\nI was... vain, centuries ago. Desperate to prove myself, I took on a bold commission.\n\nFind him and bring... it... back. You will know what I am talking about when you see it.\n\nHe resides near the villa south of this courtyard.", objectives = "Find and retrieve Lespin's 'art' from Mornath.", progress = "He was so passionate, so driven. I saw his vision, created it to his exact specifications. Beautiful filigree and enamel put to a fearsome weapon...", completion = "By the Magistrix, I had forgotten how ugly that thing is. Impeccable workmanship, obviously. Just... ugh. I should melt the whole thing down." }
WordHunterWoW_QuestEN[41467] = { title = "The Only Choice We Can Make", description = "Take this torch, {name}. \n\nWe cannot reverse the Nightmare corruption once it has taken hold. All we can hope to do is destroy its manifestations.\n\nIncinerate the root. Only then can we rest easy in Suramar.", objectives = "Incinerate the Shaladrassil Root.", completion = "What a disturbing tale!" }
WordHunterWoW_QuestEN[41468] = { title = "Mistress of the Claw", description = "The great forest guardian, Ursoc, gave his life for this world ten thousand years ago. After the guardian's death his claws were hidden away, safe from any who would use their power for evil.\n\nLea Stonepaw and her Druids of the Claw consider Ursoc their paragon and dedicate their lives to following in his example. If anyone would know where the claws reside, it would be Lea.\n\nShe and her Druids of the Claw reside in the Tel'Andu Barrow Den just to the north.", objectives = "Find Lea Stonepaw.", completion = "The Claws of Ursoc?\n\nI thought I'd go the rest of my days without hearing of them again. Is our situation truly so dire? They were sealed away for good reason!" }
WordHunterWoW_QuestEN[41469] = { title = "Return to Irongrove Retreat", description = "We have three blessings from the creatures we share this land with.\n\nCombined with a blessing from Elune, the moonwell will watch over this land for years to come.\n\nMeet Mythandros at the retreat. I am sure he would like to include you in the ritual.", objectives = "Seek Mythandros at Irongrove Retreat.", completion = "Welcome back. I see we are ready to begin." }
WordHunterWoW_QuestEN[41473] = { title = "Redhoof the Ancient", description = "While you were busy assisting the Owlcats across the river, Mythandros and Solendra ventured further to the east.\n\nI believe Mythandros may have found the next creature that may offer us its blessing.\n\nThere is a secluded glade along the river's bend to the Northeast. There you may find our new ally, an elderly stag named Redhoof.", objectives = "Locate Mythandros and Redhoof the Ancient.", completion = "This fine gentleman was just telling me how dearly he loves his forest. Let us assist him!" }
WordHunterWoW_QuestEN[41474] = { title = "Fertilizing the Future", description = "Like most herbivores, our antlered friends will eat anything green enough to chew. \n\nHowever I have noticed that they seek these patches of dark grass, given their preference. I believe we can begin to earn their favor if we aid the forest in producing more of this most nutritious of stag food.\n\nI will provide you with the seeds- all you must do is locate suitable growing soil and plant them. Our magic will do the rest.", objectives = "Plant 5 Lush Grass Seeds in piles of Rich Soil.", progress = "How goes the planting?", completion = "They are looking better fed already!" }
WordHunterWoW_QuestEN[41475] = { title = "Prongs and Fangs", description = "Now, {name}, do not mistake me- I am a druid. I understand that nature has a balance.\n\nPredators must feed, and others will be hunted. I also understand that tampering with such balance has consequences.\n\nThat is why I have taken upon myself to walk this land and perform some... ah... calculations.\n\nSlay only a small number of the wolves you find, and one alpha. That should reduce their number enough to allow the Sablehorn to thrive without disrupting the flow of things here.", objectives = "Slay 8 Suramar Snarlers and Gloomfang.", progress = "Are you being gentle with your pruning?", completion = "In the end, they will all thrive- for with more Sablehorn, the wolves will eat better in the years to come." }
WordHunterWoW_QuestEN[41478] = { title = "The Final Blessing", description = "My friend Solendra Featherdown went to explore the habitat of the native Nightsabers. \n\nNow that we have the blessings of the Feathermane and the Sablehorn it is time to seek the blessing of the Nightsabers. She is just on the other side of this glade, to the North.", objectives = "Speak to Solendra Featherdown.", completion = "Welcome, <race>." }
WordHunterWoW_QuestEN[41479] = { title = "Natural Adversaries", description = "I have walked this land in the time since our arrival. Here, basilisks have emerged from the ravines to the east. They encroach upon the home of the Nightsabers.\n\nTo earn their blessing, I believe we should clear the way for their return.\n\nSlay the basilisks that have taken more than their fair share of the land, {race}.", objectives = "Slay 8 Manascale Basilisks.", completion = "Well done, <race>." }
WordHunterWoW_QuestEN[41480] = { title = "Managazer", description = "There is one basilisk here who has gorged himself so thoroughly on Nightsaber flesh that he seldom leaves his cave.\n\nWe will use this to our advantage.\n\nSeek out the basilisk Managazer and use his death as an example to the others who have strayed from their home.", objectives = "Slay Managazer, the Basilisk Lord.", progress = "Managazer must perish, <race>.", completion = "Such a gluttonous creature." }
WordHunterWoW_QuestEN[41481] = { title = "Brimstone Destroyer", description = "", objectives = "" }
WordHunterWoW_QuestEN[41482] = { title = "Brimstone Destroyer", description = "", objectives = "" }
WordHunterWoW_QuestEN[41483] = { title = "Brimstone Destroyer", description = "", objectives = "" }
WordHunterWoW_QuestEN[41484] = { title = "Brimstone Destroyer", description = "", objectives = "" }
WordHunterWoW_QuestEN[41485] = { title = "Moonwhisper Rescue", description = "As a druid I understand that predation happens. Creatures that eat meat must acquire meat.\n\nBut this...\n\n<Solendra gestures angrily toward a nearby petrified nightsaber.>\n\nThis is just sad. Free them, {race}. Take my blessing and free them from this needless torment.", objectives = "Free 5 Petrified Nightsabers using Solendra's Gift.", progress = "Have you freed them, <race>?", completion = "I am much relieved, <name>." }
WordHunterWoW_QuestEN[41486] = { title = "Brimstone Destroyer", description = "", objectives = "" }
