WordHunterWoW_QuestEN[41499] = { title = "Squid Out of Water", description = "Toryl told me about those squid creatures that are controlling my brothers.\n\nI have never seen anything like them before around Jandvik. The naga must have brought them from wherever they came.\n\nI do not want any more of my kin to suffer the fate of being controlled by the naga.\n\nFind out where those squids come from and stop them.", objectives = "Destroy 5 Willbreaker Incubators in the Sashj'tar Ruins.", completion = "The naga will not be taking any more of my kin!" }
