WordHunterWoW_QuestEN[41540] = { title = "Rendezvous with the Courier", description = "Thas'dorah is a mighty bow indeed! The weapon was carved from a limb of Thas'alah, the mother tree of Eversong, and infused with the magic of the Sunwell. I fought alongside its first wielder, Talanas Windrunner, during an Amani troll incursion.\n\nAh, but such tales can wait for another time.\n\nCourier Larkspear was making preparations to depart. You can meet him at Krasus' Landing.", objectives = "Speak to Courier Larkspur at Krasus' Landing.", completion = "I don't know the full details, but a demon prisoner has given us the first solid lead on Alleria Windrunner's whereabouts in a very long time.\n\nThe ranger-general has joined with members of the Farstriders on the Broken Shore. She's putting a team together, and your presence is crucial to its success." }
WordHunterWoW_QuestEN[41541] = { title = "A Beastly Expedition", description = "I know the power of Titanstrike well. The Unseen Path battled the vrykul warlord Volund as he campaigned to conquer the Broken Isles. We sought to wrest the rifle from him, but he took it to his grave.\n\nIf Volund's tomb can at last be opened, the artifact would be a great boon to our cause.\n\nI believe Grif Wildheart is making preparations to depart. You can meet him at Krasus' Landing.", objectives = "Speak to Grif Wildheart at Krasus' Landing in Dalaran.", completion = "There you are! I knew you'd be bitin' to find Titanstrike.\n\nDon't mind ol' Huey here. The city of mages is no place for a gryphon." }
WordHunterWoW_QuestEN[41542] = { title = "Preparation for the Hunt", description = "Talonclaw is a mighty spear indeed! I first set eyes upon it when the Highmountain tauren led the members of my order up to Talon Peak to found the Trueshot Lodge.\n\nBut such tales must wait for another time.\n\nApata has been in Dalaran gathering supplies for her expedition. I imagine she's ready to depart by now.\n\nSeek her out at Krasus' Landing. I know she will be eager to begin.", objectives = "Speak to Apata Highmountain at Krasus' Landing in Dalaran.", completion = "My brother Wuho and I will be honored to have you on this quest, <name>. Talonclaw is a sacred artifact to my people, and I know with your help we will recover it.\n\nWe just have to do one thing before we head out, speak with the Eagle Spirit." }
