WordHunterWoW_QuestEN[41574] = { title = "Stolen Thunder", description = "Titanstrike is in the tomb of Warlord Volund somewhere on the isle of Shield's Rest. It's a dank, sloppy mess adrift in a sea of gloom.\n\nSounds lovely, eh?\n\nI've been workin' with a vrykul guide named Prustaga. She'll help us break the wards keepin' the tomb sealed.\n\nI know what you're thinkin'... vrykul are trouble. But she hasn't taken a swing at me just yet.\n\nHuey'll take us down to the shore. Prustaga's probably found the tomb by now!", objectives = "Accompany Grif Wildheart to Shield's Rest Island and track down Titanstrike.", progress = "It's a good thing you found my observation relay! It's been missing for at least a thousand years.", completion = "You might feel a bit dizzy after going through that teleporter. The Broken Isles isn't exactly next door, after all." }
WordHunterWoW_QuestEN[41575] = { title = "Felsoul Teleporter Online!", description = "<The telemancy beacon is deactivated, but intact. Some Ancient Mana should get it back up and running.>", objectives = "Infuse the Beacon with Ancient Mana.", progress = "<The beacon is cold and dark.>", completion = "<The beacon glows as you infuse it with Ancient Mana.>" }
