WordHunterWoW_QuestEN[41606] = { title = "Finding Brytag", description = "<Kell barely manages to speak.>\n\nThat naga witch... has given many of my kin... to the sea giants.\n\nBrytag was... the last one I saw alive.\n\nFind him quickly.", objectives = "Locate Brytag in Azuregale Bay.", completion = "I do not know who you are, but you are not a sea giant, and that is enough for me." }
WordHunterWoW_QuestEN[41607] = { title = "Taking a Promenade", description = "We must learn much about our long-lost kin if we are to fight them.\n\nWe dispatched one of our scouts to infiltrate the Promenade and gather intelligence. The Sentinels sent their own scout as well, hopefully she is smart enough to not get herself killed before reporting in.\n\nThey have not returned in some time, and we must suspect the worst.\n\nFind them and we shall see what we are up against.", objectives = "Locate the scouts in the Promenade.", completion = "They are alive? That is good news. Their knowledge of the defenses will be invaluable." }
