WordHunterWoW_QuestEN[41618] = { title = "The Seawarden", description = "The Seawarden made a deal with the Tidemistress. She handed us over to him like cattle.\n\nI despise that sea giant! If I were not trapped in this bubble, I would choke the life out of him with my own two hands.\n\nIf you cross his path before I get out of here, make him regret ever making a deal with the naga!", objectives = "Kill Seawarden Largush in Azuregale Bay.", progress = "Have you slain the Seawarden?", completion = "I only wish that I had the chance to get to him first.\n\nBah! His body can rot in these waters for all I care." }
WordHunterWoW_QuestEN[41622] = { title = "Crawliac's Legacy", description = "[ph] Defend the bluffs!You will receive:\n\nUpon completion of this quest you will gain:", objectives = "" }
WordHunterWoW_QuestEN[41623] = { title = "Champions of Highmountain", description = "", objectives = "" }
WordHunterWoW_QuestEN[41624] = { title = "Rocko Needs a Shave", description = "", objectives = "Defeat Rocko in a pet battle." }
WordHunterWoW_QuestEN[41625] = { title = "The Light's Wrath", description = "Light's Wrath... a bold choice. Though if you believe you can control its energies, it could prove vital to our cause.\n\nRetrieving it won't be easy. It was last held by the Kirin Tor, who, fearing its unbridled power, handed it to the blue dragonflight to secure away from the hands of men. Only they would know exactly where it was taken, or how to retrieve it.\n\nThe dragon Kalec may be our best chance. He now resides upon the Council of Six in Dalaran. Seek him, and your answers, there.", objectives = "Meet Kalec at the Violet Citadel in Dalaran.", completion = "So you seek Light's Wrath? A dangerous weapon, to be sure.\n\nLong ago the Kirin Tor entrusted its safekeeping to the blue dragonflight. It was locked away in the only place that could contain its rampant power  - the Nexus Vault.\n\nI have not been there in some time, however. After the blue dragonflight was dissolved, the Nexus was abandoned. There is no knowing whether the Nexus Vault is still intact - or what may be waiting in the Nexus itself." }
WordHunterWoW_QuestEN[41626] = { title = "A New Threat", description = "If you seek the Nexus, I would warn not to rush headlong. There are strange happenings in Coldarra, and it would be best to gather some information before proceeding.\n\nDuring my last visit to the Dragonblight, I sensed unusual energies from the Azure Dragonshrine. Since this place was very closely tied to Malygos' plans during the Nexus Wars, whatever is present there may explain the current state of the Nexus.\n\nI cannot accompany you, but this crystal can be used to communicate with me. Good luck.", objectives = "Search the Azure Dragonshrine for clues regarding the current state of the Nexus.", completion = "This appears to be a communication device commonly utilized by the ethereals.\n\nPerhaps it could be the key to finding out who is behind the happenings at the Dragonshrine." }
WordHunterWoW_QuestEN[41627] = { title = "A Forgotten Enemy", description = "The device still hums with power. It must have been abandoned not long ago.\n\nThe nearby switch appears to activate it.", objectives = "Activate the Ethereal Communication Device at the Azure Dragonshrine." }
WordHunterWoW_QuestEN[41628] = { title = "Eyes of the Dragon", description = "You should travel at once to Coldarra in Borean Tundra, {name}. There, I would recommend you scout out a few key locations and report back to me. \n\nI know the area well, and should be able to tell you how to proceed.\n\nMake haste!", objectives = "Scout out the key locations in Coldarra." }
WordHunterWoW_QuestEN[41629] = { title = "Harnessing the Holy Fire", description = "The energy from Light's Wrath lashes out from within the weakened Nexus Vault.  We may be able to use this raw, chaotic energy to our advantage.\n\nIf we can harness this energy and feed it into the Surge Needles, it should cause a rather... destructive reaction.", objectives = "Empower yourself with Unstable Holy Energy by defeating Wraths of the Light or siphoning from Breaches of Holy Energy around the foundation of the Nexus." }
WordHunterWoW_QuestEN[41630] = { title = "Unleashing Judgment", description = "You have the power you need to destroy the Surge Needles. \n\nAt the location of the breaches where the Surge Needles pierce the ground, there will be a large concentration of void energy. Focus the power of Light's Wrath into these points of focused void, and the reaction should cause an overload, destroying the Surge Needle above.\n\nYou must act quickly. The Ethereum likely won't sit idly by as you lay waste to their machinations.", objectives = "Use your built up Unstable Holy Energy to destroy the Surge Needles in Coldarra." }
WordHunterWoW_QuestEN[41631] = { title = "The Nexus Vault", description = "If the Ethereum managed to capture Azuregos, then they are more powerful than I imagined. \n\nWe have not always seen eye to eye, Azuregos and I, but he is still my kin. Since you seek to put an end to the ethereals and claim Light's Wrath, I would ask that you also free my brother from their grip.\n\nWith the Surge Needles destroyed, the shield has dissipated. The Nexus awaits, {name}.", objectives = "Defeat Nexus-Prince Bilaal and claim Light's Wrath.", completion = "You have my gratitude for saving Azuregos, <name>. I can rest easy knowing that the Nexus is under his care.\n\nAs for you, I can see you're full of surprises. Never in my time have I seen a <class> who can control the chaotic energies of Light's Wrath. \n\nYou are truly the hero we need to face the Legion." }
WordHunterWoW_QuestEN[41632] = { title = "A Gift of Time", description = "You have done a great thing for the blue dragons today, {name}, as well as for my own peace of mind.\n\nNow, armed with Light's Wrath, I only ask that you fulfill your original goal, and take the fight to the Legion.\n\nI believe Alonsus Faol awaits your return. Safe travels, friend.", objectives = "Speak with Alonsus Faol.", completion = "So the dragons proved helpful? This is good, we may need their assistance in the war to come." }
WordHunterWoW_QuestEN[41633] = { title = "Work Order: Leystone Greaves", description = "", objectives = "Are you here to deliver supplies?", progress = "Are you here to deliver supplies?", completion = "Thank you for assisting us, blacksmith. We needed these greaves badly." }
