WordHunterWoW_QuestEN[41684] = { title = "The Necrodark", description = "Things are worse than I expected.\n\nWe might be in trouble, {name}. With this place all but taken over by the Necrodark, they might have already unleashed the Grey One.", objectives = "" }
WordHunterWoW_QuestEN[41685] = { title = "DANGER: Ala'washte", description = "", objectives = "" }
WordHunterWoW_QuestEN[41686] = { title = "DANGER: Olokk the Shipbreaker", description = "", objectives = "" }
