WordHunterWoW_QuestEN[41688] = { title = "Ursol", description = "", objectives = "" }
WordHunterWoW_QuestEN[41689] = { title = "Cleansing the Mother Tree", description = "We must save the Mother Tree at all costs.\n\nI believe I know a way.\n\nThe world tree Nordrassil, atop Mount Hyjal, was born from an acorn of G'Hanir. We can use the sacred waters surrounding its roots to purify the corruption.\n\nIf we take the Dreamway to Mount Hyjal's summit we should have enough time to complete the cleansing ritual before G'Hanir falls completely to the darkness.", objectives = "Use the Dreamway to travel to Mount Hyjal, then cleanse G'Hanir in the sacred waters beneath Nordrassil.", completion = "We all owe you a great deal for your heroism, <name>. I owe you a great deal.\n\nI suspect this war is far from over." }
WordHunterWoW_QuestEN[41690] = { title = "Reconvene", description = "You found Lyessa in the Dream, didn't you, Shan'do {name}? I heard you mutter her name in your slumber.\n\nThank Elune she is well.\n\nYou must seek her out - I can sense her presence even now at the Circle of Spirits above.\n\nIf ever there were one who could help us cleanse G'Hanir, it is Lyessa.", objectives = "Meet with Lyessa Bloomwatcher at the Circle of Spirits.", completion = "I don't know how much longer I would have lasted had you not arrived - thank you." }
WordHunterWoW_QuestEN[41691] = { title = "Sea of Feathers", description = "", objectives = "" }
