WordHunterWoW_QuestEN[41701] = { title = "Gettin' Tuffer", description = "", objectives = "" }
WordHunterWoW_QuestEN[41702] = { title = "Written in Stone", description = "<You bundle the notes and store them away in your pack.\n\nAccording to his final journal entry, Kel'danath used something called a \"spellstone\" in his experiments.\n\nThe spellstone, if not the arcanist himself, must be nearby.>", objectives = "Retrieve the Spellstone of Kel'danath.", progress = "<This withered seems entranced by the spellstone. He is completely pacified.>", completion = "<A small tag hanging from his sleeve reads \"16 - Theryn.\">" }
WordHunterWoW_QuestEN[41703] = { title = "DANGER: Ormagrogg", description = "", objectives = "" }
WordHunterWoW_QuestEN[41704] = { title = "Subject 16", description = "<It seems Theryn is still under the arcanist's spell. In the absence of Kel'danath himself, a live subject could be useful in helping Thalyssra unravel his research.>", objectives = "Deliver Theryn to Thalyssra.", completion = "So, Kel'danath turned in the end...\n\nHe deserved better. Thank you for giving him peace." }
WordHunterWoW_QuestEN[41705] = { title = "Assault on Thunder Totem", description = "", objectives = "" }
WordHunterWoW_QuestEN[41706] = { title = "Briny Waters", description = "", objectives = "" }
WordHunterWoW_QuestEN[41707] = { title = "Wormtalon Wreckage", description = "As if Shaladrassil's encroaching roots were not enough to deal with, now the Wormtalon harpies have come to take advantage of our plight. \n\nKill them, {race}. They deserve nothing less for feeding on our misery.", objectives = "Slay 15 Wormtalon Harpies in Shadowfen.", completion = "Such violence should not be necessary. Thank you, regardless." }
WordHunterWoW_QuestEN[41708] = { title = "Dark Side of the Moon", description = "Xavius led Ysera past here, but their destination is unclear. This twisted wickedness smothers my mind!\n\nThese refugees tell of an ancient Moonwell hidden in the ruins of their home. If it somehow resisted this corruption...\n\nI will beg of Elune a vision to give me direction. With her light, I may find my husband yet.", objectives = "Protect Tyrande while she holds her vigil at the Ancient Moonwell.", completion = "He is still alive, but the rest remains to be seen." }
WordHunterWoW_QuestEN[41709] = { title = "Breaking Down the Big Guns", description = "You did well against that sea witch, but not well enough.\n\nHer power far surpasses any creature that I have ever fought. To defeat her, we will need something formidable. Something that she will not expect...\n\n<Toryl grins wryly.>\n\nSomething of their own design... \n\nSalvage as many parts from their harpoon launchers as you can carry and meet me back in Jandvik.", objectives = "Collect 50 Harpoon Parts from Sashj'tar Harpooners in Azuregale Bay.", progress = "The Tidemistress is a dangerous foe. We must be just as cunning to defeat her.", completion = "You have all the parts that you will need... two in some cases." }
