WordHunterWoW_QuestEN[41724] = { title = "Heart of the Nightmare", description = "I know only that my husband is somewhere deeper in this twisted forest. He is still alive, but it remains to be seen if he is whole.\n\n<Tyrande's expression hardens into a scowl.>\n\nElune herself cannot protect Xavius if he is not.", objectives = "Track Malfurion's path through the Nightmare.", completion = "No one is safe from this corruption." }
WordHunterWoW_QuestEN[41728] = { title = "The Defense of Tian Monastery", description = "Chen's recent report indicates that Tian Monastery is under attack!\n\n{name}, they need your help. Go speak to Tak-Tak west of the main temple. He can get you there quickly.", objectives = "Travel to the Jade Forest on Pandaria, then speak to Taran Zhu at Tian Monastery. Speak to Tak-Tak west of the Temple of Five Dawns to fly there.", completion = "I did not expect the Grandmaster himself! Your strength will help us turn the tide. We cannot let these demons succeed!" }
WordHunterWoW_QuestEN[41729] = { title = "Slowing the Spread", description = "Reinforcements. Just what we needed! Grandmaster, the monastery is under attack.\n\nThe Legion is using a foul device known as a Fel Spreader to scorch the very earth we walk on with disgusting fel energy.\n\nDestroy those machines, and we can slow their efforts.", objectives = "Destroy 3 Fel Spreaders.", completion = "You did well, little wicket. Stay strong together, that's the ticket! The enemies have tried to spread their taint, but we stopped them with a little restraint!" }
WordHunterWoW_QuestEN[41730] = { title = "Desperate Strike", description = "Good, your timing couldn't have been better, {name}.\n\nThese foul Legion creatures have invaded our sanctuary. They have no place here on our world.\n\nKill every demon you see, brother.", objectives = "Kill 20 demon attackers.", progress = "This is an invasion like none I have ever seen before.", completion = "Good wicket, strong wicket, thanks for helping! You've sent the demons off, groaning and yelping!" }
WordHunterWoW_QuestEN[41731] = { title = "Storm, Earth, and Fire", description = "Tian Monastery is in bad shape.\n\nFelspreader imps are torching the grounds. Fel spikes radiate foul energy, corrupting the nearby earth. And fel magic has seeped into the monastery's ale barrels, tainting the brew.\n\nUse your abilities to snuff the flames, shatter the spikes, and destroy the tainted barrels.\n\nSigh... hundreds of years of the finest ale... ruined.\n\nI don't wish to hear any more of it. Just get it done.", objectives = "Destroy 5 Fel Spikes, put out 5 Fel Fires, and destroy 5 Tainted Ale barrels.", progress = "Is it done?", completion = "The grounds are safe, thanks to you... too bad we couldn't save any of that brew!\n\n<The Monkey King heaves a great sigh.>" }
WordHunterWoW_QuestEN[41732] = { title = "The Hand of Keletress", description = "The demons' leader is up ahead, taking prisoners it is said!\n\nThis dire storm, we will weather... if we fight her together!", objectives = "Kill Skola Greatsword.", completion = "Tian Monastery is safe again, thanks to you." }
WordHunterWoW_QuestEN[41733] = { title = "Rebuilding the Order", description = "On behalf of all the students and teachers here at Tian Monastery, thank you, Grandmaster {name}.\n\nYou have a difficult task ahead of you to rebuild our order, but we stand with you.\n\nLet us head back to the Wandering Isle.", objectives = "Speak to Iron-Body Ponshu at the Wandering Isle.", completion = "Our order's teachings will continue, thanks to you, Grandmaster." }
WordHunterWoW_QuestEN[41734] = { title = "Champion: Taran Zhu", description = "", objectives = "Grandmaster, the stories they tell about you are true. I witnessed your fortitude first hand at Tian Monastery.\n\nMy life and heart are pledged to the <class> order, and we have many battles ahead of us.\n\nLet me be one of your swords. I would be honored to fight for you." }
WordHunterWoW_QuestEN[41735] = { title = "Champion: The Monkey King", description = "", objectives = "Clever <race>, we fought as one, to defend the temple of the rising sun.\n\nA natural leader, you laid enemies low, I'd much rather be your friend than foe!\n\nInto the ring, my hat I toss! Let me fight with you, new boss!" }
WordHunterWoW_QuestEN[41736] = { title = "Champion: Angus Ironfist", description = "", objectives = "It was an honor to see ye in action, Grandmaster <name>. I'm more determined than ever to put an end to Lady Keletress and the Legion forces.\n\nI think we could take the vrykul's Storm Brew and make our own recipe, and use their own weapon against them.\n\nWill ye let me fight by your side?" }
WordHunterWoW_QuestEN[41737] = { title = "Champion: Hiro", description = "", objectives = "Ahhh, it feels good to be back out of  harm's way.\n\nNow dat I've got a couple brews in me, I feel much better.\n\nI owe you my life, Grandmaster. You have my undying loyalty. Just say da word, and I will do whatever you ask of me." }
WordHunterWoW_QuestEN[41738] = { title = "Champion: Sylara Steelsong", description = "", objectives = "<Sylara gazes out the door at the sky beyond. She seems deep in thought, as if thinking about some other, unfinished task. She heaves a small, barely audible sigh.>\n\n<Then, her steely eyes shift and lock on to you.>\n\nMy place is here.\n\nI fight for you." }
WordHunterWoW_QuestEN[41739] = { title = "Champion: Aegira", description = "", objectives = "We have been through quite a lot together, <name>.\n\nWithout your help, I could not have avenged my master, nor found the courage to make her legendary brew.\n\nThanks to you, we should have plenty of Storm Brew to supply the entire temple.\n\nSpeaking of which, I feel there are many similarities between your fighting style and mine.\n\nWould you accept me as the newest member of your order?" }
WordHunterWoW_QuestEN[41740] = { title = "Tech It Up A Notch", description = "There are many ways to commune with the elements. In their ingenuity, the goblins have found ways to imbue their mechanical devices with the energy of elemental spirits. I do not pretend to understand. But in our hour of need, we should not hesitate to embrace a diversity of options.\n\nWe are fortunate to have at our disposal the services of the one they call \"Goldmine,\" whose unorthodox research may significantly augment our power. He waits nearby.", objectives = "Speak to Journeyman Goldmine at the Heart of Azeroth in the Maelstrom.", progress = "What's it gonna be, boss?", completion = "Excellent choice, Farseer. <class> from all over the world have much to learn from one another." }
WordHunterWoW_QuestEN[41741] = { title = "Troops in the Field", description = "It is time for us to test the strength of your newly summoned Lesser Elementals. Look at the Scouting Map and send your champions and troops on a routine scouting mission.", objectives = "Use the Scouting Map and complete the mission, \"Troops in the Field.\"", progress = "How did it go?", completion = "The scouting mission was more successful than we could have imagined, <name>. Your troops were able to rescue Journeyman Goldmine, a... most unusual little <class>.\n\nIn thanks, he has agreed to lend his skill to our cause." }
WordHunterWoW_QuestEN[41742] = { title = "Champion: Celestos", description = "", objectives = "The Windlord has commanded that I shall assist the Earthen Ring in your campaign against the Burning Legion.\n\nLord Thunderaan sees great potential in you, Farseer. As thanks for your help in securing his return as Windlord, he has granted you my services here in the mortal realm.\n\nWhen the time for battle approaches, the armies of Skywall will be at your back." }
WordHunterWoW_QuestEN[41743] = { title = "Champion: Nobundo", description = "", objectives = "Your leadership during this time of crisis has been inspiring, Farseer <name>. It was truly an honor to journey with you through Skywall.\n\nAlthough there are many matters here that require my attention, it would be an honor to fight at your side once again.\n\nShould you have need of my aid once again, I will be yours to command." }
WordHunterWoW_QuestEN[41744] = { title = "Champion: Rehgar Earthfury", description = "", objectives = "I have always respected you for your courage in battle, Farseer.\n\nHowever, the way you have championed the Earthen Ring and united the Elemental Lords... it has been an honor to behold. You truly are a great leader. The leader our order needs!\n\nThough the elements are united against the Burning Legion, our work is not yet done. If you should have need of my abilities, you need only ask.\n\nI live to serve the Earthen Ring!" }
WordHunterWoW_QuestEN[41745] = { title = "Champion: Scaldius", description = "", objectives = "The Firelord has commanded me to aid the mortals in their battle against the Burning Legion.\n\nMy master has decreed that demon invaders have no place upon this world. I live to destroy the enemies of my master.\n\nI will obey your commands as though they are the Firelord's himself. Who shall I destroy first?" }
WordHunterWoW_QuestEN[41746] = { title = "Champion: Muln Earthfury", description = "", objectives = "It was an honor to fight at your side in Deepholm, Farseer. The way you lead our order with courage and determination inspires us all with hope.\n\nYet, I fear that the worst is still ahead of us. You should not bear this burden alone.\n\nGive me the honor of fighting alongside you once more, and I will not let you down." }
WordHunterWoW_QuestEN[41747] = { title = "Champion: Avalanchion", description = "", objectives = "<The deep, thundering words of Avalanchion rumble out slowly as he speaks>\n\nStonemother... send me to help Farseer...\n\nSay crush demons... protect <class>.\n\n\n\nAvalanchion go with Farseer... make demons cry." }
WordHunterWoW_QuestEN[41748] = { title = "Champion: Ritssyn Flamescowl", description = "", objectives = "Rebuilding the council is our key to defeating the Legion, but it's a task that cannot be completed alone.\n\nYou could use someone at your side, someone who's familiar with the burden of leadership.\n\nI would be honored to serve as Second. Through your power and guidance, we can rebuild." }
WordHunterWoW_QuestEN[41749] = { title = "Given to Corruption", description = "A final favor for an old friend, perhaps? My age-old companion, Varethos, has fallen to the nightmare's torment. We once worked in unison to protect this land. His close ties to the land brought him low in this dark hour.\n\nAs with all who suffer this fate, there is no restoring him.\n\nPlease, {name}, bring him peace.", objectives = "Slay Keeper Varethos.", completion = "My sight fades, but I am glad that he rests." }
WordHunterWoW_QuestEN[41750] = { title = "Champion: Calydus", description = "", objectives = "Calydus no longer suffers under the cruel hand of Jagganoth, thanks to friend.\n\nCalydus has a choice who to follow, and he pledges loyalty to the new Overlord!\n\nThat is, if friend is willing to let Calydus help?" }
WordHunterWoW_QuestEN[41751] = { title = "Champion: Kira Iresoul", description = "", objectives = "Your commitment to rebuilding the council is commendable. You could have left Shinfel to die and found a replacement, but you look out for your own.\n\nI followed blindly once before, trusting my mentor to look out for my best interests. Instead, he left me to lead a council that admonished my way of doing things.\n\nFor this, I will never be a follower. Instead, I choose to stand beside you. My power is yours to use as you see fit, if you wish to use it." }
WordHunterWoW_QuestEN[41752] = { title = "Champion: Zinnin Smythe", description = "", objectives = "<Zinnin's gaze meets yours while standing in quiet contemplation. His stare remains steady as he places a fisted hand over his chest, making an unspoken oath.>" }
WordHunterWoW_QuestEN[41753] = { title = "Champion: Jubeka Shadowbreaker", description = "", objectives = "We have to stop meeting like this, <name>. You've saved me more times than I care to admit.\n\nIf you in turn ever need saving, I'll be there to return the favor." }
WordHunterWoW_QuestEN[41754] = { title = "Champion: Shinfel Blightsworn", description = "", objectives = "So Ritssyn appointed you First of our council, did he?\n\nIt seems much has changed in the short time I've been gone.\n\nThe Legion threat is greater than ever. I have witnessed their power firsthand, and know that we cannot defeat them as we are now.\n\nYou will unite us, <name>, and together we will strip the Legion of their power!" }
WordHunterWoW_QuestEN[41755] = { title = "Champion: Lulubelle Fizzlebang", description = "", objectives = "I don't have to hide away in shame anymore, and I have you to thank for that.\n\nIt's a debt I doubt I'll ever be able to repay, but I'd like to try." }
WordHunterWoW_QuestEN[41756] = { title = "Champion: Eredar Twins", description = "", objectives = "We live to serve you, <name>.\n\nIt would please us to do your bidding." }
WordHunterWoW_QuestEN[41757] = { title = "Echoes of the Earth-warder", description = "", objectives = "" }
WordHunterWoW_QuestEN[41758] = { title = "Obsidian Guardians", description = "", objectives = "" }
WordHunterWoW_QuestEN[41759] = { title = "An Unlikely Ally", description = "Channeling the demonic gateway will require the assistance of someone with intimate knowledge of the Burning Legion.\n\nI know of such a warlock, though I imagine her blood still boils upon hearing my name. It might be best if you are the one to request her help.", objectives = "Speak to Kira Iresoul in Azsuna.", completion = "Ritssyn sent you, did he? I see my old mentor still refuses to do his own dirty work.\n\nBut of course, someone in his position can't be seen consorting with a purported member of the Argus Wake! What would the others think?\n\nAs much as I relish the idea of Ritssyn needing my help, I don't barter in kindness and favors, <name>.\n\nMy currency is power and knowledge. If you have either, then it's possible we can come to an arrangement." }
WordHunterWoW_QuestEN[41760] = { title = "Kel'danath's Legacy", description = "Kel'danath discovered something incredible - the power to subdue and even control the withered.\n\nI will pick up where my old friend left off. We shall see to it that he did not die in vain. \n\nPerhaps in the end we can even find peace for the wretches who have been left to a fate worse than death.\n\nI will need more subjects. Take Kel'danath's spellstone and use it to subdue more withered.", objectives = "Use the Spellstone of Kel'danath to charm 5 withered and send them to Shal'Aran.", progress = "We will need more subjects if we are to continue Kel'danath's research.", completion = "Fascinating.\n\nLet us hope the spell holds." }
WordHunterWoW_QuestEN[41761] = { title = "Winter Moose Roundup", description = "My father, Karmaan, owns this farm, and our main livestock are talbuk. One of the podlings must have opened the gate to their pen and they all escaped!\n\nThe little terrors could have slaughtered them in the cage, but they like to hunt their prey. I'm afraid that if I stay out here much longer, I'll be their next meal!\n\nWill you round up the talbuk and bring them here? I can't get them myself, and I can't let my dad find out about this!", objectives = "Rescue 4 Talbuk at Kuuros Farm." }
WordHunterWoW_QuestEN[41762] = { title = "Sympathizers Among the Shal'dorei", description = "Elisande's decision to welcome the Legion into Suramar earned her plenty of enemies, though only some of us were bold enough to openly defy her.\n\nWe have allies in the city - we just don't know how many.\n\nI need you to make contact with a spell-fencer by the name of Silgryn. He is loyal to our cause, and has been lying in wait since our failed coup.\n\nHe patrols the western edge of the city. Address him by name and tell him our cause is not lost!", objectives = "Speak with Silgryn in the Suramar Outskirts.", completion = "We should be safe to speak here for a moment." }
WordHunterWoW_QuestEN[41763] = { title = "Close Enough to Touch", description = "He is near, {race}, I can feel it.\n\nWe must search Shala'nir for Malfurion. If we do not find him soon, I fear he will be lost to me forever.\n\nI was unsure of your worth when first we met. I know now that you will not fail me.\n\nI am... grateful.", objectives = "Search for Malfurion within Shala'nir.", completion = "This cannot be!" }
WordHunterWoW_QuestEN[41764] = { title = "Walking in Their Footsteps", description = "Spiritwalkers maintain balance between the world of the living and the spirit realm. We can travel into the memories of the dead to glean clues about the past.\n\nThe wards Ebonhorn maintained were placed long ago by heroes who fought the darkness. By walking in their footsteps, we may locate the wards and restore them.\n\nIgrul, the drogbar known as the Scalebane, was a true friend to Huln Highmountain. Use the Water of Vision to enter his memories and find where he placed the first ward.", objectives = "Use the Water of Vision to walk in the memories of Igrul the Scalebane.", progress = "As a spiritwalker, I am able to see the memories of the dead.", completion = "I am pleased you were able to place the first ward. We are one step closer to saving Ebonhorn.\n\nBut this mention of the Darkness is unsettling. It is a monster spoken of in our myths and folklore, tales told around campfires to spook the young.\n\nCould these stories be based in truth?" }
WordHunterWoW_QuestEN[41766] = { title = "Wildlife Protection Force", description = "", objectives = "Defeat Rocko in a pet battle." }
WordHunterWoW_QuestEN[41767] = { title = "A Daring Rescue", description = "The plan is a simple one, but it will require great effort on your part.\n\nKira and I will summon the demonic gateway, but you will have to enter alone and recover the missing council members.", objectives = "Enter the demon world and rescue the missing council members.", progress = "Kira and I can sustain the gateway, but you will need to enter the demon world alone.", completion = "Shinfel cannot be broken at the hands of Mephistroth. Armed with her power and knowledge, the dreadlord would be able to mount a devastating attack against Dreadscar Rift.\n\nA ritual of summoning should be able to summon Shinfel to our side, but we'll need to create a powerful anchor." }
WordHunterWoW_QuestEN[41768] = { title = "Soul Beacon", description = "I have bound Shinfel's soul to her staff, allowing it to serve as an anchor in this world.\n\nWhen we perform the ritual of summoning, it will act as a beacon, guiding Shinfel through the Twisting Nether and back to our world.", objectives = "Perform a ritual of summoning to retrieve the missing council member.", progress = "The council cannot be rebuilt without Shinfel.", completion = "We may have Shinfel in our possession, but her mind remains in the hands of her demon captors.\n\nWhat kind of ancient magic have they cursed her with? I've never seen anything like it." }
WordHunterWoW_QuestEN[41769] = { title = "Mad Ernie the Alchemist", description = "If we have any hope of curing this curse, we need to know what kind of magic we're dealing with.\n\nI know of an alchemist who earned himself quite the reputation for his unconventional methods. Shunned from Gilneas long ago, I believe Mad Ernie has taken up residence in these lands.\n\nHis knowledge may be the first step to breaking this curse.", objectives = "Find Mad Ernie the Alchemist in Val'sharah.", progress = "Have you come to lend a hand? We all must do our part.", completion = "That's a name I thought I'd never hear again.\n\nWe may have worked together in the past, but Ritssyn needs to know I'm not the man I was before.\n\nMy priorities are Marl and this farm." }
WordHunterWoW_QuestEN[41770] = { title = "The Skies Above", description = "There has been no Windlord to lead the air elementals since the death of Al'Akir.\n\nThe realm of Skywall has been thrown into turmoil. The throne of Al'Akir is Thunderaan's by right, but what remains of the prince's essence within Thunderfury is diminishing. If we do not move quickly, Thunderaan may be lost forever.\n\nTake the damaged Thunderfury to Vortex Pinnacle and speak with Celestos.\n\nCelestos was a loyal servant of Al'Akir and he will share our desire to see Thunderaan reborn.", objectives = "Speak with Celestos in The Vortex Pinnacle.", completion = "Farseer Nobundo has told me of your plan to save Azeroth. I fear I may be the only zephyr to share your desire." }
WordHunterWoW_QuestEN[41771] = { title = "Recharging the Blade", description = "You have recovered the Blessed Blade of the Windseeker, and with it you hold all that is left of the soul of Prince Thunderaan.\n\nThunderfury can be restored, but it will require a rare essence known as the Heart of Skywall.\n\nVortos, the Duke of the East Winds, possesses the heart... but he will not give it willingly.\n\nVortos must be defeated, and the Heart of Skywall must be combined with the blade.\n\nOnly then can Thunderaan return and claim the Throne of Four Winds.", objectives = "Obtain the Heart of Skywall.", progress = "Have you retrieved the Heart of Skywall?", completion = "At long last, the Windseeker shall return to to his rightful place as heir to the Throne of Four Winds. This is a glorious day for Skywall!" }
WordHunterWoW_QuestEN[41772] = { title = "Ascendant of Flames", description = "As we speak, an endless war rages for control of the Firelands. Of the two aspiring Firelords, Lord Smolderon hates mortals less.\n\nIf we help him defeat his rival and ascend to Firelord, he may unite with us in return.\n\nThe champions of the Earthen Ring have already made their way to the Firelands. Go and meet with Rehgar Earthfury and find a way to turn an old enemy into a new ally.\n\nIf anyone can succeed at this impossible task, I have faith that it is you, Farseer.\n\nMay the elements be with you.", objectives = "Speak with Rehgar Earthfury in the Firelands.", completion = "At last you have arrived, Farseer <name>.\n\nIt seems our presence in the Firelands has not gone unnoticed." }
WordHunterWoW_QuestEN[41773] = { title = "The Firelord's Command", description = "Greetings, mortal. I am Scaldius, emissary of Lord Smolderon.\n\nI have just met with others from your order. They tell me that you will bring an end to those who oppose my master. This pleases Lord Smolderon.\n\nPyroth and his minions defy my master's rule and so an example must be made of them. You will slay Pyroth and his champions!\n\nNothing is more humiliating than death at the hands of a mortal. Do this and Lord Smolderon will grant you audience.", objectives = "Defeat the forces of Pyroth.", progress = "I will devour the heart of Pyroth with great pleasure!", completion = "The son of Rhyolith slain by mere mortals? What an ignominious death!\n\nYou have done well, <class>. This pleases me greatly." }
WordHunterWoW_QuestEN[41774] = { title = "The Rival Lords of Fire", description = "You stand before the true Lord of the Firelands, mortal. This land is mine by right, claimed from the ashes of Ragnaros himself.\n\nHowever, there are still some who foolishly oppose my reign. I would take great pleasure in destroying their worthless souls, but I will not honor them with death by my hands.\n\nThey must be humiliated for their insolence, and there is nothing more humiliating than being slain by a mere mortal.\n\nAmuse me shaman. Prove your worth and destroy my rivals!", objectives = "Return to Lord Smolderon with Garixxia's Smoldering Heart and the Core of Molten Rage." }
WordHunterWoW_QuestEN[41775] = { title = "The Great Stonemother", description = "In order to unite the four Elemental Lords of Azeroth, you will need to seek out Therazane and convince her to join the cause of Azeroth.\n\nHowever, the Stonemother currently has her hands full battling a Twilight's Hammer resurgence in Deepholm.\n\nIf we lend Therazane our aid she may agree to unite with the Earthen Ring against the Burning Legion.\n\nJourney to Therazane's Throne in the heart of Deepholm. Aid her in defeating the Twilight's Hammer and convince her to join the defense of Azeroth!", objectives = "Speak with Therazane in Deepholm.", progress = "What would you have with the Stonemother, <class>?", completion = "The Earthen Ring has come to offer help? This is unexpected... but welcome, nonetheless." }
WordHunterWoW_QuestEN[41776] = { title = "Return of the Windlord", description = "With Thunderfury recharged, Prince Thunderaan can now return to the physical realm.\n\nIn a moment, I will release my master's spirit from the blessed blade.\n\nWhen the ritual is complete, Skywall will once again have its Windlord.", objectives = "Summon Prince Thunderaan.", completion = "At long last, I have returned to Skywall thanks to the help of mortal hands. I owe you a great debt, Farseer." }
WordHunterWoW_QuestEN[41777] = { title = "Destroying the Cult", description = "We are all that stands between the Twilight's Hammer and their conquest of Deepholm.\n\nAzeroth cannot hope to fight the full strength of the Twilight's Hammer and the Burning Legion at the same time. It is up to us to put an end to their cult before they are able to fully rebuild.\n\nAccompany me into their stronghold and we shall cut through their ranks together!", objectives = "Slay 15 Twilight's Hammer cultists at The Twilight Throne.", progress = "How many have you slain? I've lost count.", completion = "The Twilight's Hammer will not soon recover from the damage we've dealt to their numbers this day. It is an honor to battle at your side, Farseer <name>." }
WordHunterWoW_QuestEN[41778] = { title = "Firing Up the Forge", description = "Are you familiar with the Obliterum Forge? It can be used to destroy crafted gear, yielding valuable Obliterum. I'm personally quite curious to see it in action.\n\nOne of my many admirers recently gifted me a set of adventuring robes, but I'm afraid they're not quite my style.\n\nPlace them inside the forge and see what happens.", objectives = "Use the Obliterum Forge to obliterate Archmage Karlain's Imbued Silkweave Robes.", progress = "What are the results, <name>?", completion = "Success! While their interior decoration sensibilities may differ significantly from those of Dalaran's architects, the demon hunters do make an efficient forge.\n\nYou keep the obliterum, <name>. I have a feeling you'll be needing it eventually." }
WordHunterWoW_QuestEN[41779] = { title = "DANGER: Xavrix", description = "", objectives = "Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[41780] = { title = "Doom and Gloom", description = "Doom curses are serious business, so much so that many warlocks didn't deal in them for some time. \n\nThe magic grows stronger as time goes on, eventually leading to death. Only the caster of the curse can remove it.\n\nI can craft an elixir that will slow its progression, but you'll need to collect an assortment of ingredients first.", objectives = "Recover the ingredients Ernest needs to create an Elixir of Suspension.", progress = "Have you found those ingredients yet? Time really isn't on your side, you know.", completion = "This looks like everything I need. Just give me a moment to mix it all together." }
WordHunterWoW_QuestEN[41781] = { title = "Herding Goats", description = "In case you haven't noticed, things are a bit hectic around here.\n\nMarl's doing a good job protecting the corn fields, but the commotion gave our goats quite the scare. They dashed out of their pen as soon as the fighting started, and are now running amuck!\n\nRound them up for me and I'll do my best to figure out how to handle the curse you're dealing with.", objectives = "Catch Greyhorn Goats, then return them to their pen.", progress = "Have you found my goats yet?", completion = "I can see all my goats have been accounted for.\n\nNow, let's see if we can do something about that curse." }
WordHunterWoW_QuestEN[41782] = { title = "To The Hills", description = "It is said that a fragment of Ursoc's spirit, his fury and rage, remained within the claws after his death. Only those who have attained mastery of discipline have any hope of wielding them without being overwhelmed by the bear lord's fury.\n\n<Lea looks intently at you for a moment.>\n\nBut you are no novice, I can see that clearly.\n\nVery well, draw water from the moonwell on the northern edge of the grove then come find me. I'll await your arrival within the broken stump of Vordrassil in Northrend.", objectives = "Fill a Vial of Moonwell Water and locate Lea Stonepaw within Grizzly Hills.", progress = "Did you get the moonwell water? It is essential for our task!", completion = "Excellent! We will need this water to enter the Emerald Dream, but first we need to address the magical wards that protect the claws." }
WordHunterWoW_QuestEN[41783] = { title = "Fallen Offerings", description = "When the claws were sealed away, magical wards were placed to prevent anyone from reaching their location. Only the power of a demigod can give us passage through the wards, one such as Ursol, the brother of Ursoc.\n\nUrsol is a reclusive guardian and requires an offering before he will appear to us.\n\nlike Ursoc, he was worshipped by the furbolg, but years of war have decimated their tribes and their shaman lay dead.\n\nSearch the bodies of the fallen for their offerings while I prepare the shrine.", objectives = "Search the bodies of Frostpaw Shaman for Offerings to Ursol and return them to Lea Stonepaw within Grizzlemaw", progress = "Did you get the offerings?", completion = "Yes, this should work!\n\nI hate rummaging through the pockets of the dead but we need them more than they do.\n\nNow, let's begin." }
WordHunterWoW_QuestEN[41784] = { title = "Borrowed Time", description = "Don't let the aroma deceive you, this concoction is mostly safe for consumption.\n\nWhoever is afflicted should drink the entire contents of the vial, every last drop! If the elixir works, the effects should be immediate. If not, well... just tell them they drink at their own risk, alright?\n\nKeep in mind, this will only weaken the curse, not cure it.", objectives = "Give the Elixir of Suspension to Shinfel Blightsworn.", progress = "Shinfel's curse will kill her soon if we don't find a way to slow its progression.", completion = "Killing a demon isn't always the answer. Sometimes, the solution is to control one, or two as the case may be.\n\nIf we can summon the sisters and bend their will to ours, it will deliver a devastating blow to Mephistroth's forces and rid Shinfel of her curse." }
WordHunterWoW_QuestEN[41785] = { title = "Finding Fizzlebang", description = "I have reason to believe that Wilfred Fizzlebang's sister has made her way to Stormheim.\n\nIf she has half his power, but at least twice his intelligence, then we just might succeed in summoning the eredar twins.", objectives = "Find Lulubelle Fizzlebang in Stormheim.", completion = "You're the council's new leader, aren't you? I could tell by your weapon. I bet you have an amazing story to tell about how you got it.\n\nMy name's Lulubelle, or Lulu for short. But, uh... I'd appreciate if you didn't mention to anyone that you saw me, ok?" }
WordHunterWoW_QuestEN[41786] = { title = "7.0 Suramar - Vignette: Sea Giant King - twh", description = "", objectives = "" }
WordHunterWoW_QuestEN[41787] = { title = "Someone Else's Mess", description = "A confession alone won't be enough to clear my name. As long as those demons run amuck, people will blame their presence on me. \n\nSomeone needs to clean up the mess that warlock made. I'd do it myself, but I can't be placed at the scene of the crime.\n\nYou could banish them though. That would do the trick. Use this orb on newly summoned demons to send them right back where they came from - permanently!", objectives = "Banish demons that have been irresponsibly summoned in Stormheim.", completion = "Thank you, <name>.\n\nYour willingness to help an outcast will not be forgotten." }
WordHunterWoW_QuestEN[41788] = { title = "Coercing a Confession", description = "My location has to be kept secret, at least until I have proof of my innocence.\n\nThanks to the legacy of my family name, any time some miserable warlock summons demons they can't control, I get the blame.\n\nThe scene of my latest \"crime\" is a nearby cave, where unruly imps and other nasty demons are roaming free.\n\nFind the lousy warlock who's responsible, and get him to write a confession.", objectives = "Find the warlock that has been irresponsibly summoning demons and obtain a written confession of his wrongdoings.", completion = "This writing is a bit difficult to decipher, but I think all the pertinent information is included.\n\nArmed with this confession, I should be able to prove my innocence and focus on more pressing matters." }
WordHunterWoW_QuestEN[41789] = { title = "Return to the Crag", description = "", objectives = "" }
WordHunterWoW_QuestEN[41790] = { title = "The First Trial of Ursol", description = "The Legion...\n\n<the glow of Ursol's eyes begin to shine intensely>\n\nYes... I remember clearly that day long ago when my brother fell. Countless demons fell beneath his claws until, through the overwhelming numbers of the enemy, he was overtaken. My brother was the true spirit of the bear!\n\nYou must prove to me that the spirit of the bear resides within you as well.", objectives = "Complete the first of Ursol's trials.", progress = "<The ancient stares at you expectantly.>", completion = "You are powerful indeed, but strength alone will not impress me." }
WordHunterWoW_QuestEN[41791] = { title = "The Second Trial of Ursol", description = "Ursoc never backed down from a battle, even when faced with overwhelming odds. If you would take up his claws you will show me that you possess the same courage.\n\nYour next trial will place you against an onslaught of my followers. Defeat all of the spirits and prove that you possess the courage of the bear!", objectives = "Complete the second of Ursol's trials.", progress = "<The ancient stares at you expectantly.>", completion = "Well done, <name>. You handled yourself with honor!\n\nYou've done well so far, yet a single trial remains before I will give you my blessing." }
WordHunterWoW_QuestEN[41792] = { title = "The Third Trial of Ursol", description = "You've proven to me your strength and your courage, but do you possess the ability to apply yourself when it matters most?\n\nThis final trial will reveal all.", objectives = "Complete the third of Ursol's trials.", progress = "<The ancient stares at you expectantly.>", completion = "You have passed every trial I've placed before you and emerged victorious. You are worthy indeed of my brother's legacy, and have earned my blessing!\n\nGo, seek out the claws and claim them as your own." }
WordHunterWoW_QuestEN[41793] = { title = "Lulubelle on Loan", description = "What you plan to do is pretty risky, you know? Summoning one sister would be difficult enough, but both of them at once? That's just asking for trouble.\n\nLuckily, I'm up for the challenge. I'll help you and the rest of the council summon those demons, and hopefully restore pride to the Fizzlebang name.", objectives = "Speak to Ritssyn Flamescowl.", completion = "With Lulubelle's assistance, we should be able to complete the summoning." }
WordHunterWoW_QuestEN[41794] = { title = "Drakestalker", description = "", objectives = "" }
WordHunterWoW_QuestEN[41795] = { title = "Summoning the Sisters", description = "It would be best to conduct the summoning on the outskirts of Dreadscar Rift. If things do not go as planned, at least the aftermath will be contained to a small island of land that floats above our order.\n\nOnce the sisters have been summoned, use the Bloodstone to enslave them.\n\nI'll let the others know it's time to begin.", objectives = "Travel through the Demonic Gateway to reach the summoning platform and use the Bloodstone to subdue the eredar sisters once the summoning is complete.", completion = "You did it, <name>. The demon twins are under your control.\n\nI have not witnessed such power since the fall of Ragnaros." }
WordHunterWoW_QuestEN[41796] = { title = "Selecting a Sixth", description = "With the demon sisters under your control, you have managed to weaken Mephistroth's army and gain powerful allies for the council.\n\nOur work is not done, however. Dreadscar Rift will remain a target as long as the Burning Legion remains.\n\nIf we wish to protect our new home, we must rebuild the council. Both Lulubelle and Kira have proven themselves worthy to join our ranks, though only one spot remains.\n\nAs First of the Black Harvest, the choice is yours.", objectives = "Choose who will become the final member of the council.", progress = "The choice may not be easy, but it is yours to make.", completion = "And so the choice is made." }
WordHunterWoW_QuestEN[41797] = { title = "Recruiting The Troops", description = "As her name suggests, Imp Mother Dyala is adept at summoning imps.\n\nWhile the council controls Dreadscar Rift, her services will be ours to use as we see fit.\n\nSpeak to her if you wish to train a pack of imps.", objectives = "Speak to Imp Mother Dyala and train a Pack of Imps.", progress = "How did the training go?", completion = "Excellent. These troops will be invaluable in our defense of the Broken Isles. Deploy them on missions, just as you would with our champions." }
WordHunterWoW_QuestEN[41798] = { title = "Recruiting More Troops", description = "As First of the council, you have acolytes devoted to helping any way they can. Recruiter Jared is in charge of screening candidates, only selecting those that possess the skills we desire.\n\nSpeak to him now.", objectives = "Speak to Recruiter Jared.", completion = "I'm here to help build you an army, <name>." }
WordHunterWoW_QuestEN[41799] = { title = "Minions of the Darkness", description = "Oenia Skyhorn was a legendary chieftain of her tribe. Though she crossed over to the spirit realm long ago, her presence is still felt all around us.\n\nEbonhorn told me that Oenia placed a ward here to protect the people she cared for so deeply... perhaps from the specter of the Darkness.\n\nUse the Water of Vision to journey into her echoes. Worry not that this ritual might disturb her rest. A hero like Oenia would relish a chance to aid us in the present.", objectives = "Use the Water of Vision to walk in the memories of Oenia Skyhorn.", progress = "The spirits speak of the Darkness. A great danger rises, <name>.", completion = "These shadows of the spirit realm grow stronger. I fear they may soon pierce the veil into our reality.\n\nI pray restoring the wards will set things right." }
WordHunterWoW_QuestEN[41800] = { title = "Servants of the Darkness", description = "The heroes of Highmountain's past placed wards to protect our land from the insidious Old Gods. The deeds of these noble champions kept us safe for thousands of years.\n\nWe must not fail their memory.\n\nHuln Highmountain himself placed the ward here at Snowblind Mesa. It must be reactivated for us to have any hope of saving Ebonhorn.\n\nEnter the echo of Huln's spirit, and let his courage lead you to the location of this ward.", objectives = "Use the Water of Vision to walk in the memories of Huln Highmountain.", completion = "Huln battled the Necrodark?\n\nThere are so many tall tales attributed to Huln that I assumed those drogbar to be just another story. But it is clear they served the Darkness.\n\nA troubling discovery... but there is no time to dwell on it now." }
WordHunterWoW_QuestEN[41802] = { title = "The Gates of Valor", description = "Ye'd not normally know it, but the terraced entrance to the vrykul's Halls o' Valor is a fine place for findin' ancient artifacts. Problem is, the place is just a big mess with demons at the time.\n\nWell, ye've not got much choice. If the disc isn't elsewhere in Stormheim, it most likely lies at the Gates of Valor. Good luck, {name}.", objectives = "Obtain 6 Chipped Titan Disc Fragments by surveying near the Gates of Valor in Stormheim.", progress = "Ye're back in one piece. What's the news?", completion = "Alright, let's see what ye brought me.\n\n<Brann examines the disc pieces.>\n\nWell look at this? There's a piece o' somethin' fel here. I betcha that's what was causin' all those imps ta show up 'round here.\n\nI'll give it to ya to dispose of, or do whatever it is ye do with things like that." }
WordHunterWoW_QuestEN[41803] = { title = "Asking a Favor", description = "Caria Felsoul was a bright student... and a Legion traitor.\n\nIn her treason she was bestowed the Aldrachi Warblades, the soul-rending blades of the Aldrachi's greatest champion - they say he only finally fell to Sargeras himself.\n\nWe sent a small force to find Caria, but we have not heard word since. Jace has a Legion communicator he believes we can use to reach them- we just need a power source.\n\nPerhaps you could see if Khadgar has anything we could use? I'm afraid our allies are few.", objectives = "Ask Khadgar for a source to power the Legion communicator.", completion = "It's good to see you again. If there's anything I can do to help you take the fight to the Legion, just let me know." }
WordHunterWoW_QuestEN[41804] = { title = "Ask and You Shall Receive", description = "A Legion communicator? Hmmmm.\n\n<Khadgar pauses to think for a moment.>\n\nYou know what, I think I have something in my lockbox upstairs that is just the ticket.", objectives = "Obtain the Crystallized Soul from Archmage Khadgar.", progress = "I'm always happy to help a friend.", completion = "No need to thank me, just promise you won't accidentally blow anything up in the city; our repair bills are already astronomical." }
WordHunterWoW_QuestEN[41805] = { title = "Key of Kalyndras", description = "", objectives = "" }
WordHunterWoW_QuestEN[41806] = { title = "Return to Jace", description = "That crystallized soul should power your communicator long enough to reach your allies.\n\nI must urge you to be cautious, {name}. If that device is of Legion origin, then you never know who among its creators might overhear your message.\n\nI'm sure your allies eagerly await your return.", objectives = "Return to Jace Darkweaver.", completion = "Did the Archmage have anything of use?" }
WordHunterWoW_QuestEN[41807] = { title = "Establishing a Connection", description = "<Jace glances at the crystallized soul.>\n\nYes, that will do nicely. Release its energy to activate the communicator - it should already be configured to contact Allari and her forces.\n\nIf Caria is out there, we will find her, and we will make her suffer for her transgressions.", objectives = "Activate the Legion Communicator and receive Allari the Souleater's report.", progress = "This may be our only chance at revenge against Caria. Every moment is precious.", completion = "Not good... not good at all." }
WordHunterWoW_QuestEN[41812] = { title = "Tracking Quest: Saw Boss Cinematic", description = "", objectives = "" }
WordHunterWoW_QuestEN[41815] = { title = "Curse of the Necrodark", description = "It is clear that the Old Gods have long sought to control Highmountain. Their covetous desire speaks to the power of this land, and the strength of the spirits that echo through its peaks and valleys.\n\nThey will not take our sacred mountain, {name}. Not while I draw breath.\n\nWith the Highmountain tribes united, and with Baine Bloodhoof at our side, we will defeat the Darkness... once and for all.\n\nCome. Let us take back the summit from the forces that would corrupt it.", objectives = "Journey to Highmountain Summit.", completion = "Mayla charged ahead with Ebonhorn. Now they're cut off from the rest of us.\n\nThis is bad, <name>." }
