WordHunterWoW_QuestEN[41834] = { title = "The Masks We Wear", description = "Many nightborne had pinned their hopes on Thalyssra deposing the Grand Magistrix. Since she disappeared, dissenting voices have grown silent.\n\nWe must spread the word, discreetly, among the populace. Ly'leth Lunastre will be a perfect ally in this. She is a socialite with many connections, and she is no friend of the Legion.\n\nLy'leth hosts a masquerade party at her estate where rumors are traded like coin - and brandished like daggers.\n\nLet us invite ourselves in.", objectives = "Speak with 8 Masqued Revelers while in costume, then speak with Ly'leth Lunastre.", progress = "Pleased to make your acquaintance.", completion = "That mask suits you.\n\nIn Suramar, it can be quite advantageous to be someone else for a time..." }
WordHunterWoW_QuestEN[41835] = { title = "Deworming", description = "", objectives = "" }
WordHunterWoW_QuestEN[41836] = { title = "WANTED: Bodash the Hoarder", description = "", objectives = "" }
WordHunterWoW_QuestEN[41837] = { title = "Rockaway Bully", description = "", objectives = "" }
WordHunterWoW_QuestEN[41838] = { title = "WANTED: Slumber", description = "", objectives = "" }
WordHunterWoW_QuestEN[41839] = { title = "The Taken", description = "When Mayla's father was taken, so were the corpses of several of our greatest chieftains.\n\nThe Grey One, even now, is priming Mayla's father to be a vessel for his evil agenda.\n\nBut the others have already been taken by the necrodark, their corpses now vessels for malevolent drogbar spirits.\n\nI will be honest, I do not think my skills could defeat these monstrosities.\n\nWe need your help!", objectives = "Defeat the Taken Chieftains." }
WordHunterWoW_QuestEN[41840] = { title = "Ice and Shadow", description = "We took down one of the Necrodark. Ebonhorn found that it held a shard of ice infused with shadow essence.\n\nPerhaps the villains are using these shards as a kind of talisman. I suggest you deprive them of their trinkets.\n\nI know little of such magics, but it seemed that Ebonhorn had a use for them in mind.", objectives = "Collect 20 Shadowice Shards.", progress = "Did you find more of the shards?", completion = "Perfect timing, <name>. These shards will prove very useful in what I'm about to do." }
WordHunterWoW_QuestEN[41841] = { title = "The Final Ward", description = "The Necrodark are readying their ritual to give physical form to the Darkness. They've sealed themselves inside and barred our way.\n\nThe shards you brought me should provide the means to bring down the barrier. Once it is done, we have to act quickly. We must restore the final ward before the Darkness can manifest.\n\nDo not hesitate. The fate of Highmountain itself hangs in the balance.", objectives = "Restore the Summit Ward.", progress = "This is the hardest challenge I have ever had to face.", completion = "We failed! The ward is shattered.\n\nI sense the Darkness rising..." }
WordHunterWoW_QuestEN[41842] = { title = "Bottom of the Food Chain", description = "", objectives = "" }
WordHunterWoW_QuestEN[41843] = { title = "Bad Luck, Puck", description = "", objectives = "" }
WordHunterWoW_QuestEN[41844] = { title = "WANTED: Sekhan", description = "", objectives = "" }
WordHunterWoW_QuestEN[41845] = { title = "The Tribes Must Be Warned", description = "Though he lacks a corporeal form, do not assume the Grey One to be weak. \n\nLegends speak of him using the bodies of the dead as vessels for his dark magic. If true, this may be the next stage of his plan.\n\nMayla must be warned of what has transpired here. Now that he has been freed, the Grey One means to doom us all.\n\nSay the word and I can return us quickly to Thunder Totem.", objectives = "" }
WordHunterWoW_QuestEN[41846] = { title = "Power in a Vessel", description = "The Grey One is real! I always thought he was some ghost story told to young calves to keep them out of caves.\n\nWe must go to my father's burial chamber immediately!", objectives = "" }
WordHunterWoW_QuestEN[41848] = { title = "Legion Invaders", description = "", objectives = "" }
WordHunterWoW_QuestEN[41849] = { title = "The Iron Fist", description = "It's time to send a rescue operation to the Gates of Valor, {name}.\n\nI will prepare our troops and send them at once. We will need a sizable army to take on the massive Legion force in Stormheim.\n\nGrandmaster, go ahead whenever you are ready. I will send our forces to meet you in the field.", objectives = "Speak to Angus Ironfist at Tideskorn Warcamp in Stormheim.", completion = "They made you Grandmaster, eh? Well, I was busy anyway!\n\nAnyway, I managed to escape from those fel-drinking dirt-kickers across the road, but our own are still in trouble.\n\nThose Legion worms are goin' ta sacrifice the prisoners for their souls.\n\nWe've got ta help them!" }
WordHunterWoW_QuestEN[41850] = { title = "The Master of Swords", description = "I got bad news fer ya - we don't have time to wait for reinforcements. They're sacrificin' prisoners now! Every minute we wait here jabberin' is another life on the line!\n\nFirst things first, my friend Sylara is being held captive in the camp just across the road.\n\nWe need ta free her - she'll be a valuable ally.\n\nWe've got ta move move move!", objectives = "Collect Dravax's Key from Dravax, then free Sylara Steelsong.", progress = "Something need punching?", completion = "Good, ye did it. Sylara is worth ten well-trained monks." }
WordHunterWoW_QuestEN[41851] = { title = "Quelling the Tide", description = "<Sylara looks at you with determined eyes.>\n\nOur friends are in danger. We will save them. Kill any Legion in the way.", objectives = "Kill 16 Legion defenders at the Gate of Valor.", progress = "<Sylara nods at you.>", completion = "<Sylara bows deeply.>\n\nWell fought." }
WordHunterWoW_QuestEN[41852] = { title = "No Monk Left Behind", description = "Most of the prisoners are being held in the main camp at the Gates of Valor.\n\nOur people have been beaten and tortured, and worse still awaits for them if we don't save them.\n\nFind the cages within the main camp and free as many monks as you can find.\n\nI'll be right beside you, knocking heads and taking names!", objectives = "Free 6 Tortured Prisoners.", progress = "Did we free them all?", completion = "Good work, Grandmaster!\n\nThat should be all of them." }
WordHunterWoW_QuestEN[41853] = { title = "Zero to Hiro", description = "I have a favor to ask of you, {name}. My good friend Hiro is still somewhere inside the main camp.\n\nOnly problem is, the Gates of Valor are swarming with the biggest, baddest, nastiest Legion creatures I've ever seen. If we walk in there, we'll just get slaughtered.\n\nBut I've seen these vrykul chugging some kind of special brew called Storm Brew. It's some kind of combat tonic that makes them bigger and stronger.\n\nLet's steal some of that drink, then storm in to save Hiro!", objectives = "Steal a Storm Brew, then save Hiro.", completion = "Ahhh, tanks be to ya for freein' me. I thot I was demon-food for sure." }
WordHunterWoW_QuestEN[41854] = { title = "Brick By Brick", description = "Da monks be free, and we put a thorn in dat eredar lady's side.\n\nI'm back wit my friends, and lookin' forward to sleepin' in a bed tonight.\n\nLet's go back ta da Wanderin' Isle. I've never been so excited ta see a turtle in my life.", objectives = "Return to Iron-Body Ponshu on the Wandering Isle.", completion = "This is fantastic news, <name>!\n\nNot only have you disrupted the Legion's plans, but you've saved the lives of numerous people.\n\nIn addition, you rescued three of the greatest monks we've trained in recent history.\n\nThe order is indebted to you once again." }
